-- >>> 20260927000100_extensions.sql
-- =============================================================================
-- NomadCare v2 — 0100 extensions & private schema
-- Owner: P1 database. Idempotent (safe to re-run in the Supabase SQL Editor).
-- postgis + pgcrypto are REQUIRED. pg_cron + pg_net are OPTIONAL: if the server
-- does not offer them, this file still succeeds and the dead-man cron is simply
-- not scheduled (see 0800_cron.sql and supabase/README.md).
-- =============================================================================
set search_path = public, extensions;

create schema if not exists extensions;

-- Required -------------------------------------------------------------------
create extension if not exists pgcrypto with schema extensions;  -- digest(), gen_random_bytes()
create extension if not exists postgis  with schema extensions;  -- geography, ST_*

-- Optional: pg_cron (job scheduler) -------------------------------------------
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    return;
  end if;
  if not exists (select 1 from pg_available_extensions where name = 'pg_cron') then
    raise notice 'pg_cron is not available on this server: skipping (dead-man cron will not be scheduled)';
    return;
  end if;
  begin
    -- Supabase installs pg_cron into pg_catalog (its objects live in schema "cron").
    execute 'create extension if not exists pg_cron with schema pg_catalog';
  exception when others then
    begin
      execute 'create extension if not exists pg_cron';
    exception when others then
      raise notice 'pg_cron could not be enabled (%): enable it in Dashboard > Database > Extensions, then create the cron jobs (supabase/README.md, Bước 5) or re-run the whole setup_all.sql — never 0800_cron.sql alone', sqlerrm;
    end;
  end;
end $$;

-- Optional: pg_net (async HTTP from SQL, used to call the Edge Function) -----
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_net') then
    return;
  end if;
  if not exists (select 1 from pg_available_extensions where name = 'pg_net') then
    raise notice 'pg_net is not available on this server: skipping (alerts must be triggered from the dashboard)';
    return;
  end if;
  begin
    execute 'create extension if not exists pg_net with schema extensions';
  exception when others then
    begin
      execute 'create extension if not exists pg_net';
    exception when others then
      raise notice 'pg_net could not be enabled (%): enable it in Dashboard > Database > Extensions', sqlerrm;
    end;
  end;
end $$;

-- Private schema: NOT exposed through the Data API (PostgREST) -----------------
create schema if not exists app_private;
revoke all on schema app_private from public;
do $$
begin
  -- Supabase API roles exist on every Supabase project; guard for plain Postgres.
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on schema app_private from anon, authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant usage on schema app_private to service_role';
  end if;
end $$;

-- >>> 20260927000200_schema.sql
-- =============================================================================
-- NomadCare v2 — 0200 schema: tables, constraints, indexes, row triggers
-- Owner: P1 database. Contract: CONTRACT.md §9 (names are the contract).
-- Text columns + CHECK constraints are used instead of enums (easier to evolve).
-- Coordinates are stored as geography(…,4326); JSON APIs expose [lat,lng].
-- Idempotent: "if not exists" everywhere, triggers are dropped/re-created.
-- =============================================================================
set search_path = public, extensions;

-- ------------------------------------------------------ reference data ----
create table if not exists public.carriers (
  id    text primary key,
  name  text not null,
  sort  int  not null default 0
);

create table if not exists public.routes (
  id             text primary key,
  name           text not null,
  name_en        text,
  region         text,
  travel_mode    text not null default 'motorbike'
                 check (travel_mode in ('motorbike', 'hiking', 'mixed')),
  length_km      numeric check (length_km is null or length_km >= 0),
  color          text,
  description_vi text,
  description_en text,
  geom           geography(LineString, 4326),
  bbox           jsonb,             -- [south, west, north, east]; computed from geometry when null
  sort           int not null default 0,
  is_active      boolean not null default true,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

create table if not exists public.route_nodes (
  id        text primary key,
  route_id  text not null references public.routes (id) on delete cascade,
  name      text not null,
  name_en   text,
  kind      text not null default 'poi'
            check (kind in ('town', 'junction', 'pass', 'trailhead', 'village', 'viewpoint', 'poi')),
  geom      geography(Point, 4326) not null
);

create table if not exists public.route_edges (
  id            text primary key,
  route_id      text not null references public.routes (id) on delete cascade,
  from_node     text not null references public.route_nodes (id) on delete cascade,
  to_node       text not null references public.route_nodes (id) on delete cascade,
  length_km     numeric not null check (length_km >= 0),   -- filled from geom when omitted
  is_connector  boolean not null default false,
  geom          geography(LineString, 4326) not null
);

-- ------------------------------------------------------------ signal ----
create table if not exists public.signal_samples (
  id            bigint generated by default as identity primary key,
  route_id      text not null references public.routes (id) on delete cascade,
  edge_id       text references public.route_edges (id) on delete set null,
  carrier       text not null references public.carriers (id),
  tech          text check (tech in ('5G', '4G', '3G', '2G', 'none')),
  rsrp_dbm      int check (rsrp_dbm is null or rsrp_dbm between -160 and -20),
  level         text not null check (level in ('likely', 'uncertain', 'lost')),  -- derived from rsrp when omitted
  geom          geography(Point, 4326) not null,
  measured_at   timestamptz not null default now(),
  source        text not null default 'team' check (source in ('team', 'community')),
  status        text not null default 'approved' check (status in ('approved', 'pending', 'rejected')),
  device_model  text,
  is_holdout    boolean not null default false,
  created_at    timestamptz not null default now()
);

create table if not exists public.signal_segments (
  id             bigint generated by default as identity primary key,
  route_id       text not null references public.routes (id) on delete cascade,
  edge_id        text not null references public.route_edges (id) on delete cascade,
  carrier        text not null references public.carriers (id),
  seq            int not null default 0,
  from_km        numeric not null check (from_km >= 0),
  to_km          numeric not null,
  level          text not null check (level in ('likely', 'uncertain', 'lost')),
  confidence     numeric check (confidence is null or confidence between 0 and 1),
  model_version  text,
  created_at     timestamptz not null default now(),
  constraint signal_segments_range check (to_km >= from_km)
);

create table if not exists public.route_accuracy (
  route_id       text not null references public.routes (id) on delete cascade,
  carrier        text not null references public.carriers (id),
  accuracy       numeric check (accuracy is null or accuracy between 0 and 1),
  holdout_n      int check (holdout_n is null or holdout_n >= 0),
  model_version  text,
  computed_at    timestamptz not null default now(),
  primary key (route_id, carrier)
);

-- ------------------------------------------------ facilities & services ----
create table if not exists public.facilities (
  id              text primary key default gen_random_uuid()::text,
  route_id        text references public.routes (id) on delete set null,
  name            text,
  type            text check (type in ('tram_y_te', 'phong_kham', 'benh_vien', 'nha_thuoc')),
  address         text,
  geom            geography(Point, 4326),
  phone           text,
  open_hours      text,
  night_shift     boolean,
  trauma_capable  boolean,
  verified_by     text,            -- name of the person who answered the verification call
  verified_at     date,
  status          text not null default 'pending' check (status in ('verified', 'pending', 'rejected')),
  source          text not null default 'team' check (source in ('team', 'community')),
  notes           text,
  is_demo         boolean not null default true,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

-- PDF 8.1: a record only counts as verified when EVERY field is present;
-- otherwise it stays pending and is never published to devices.
do $$
begin
  if not exists (select 1 from pg_constraint
                 where conname = 'facilities_verified_complete'
                   and conrelid = 'public.facilities'::regclass) then
    alter table public.facilities add constraint facilities_verified_complete check (
      status <> 'verified' or (
            nullif(btrim(name), '')        is not null
        and nullif(btrim(address), '')     is not null
        and geom                           is not null
        and type                           is not null
        and nullif(btrim(open_hours), '')  is not null
        and night_shift                    is not null
        and trauma_capable                 is not null
        and nullif(btrim(phone), '')       is not null
        and nullif(btrim(verified_by), '') is not null
        and verified_at                    is not null
      )
    );
  end if;
end $$;

create table if not exists public.services (
  id               text primary key default gen_random_uuid()::text,
  route_id         text references public.routes (id) on delete set null,
  name             text not null,
  type             text not null check (type in ('lodging', 'repair', 'fuel', 'rental')),
  geom             geography(Point, 4326),
  phone            text,
  open_hours       text,
  is_partner       boolean not null default false,  -- non-medical partners only (PDF C.2)
  commission_rate  numeric not null default 0 check (commission_rate >= 0),
  status           text not null default 'active' check (status in ('active', 'inactive')),
  notes            text,
  is_demo          boolean not null default true,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

create table if not exists public.facility_submissions (
  id           text primary key default gen_random_uuid()::text,
  device_id    uuid,                -- anonymous device id (no FK: devices may be purged)
  facility_id  text,                -- target facility for correction/closed (no FK: keeps history)
  kind         text not null check (kind in ('new', 'correction', 'closed', 'signal_report')),
  payload      jsonb not null default '{}'::jsonb,
  lat          double precision check (lat is null or lat between -90 and 90),
  lng          double precision check (lng is null or lng between -180 and 180),
  status       text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  review_note  text,
  reviewed_by  uuid,
  reviewed_at  timestamptz,
  created_at   timestamptz not null default now()
);

-- -------------------------------------------------- publishing & content ----
create table if not exists public.data_packs (
  id            bigint generated by default as identity primary key,
  route_id      text not null references public.routes (id) on delete cascade,
  carrier       text not null references public.carriers (id),
  version       int not null check (version > 0),
  published_at  timestamptz not null default now(),
  published_by  uuid,
  notes         text,
  size_bytes    int,
  checksum      text,               -- sha256 hex of payload::text
  payload       jsonb,              -- Pack JSON (CONTRACT §8)
  is_current    boolean not null default true,
  constraint data_packs_route_carrier_version_key unique (route_id, carrier, version)
);

create table if not exists public.content_releases (
  id               bigint generated by default as identity primary key,
  version          text not null unique,
  kind             text not null default 'medical',
  status           text not null default 'draft'
                   check (status in ('draft', 'in_review', 'approved', 'retracted')),
  notes            text,
  reviewer_round1  text,            -- team member who compiled & cross-checked sources
  approver         text,            -- medical advisor who signs round 2
  approved_at      timestamptz,
  created_at       timestamptz not null default now()
);

do $$
begin
  if not exists (select 1 from pg_constraint
                 where conname = 'content_releases_approved_signed'
                   and conrelid = 'public.content_releases'::regclass) then
    -- PDF 8.1: content without the round-2 signature must not be released.
    alter table public.content_releases add constraint content_releases_approved_signed
      check (status <> 'approved' or (nullif(btrim(approver), '') is not null and approved_at is not null));
  end if;
end $$;

-- ------------------------------------------------------ devices & buddy ----
create table if not exists public.devices (
  id            uuid primary key default gen_random_uuid(),
  secret_hash   text,               -- sha256 hex of the device secret (secret itself never stored)
  carrier       text,
  app_version   text,
  created_at    timestamptz not null default now(),
  last_seen_at  timestamptz
);

create table if not exists public.device_ops (
  id           uuid primary key,    -- outbox op id generated on the device (idempotency key)
  device_id    uuid not null references public.devices (id) on delete cascade,
  op           text not null,
  received_at  timestamptz not null default now(),
  result       jsonb
);

create table if not exists public.buddy_sessions (
  id                    uuid primary key default gen_random_uuid(),  -- generated on the device (offline-first)
  device_id             uuid references public.devices (id) on delete set null,
  traveler_name         text,
  recipient_name        text,
  recipient_email       text,
  recipient_phone       text,
  interval_min          int not null default 60 check (interval_min > 0),
  grace_min             int not null default 15 check (grace_min >= 0),
  route_id              text,
  travel_mode           text,
  share_public_medical  boolean not null default false,
  public_medical        jsonb,       -- ONLY the consented public layer; null unless share_public_medical
  status                text not null default 'active'
                        check (status in ('active', 'overdue', 'alerted', 'closed')),
  started_at            timestamptz not null default now(),
  last_checkin_at       timestamptz,
  next_due_at           timestamptz,
  last_lat              double precision check (last_lat is null or last_lat between -90 and 90),
  last_lng              double precision check (last_lng is null or last_lng between -180 and 180),
  last_location_at      timestamptz,
  alerted_at            timestamptz,
  closed_at             timestamptz,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  constraint buddy_sessions_medical_consent
    check (share_public_medical or public_medical is null)
);

create table if not exists public.checkin_events (
  id           uuid primary key default gen_random_uuid(),
  session_id   uuid not null references public.buddy_sessions (id) on delete cascade,
  device_id    uuid,
  kind         text not null check (kind in ('start', 'checkin', 'location', 'pre_deadzone', 'sos', 'overdue',
                                             'alert_sent', 'alert_failed', 'stop', 'resolved')),
  lat          double precision check (lat is null or lat between -90 and 90),
  lng          double precision check (lng is null or lng between -180 and 180),
  accuracy_m   numeric,
  client_ts    timestamptz,
  received_at  timestamptz default now(),
  queued       boolean not null default false,
  note         text,
  meta         jsonb
);

-- ------------------------------------------------------ admin & audit ----
create table if not exists public.admin_users (
  user_id       uuid primary key references auth.users (id) on delete cascade,
  display_name  text,
  role          text not null default 'admin' check (role in ('admin', 'reviewer')),
  created_at    timestamptz not null default now()
);

create table if not exists public.audit_log (
  id           bigint generated by default as identity primary key,
  actor        uuid,
  actor_label  text,
  action       text not null,
  entity       text not null,
  entity_id    text,
  details      jsonb,
  created_at   timestamptz not null default now()
);

create table if not exists app_private.settings (
  key    text primary key,   -- functions_url | cron_secret | anon_key (optional)
  value  text
);
revoke all on app_private.settings from public;

-- ------------------------------------------------------------ indexes ----
-- Spatial (GiST) indexes on every geography column.
create index if not exists routes_geom_gix            on public.routes         using gist (geom);
create index if not exists route_nodes_geom_gix       on public.route_nodes    using gist (geom);
create index if not exists route_edges_geom_gix       on public.route_edges    using gist (geom);
create index if not exists signal_samples_geom_gix    on public.signal_samples using gist (geom);
create index if not exists facilities_geom_gix        on public.facilities     using gist (geom);
create index if not exists services_geom_gix          on public.services       using gist (geom);

-- B-tree indexes on foreign keys, status filters and the cron hot path.
create index if not exists route_nodes_route_idx          on public.route_nodes (route_id);
create index if not exists route_edges_route_idx          on public.route_edges (route_id);
create index if not exists route_edges_from_idx           on public.route_edges (from_node);
create index if not exists route_edges_to_idx             on public.route_edges (to_node);
create index if not exists signal_samples_route_carrier_idx on public.signal_samples (route_id, carrier);
create index if not exists signal_samples_edge_idx        on public.signal_samples (edge_id);
create index if not exists signal_samples_carrier_idx     on public.signal_samples (carrier);
create index if not exists signal_samples_status_idx      on public.signal_samples (status);
create index if not exists signal_segments_lookup_idx     on public.signal_segments (route_id, carrier, edge_id, seq);
create index if not exists signal_segments_edge_idx       on public.signal_segments (edge_id);
create index if not exists signal_segments_carrier_idx    on public.signal_segments (carrier);
create index if not exists route_accuracy_carrier_idx     on public.route_accuracy (carrier);
create index if not exists facilities_route_idx           on public.facilities (route_id);
create index if not exists facilities_status_idx          on public.facilities (status);
create index if not exists facilities_type_idx            on public.facilities (type);
create index if not exists services_route_idx             on public.services (route_id);
create index if not exists services_status_idx            on public.services (status);
create index if not exists facility_submissions_status_idx   on public.facility_submissions (status, created_at desc);
create index if not exists facility_submissions_device_idx   on public.facility_submissions (device_id);
create index if not exists facility_submissions_facility_idx on public.facility_submissions (facility_id);
create index if not exists data_packs_route_carrier_idx   on public.data_packs (route_id, carrier, version desc);
create index if not exists data_packs_carrier_idx         on public.data_packs (carrier);
create unique index if not exists data_packs_one_current_uidx
  on public.data_packs (route_id, carrier) where is_current;
create index if not exists content_releases_status_idx    on public.content_releases (status, approved_at desc);
create index if not exists device_ops_device_idx          on public.device_ops (device_id, received_at desc);
create index if not exists device_ops_received_idx        on public.device_ops (received_at);
create index if not exists buddy_sessions_device_idx      on public.buddy_sessions (device_id, started_at desc);
create index if not exists buddy_sessions_status_idx      on public.buddy_sessions (status);
create index if not exists buddy_sessions_next_due_idx    on public.buddy_sessions (next_due_at) where status = 'active';
create index if not exists checkin_events_session_idx     on public.checkin_events (session_id, client_ts desc);
create index if not exists checkin_events_kind_idx        on public.checkin_events (kind);
create index if not exists audit_log_created_idx          on public.audit_log (created_at desc);
create index if not exists audit_log_entity_idx           on public.audit_log (entity, entity_id);
create index if not exists audit_log_actor_idx            on public.audit_log (actor);

-- ------------------------------------------------------------ helpers ----
-- "Today" in Vietnam. The database runs in UTC, but facility freshness
-- (is_stale = verified > 90 days ago, days_since_verified) is a calendar
-- notion for Vietnamese users and must match the app's local-date maths.
create or replace function app_private.today_vn()
returns date
language sql
stable
set search_path = public, extensions, pg_temp
as $$
  select (now() at time zone 'Asia/Ho_Chi_Minh')::date
$$;

-- ------------------------------------------------------- row triggers ----
-- updated_at maintenance.
create or replace function app_private.touch_updated_at()
returns trigger
language plpgsql
set search_path = public, extensions, pg_temp
as $$
begin
  new.updated_at := now();
  return new;
end $$;

do $$
declare
  t text;
begin
  foreach t in array array['routes', 'facilities', 'services', 'buddy_sessions'] loop
    execute format('drop trigger if exists %I on public.%I', t || '_touch_updated_at', t);
    execute format('create trigger %I before update on public.%I
                    for each row execute function app_private.touch_updated_at()',
                   t || '_touch_updated_at', t);
  end loop;
end $$;

-- Derived defaults: length from geometry, signal level from RSRP (CONTRACT §8:
-- likely ≥ −105 dBm; uncertain −115…−105; lost < −115 or no service).
create or replace function app_private.level_from_rsrp(p_rsrp int, p_tech text default null)
returns text
language sql
immutable
set search_path = public, extensions, pg_temp
as $$
  select case
    when p_tech = 'none' then 'lost'
    when p_rsrp is null then 'uncertain'        -- no reading: do not pretend to know
    when p_rsrp >= -105 then 'likely'
    when p_rsrp >= -115 then 'uncertain'
    else 'lost'
  end
$$;

create or replace function app_private.route_defaults()
returns trigger
language plpgsql
set search_path = public, extensions, pg_temp
as $$
begin
  if new.length_km is null and new.geom is not null then
    new.length_km := round((ST_Length(new.geom) / 1000.0)::numeric, 3);
  end if;
  return new;
end $$;

create or replace function app_private.signal_sample_defaults()
returns trigger
language plpgsql
set search_path = public, extensions, pg_temp
as $$
begin
  if new.level is null then
    new.level := app_private.level_from_rsrp(new.rsrp_dbm, new.tech);
  end if;
  return new;
end $$;

drop trigger if exists routes_defaults on public.routes;
create trigger routes_defaults before insert or update of geom, length_km on public.routes
  for each row execute function app_private.route_defaults();

drop trigger if exists route_edges_defaults on public.route_edges;
create trigger route_edges_defaults before insert or update of geom, length_km on public.route_edges
  for each row execute function app_private.route_defaults();

drop trigger if exists signal_samples_defaults on public.signal_samples;
create trigger signal_samples_defaults before insert or update of level, rsrp_dbm, tech on public.signal_samples
  for each row execute function app_private.signal_sample_defaults();

-- >>> 20260927000300_views.sql
-- =============================================================================
-- NomadCare v2 — 0300 views for the admin dashboard
-- Owner: P1 database. All views use security_invoker = true, so the RLS
-- policies of the underlying tables apply to the caller (admins only).
-- Contract views: v_facilities, v_buddy_sessions.
-- Extra helper views (lat/lng instead of geography): v_services, v_signal_samples.
-- =============================================================================
set search_path = public, extensions;

-- Facilities + freshness (PDF 8.1: re-verify every 90 days; stale ones are
-- still published, together with the verification date). Dates in Vietnam time.
create or replace view public.v_facilities
with (security_invoker = true) as
select
  f.id,
  f.route_id,
  f.name,
  f.type,
  f.address,
  ST_Y(f.geom::geometry)                                      as lat,
  ST_X(f.geom::geometry)                                      as lng,
  f.phone,
  f.open_hours,
  f.night_shift,
  f.trauma_capable,
  f.verified_by,
  f.verified_at,
  f.status,
  f.source,
  f.notes,
  f.is_demo,
  f.created_at,
  f.updated_at,
  coalesce(f.verified_at < app_private.today_vn() - 90, false) as is_stale,
  (app_private.today_vn() - f.verified_at)                    as days_since_verified
from public.facilities f;

-- Buddy sessions + monitoring helpers.
--   overdue_by_min: minutes past next_due_at (0 when not yet due or closed)
--   event_count / last_event_kind: from checkin_events
-- 20260928000100_hardening appends alert_reason + sos_at; CREATE OR REPLACE VIEW
-- cannot drop columns, so re-running this file starts from scratch (0400 re-grants).
drop view if exists public.v_buddy_sessions;
create or replace view public.v_buddy_sessions
with (security_invoker = true) as
select
  s.id,
  s.device_id,
  s.traveler_name,
  s.recipient_name,
  s.recipient_email,
  s.recipient_phone,
  s.interval_min,
  s.grace_min,
  s.route_id,
  s.travel_mode,
  s.share_public_medical,
  s.public_medical,
  s.status,
  s.started_at,
  s.last_checkin_at,
  s.next_due_at,
  s.last_lat,
  s.last_lng,
  s.last_location_at,
  s.alerted_at,
  s.closed_at,
  s.created_at,
  s.updated_at,
  s.last_lat                                                  as lat,
  s.last_lng                                                  as lng,
  case
    when s.status <> 'closed' and s.next_due_at is not null and now() > s.next_due_at
      then floor(extract(epoch from (now() - s.next_due_at)) / 60)::int
    else 0
  end                                                         as overdue_by_min,
  (select count(*)::int from public.checkin_events e where e.session_id = s.id)
                                                              as event_count,
  (select e.kind from public.checkin_events e
    where e.session_id = s.id
    order by coalesce(e.client_ts, e.received_at) desc nulls last, e.received_at desc nulls last
    limit 1)                                                  as last_event_kind
from public.buddy_sessions s;

-- Services with plain coordinates.
create or replace view public.v_services
with (security_invoker = true) as
select
  s.id,
  s.route_id,
  s.name,
  s.type,
  ST_Y(s.geom::geometry) as lat,
  ST_X(s.geom::geometry) as lng,
  s.phone,
  s.open_hours,
  s.is_partner,
  s.commission_rate,
  s.status,
  s.notes,
  s.is_demo,
  s.created_at,
  s.updated_at
from public.services s;

-- Signal samples with plain coordinates (heat map / moderation queue).
create or replace view public.v_signal_samples
with (security_invoker = true) as
select
  x.id,
  x.route_id,
  x.edge_id,
  x.carrier,
  x.tech,
  x.rsrp_dbm,
  x.level,
  ST_Y(x.geom::geometry) as lat,
  ST_X(x.geom::geometry) as lng,
  x.measured_at,
  x.source,
  x.status,
  x.device_model,
  x.is_holdout,
  x.created_at
from public.signal_samples x;

-- >>> 20260927000400_rls.sql
-- =============================================================================
-- NomadCare v2 — 0400 row-level security, privileges, is_admin()
-- Owner: P1 database.
-- Model:
--   anon           → NO table/view privileges at all; only the public RPCs (0500).
--   authenticated  → table privileges, but every policy requires is_admin()
--                    (a row in admin_users). Non-admin accounts see nothing.
--   service_role   → bypasses RLS (Edge Functions, server scripts).
-- SECURITY DEFINER functions are owned by the migration role (table owner), so
-- they are not subject to these policies and validate their own input.
-- =============================================================================
set search_path = public, extensions;

-- --------------------------------------------------------- is_admin() ----
create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public, extensions, pg_temp
as $$
  select exists (select 1 from public.admin_users a where a.user_id = auth.uid())
$$;
comment on function public.is_admin() is
  'True when the calling JWT user (auth.uid()) has a row in admin_users (role admin or reviewer).';

-- Role helper for the few actions reserved to role = ''admin'' (managing admins).
create or replace function app_private.has_admin_role(p_role text default 'admin')
returns boolean
language sql
stable
security definer
set search_path = public, extensions, pg_temp
as $$
  select exists (select 1 from public.admin_users a
                  where a.user_id = auth.uid() and a.role = p_role)
$$;

revoke all on function public.is_admin() from public;
revoke all on function app_private.has_admin_role(text) from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.is_admin() from anon';
    execute 'grant execute on function public.is_admin() to authenticated, service_role';
    execute 'grant execute on function app_private.has_admin_role(text) to authenticated, service_role';
    -- policies evaluated as "authenticated" need to resolve app_private.* helpers
    execute 'grant usage on schema app_private to authenticated';
  end if;
end $$;

-- ------------------------------------------------ enable RLS + policies ----
do $$
declare
  t text;
  -- tables administered with full CRUD by admins
  crud_tables text[] := array[
    'carriers', 'routes', 'route_nodes', 'route_edges', 'signal_samples', 'signal_segments',
    'route_accuracy', 'facilities', 'services', 'facility_submissions', 'data_packs',
    'content_releases', 'devices', 'device_ops', 'buddy_sessions', 'checkin_events'];
  all_tables text[] := crud_tables || array['admin_users', 'audit_log'];
  has_roles boolean := exists (select 1 from pg_roles where rolname = 'anon');
begin
  foreach t in array all_tables loop
    execute format('alter table public.%I enable row level security', t);
    -- privileges: anon gets nothing, authenticated gets DML (filtered by RLS)
    execute format('revoke all on public.%I from public', t);
    if has_roles then
      execute format('revoke all on public.%I from anon', t);
      execute format('grant all on public.%I to service_role', t);
    end if;
  end loop;

  foreach t in array crud_tables loop
    execute format('drop policy if exists %I on public.%I', t || '_admin_all', t);
    execute format('create policy %I on public.%I for all to authenticated
                      using ((select public.is_admin()))
                      with check ((select public.is_admin()))', t || '_admin_all', t);
    if has_roles then
      execute format('grant select, insert, update, delete on public.%I to authenticated', t);
    end if;
  end loop;
end $$;

-- admin_users: every signed-in user may read their own row (the dashboard uses
-- it to show "not an admin"); admins read all; only role 'admin' manages admins.
drop policy if exists admin_users_select on public.admin_users;
create policy admin_users_select on public.admin_users for select to authenticated
  using (user_id = (select auth.uid()) or (select public.is_admin()));
drop policy if exists admin_users_manage on public.admin_users;
create policy admin_users_manage on public.admin_users for all to authenticated
  using ((select app_private.has_admin_role('admin')))
  with check ((select app_private.has_admin_role('admin')));

-- audit_log: append-only for admins (triggers write it as definer).
drop policy if exists audit_log_select on public.audit_log;
create policy audit_log_select on public.audit_log for select to authenticated
  using ((select public.is_admin()));
drop policy if exists audit_log_insert on public.audit_log;
create policy audit_log_insert on public.audit_log for insert to authenticated
  with check ((select public.is_admin()) and (actor is null or actor = (select auth.uid())));

do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    grant select, insert, update, delete on public.admin_users to authenticated;
    grant select, insert on public.audit_log to authenticated;
    revoke update, delete, truncate on public.audit_log from authenticated;

    -- identity sequences: admins insert rows into identity tables
    grant usage, select on all sequences in schema public to authenticated, service_role;
    revoke all on all sequences in schema public from anon;

    -- views (security_invoker → base-table RLS applies)
    revoke all on public.v_facilities, public.v_buddy_sessions, public.v_services, public.v_signal_samples from anon;
    grant select on public.v_facilities, public.v_buddy_sessions, public.v_services, public.v_signal_samples
      to authenticated, service_role;
  end if;
end $$;
revoke all on public.v_facilities, public.v_buddy_sessions, public.v_services, public.v_signal_samples from public;

-- app_private.settings: owner / service_role only.
alter table app_private.settings enable row level security;
revoke all on app_private.settings from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on app_private.settings from anon, authenticated';
    execute 'grant select on app_private.settings to service_role';
  end if;
end $$;

-- >>> 20260927000500_rpc_public.sql
-- =============================================================================
-- NomadCare v2 — 0500 public RPC (granted to anon + authenticated)
-- Owner: P1 database. Contract: CONTRACT.md §8 (Pack format) + §9 (RPC names).
--   list_routes() · get_data_pack(route, carrier) · build_data_pack(route, carrier)
--   nearest_facilities(lat, lng, limit, types) · get_content_release()
--   register_device(carrier, app_version) · sync_device_ops(device_id, secret, ops)
-- All public functions are SECURITY DEFINER with a fixed search_path and only
-- ever expose published data (verified facilities, active services) or data
-- that belongs to the calling device (device id + secret).
-- Internal helpers live in schema app_private (not exposed by the Data API).
-- =============================================================================
set search_path = public, extensions;

-- =============================================================================
-- 1. Small internal helpers
-- =============================================================================

-- Point from lat/lng (WGS84).
create or replace function app_private.pt(p_lat double precision, p_lng double precision)
returns geography
language sql
immutable
set search_path = public, extensions, pg_temp
as $$
  select case when p_lat is null or p_lng is null then null
              else ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography end
$$;

-- [lat, lng] rounded to 6 decimals (~0.1 m) for a point.
create or replace function app_private.latlng(p_geom geography)
returns jsonb
language sql
immutable
set search_path = public, extensions, pg_temp
as $$
  select case when p_geom is null then null else
    jsonb_build_array(trim_scale(round(ST_Y(p_geom::geometry)::numeric, 6)), trim_scale(round(ST_X(p_geom::geometry)::numeric, 6))) end
$$;

-- [[lat, lng], …] for a line, in vertex order.
create or replace function app_private.line_latlng(p_geom geometry)
returns jsonb
language sql
immutable
set search_path = public, extensions, pg_temp
as $$
  select coalesce(jsonb_agg(jsonb_build_array(trim_scale(round(ST_Y(d.geom)::numeric, 6)),
                                              trim_scale(round(ST_X(d.geom)::numeric, 6))) order by d.path),
                  '[]'::jsonb)
  from ST_DumpPoints(p_geom) as d
$$;

-- Lenient parsers for JSON coming from devices (never raise).
create or replace function app_private.try_ts(p text)
returns timestamptz
language plpgsql
stable
set search_path = public, extensions, pg_temp
as $$
begin
  if p is null or btrim(p) = '' then
    return null;
  end if;
  if p ~ '^\d{10,13}(\.\d+)?$' then            -- epoch seconds or milliseconds
    if length(split_part(p, '.', 1)) >= 13 then
      return to_timestamp(p::numeric / 1000.0);
    end if;
    return to_timestamp(p::numeric);
  end if;
  return p::timestamptz;
exception when others then
  return null;
end $$;

create or replace function app_private.try_num(p text)
returns double precision
language plpgsql
immutable
set search_path = public, extensions, pg_temp
as $$
begin
  if p is null or btrim(p) = '' then
    return null;
  end if;
  return p::double precision;
exception when others then
  return null;
end $$;

create or replace function app_private.try_bool(p text)
returns boolean
language plpgsql
immutable
set search_path = public, extensions, pg_temp
as $$
begin
  if p is null or btrim(p) = '' then
    return null;
  end if;
  return p::boolean;
exception when others then
  return null;
end $$;

create or replace function app_private.try_uuid(p text)
returns uuid
language plpgsql
immutable
set search_path = public, extensions, pg_temp
as $$
begin
  if p is null or btrim(p) = '' then
    return null;
  end if;
  return p::uuid;
exception when others then
  return null;
end $$;

-- Trimmed, length-capped text; empty → null.
create or replace function app_private.clean_text(p text, p_max int default 200)
returns text
language sql
immutable
set search_path = public, extensions, pg_temp
as $$
  select nullif(btrim(left(p, p_max)), '')
$$;

create or replace function app_private.valid_email(p text)
returns boolean
language sql
immutable
set search_path = public, extensions, pg_temp
as $$
  select p is not null and length(p) <= 254 and p ~* '^[^@\s<>"'',;]+@[^@\s<>"'',;]+\.[a-z]{2,}$'
$$;

-- =============================================================================
-- 2. Route helpers (bbox, corridor, facility membership)
-- =============================================================================

-- [south, west, north, east]. Uses routes.bbox when valid (array or object;
-- a GeoJSON-ordered [w,s,e,n] array is detected and re-ordered), otherwise
-- the extent of the route line + edges + nodes.
create or replace function app_private.route_bbox(p_route_id text)
returns jsonb
language plpgsql
stable
set search_path = public, extensions, pg_temp
as $$
declare
  v jsonb;
  b box2d;
begin
  select r.bbox into v from public.routes r where r.id = p_route_id;
  if v is not null and jsonb_typeof(v) = 'array' and jsonb_array_length(v) = 4 then
    if abs((v ->> 0)::numeric) > 90 or abs((v ->> 2)::numeric) > 90 then
      return jsonb_build_array(v -> 1, v -> 0, v -> 3, v -> 2);   -- was [w,s,e,n]
    end if;
    return v;
  end if;
  if v is not null and jsonb_typeof(v) = 'object' then
    if v ? 'south' then
      return jsonb_build_array(v -> 'south', v -> 'west', v -> 'north', v -> 'east');
    elsif v ? 'min_lat' then
      return jsonb_build_array(v -> 'min_lat', v -> 'min_lng', v -> 'max_lat', v -> 'max_lng');
    end if;
  end if;
  select ST_Extent(g) into b
  from (
    select r.geom::geometry as g from public.routes r where r.id = p_route_id and r.geom is not null
    union all select e.geom::geometry from public.route_edges e where e.route_id = p_route_id
    union all select n.geom::geometry from public.route_nodes n where n.route_id = p_route_id
  ) as x;
  if b is null then
    return null;
  end if;
  return jsonb_build_array(trim_scale(round(ST_YMin(b)::numeric, 6)), trim_scale(round(ST_XMin(b)::numeric, 6)),
                           trim_scale(round(ST_YMax(b)::numeric, 6)), trim_scale(round(ST_XMax(b)::numeric, 6)));
end $$;

-- Route line used for corridor queries: routes.geom, else the union of edges.
create or replace function app_private.route_corridor(p_route_id text)
returns geography
language sql
stable
set search_path = public, extensions, pg_temp
as $$
  select coalesce(
    (select r.geom from public.routes r where r.id = p_route_id),
    (select ST_Union(e.geom::geometry)::geography from public.route_edges e where e.route_id = p_route_id)
  )
$$;

-- Corridor half-width for facilities/services that have no route_id (metres).
create or replace function app_private.corridor_m()
returns double precision
language sql
immutable
set search_path = public, extensions, pg_temp
as $$ select 15000::double precision $$;

-- A facility/service belongs to a route when tagged with it, or when untagged
-- and within the corridor of the route line.
create or replace function app_private.in_route(p_item_route text, p_item_geom geography,
                                                p_route_id text, p_corridor geography)
returns boolean
language sql
stable
set search_path = public, extensions, pg_temp
as $$
  -- CASE guarantees the (expensive) geography distance only runs for untagged items
  select case
    when p_item_route is not null then p_item_route = p_route_id
    when p_item_geom is null or p_corridor is null then false
    else ST_DWithin(p_item_geom, p_corridor, app_private.corridor_m())
  end
$$;

-- Route length: stored value, else sum of the non-connector edges.
create or replace function app_private.route_length_km(p_route_id text)
returns numeric
language sql
stable
set search_path = public, extensions, pg_temp
as $$
  select trim_scale(round(coalesce(
    (select r.length_km from public.routes r where r.id = p_route_id),
    (select sum(e.length_km) from public.route_edges e where e.route_id = p_route_id and not e.is_connector),
    0)::numeric, 3))
$$;

-- =============================================================================
-- 3. JSON shapes (CONTRACT §8)
-- =============================================================================

-- Facility as published in a pack (verified_at 'YYYY-MM-DD').
create or replace function app_private.facility_pack_json(f public.facilities)
returns jsonb
language sql
stable
set search_path = public, extensions, pg_temp
as $$
  select jsonb_build_object(
    'id',                  f.id,
    'name',                f.name,
    'type',                f.type,
    'address',             f.address,
    'lat',                 trim_scale(round(ST_Y(f.geom::geometry)::numeric, 6)),
    'lng',                 trim_scale(round(ST_X(f.geom::geometry)::numeric, 6)),
    'phone',               f.phone,
    'open_hours',          f.open_hours,
    'night_shift',         f.night_shift,
    'trauma_capable',      f.trauma_capable,
    'verified_by',         f.verified_by,
    'verified_at',         f.verified_at,
    'is_stale',            coalesce(f.verified_at < app_private.today_vn() - 90, false),
    'days_since_verified', app_private.today_vn() - f.verified_at,
    'is_demo',             f.is_demo)
$$;

create or replace function app_private.service_pack_json(s public.services)
returns jsonb
language sql
stable
set search_path = public, extensions, pg_temp
as $$
  select jsonb_build_object(
    'id',         s.id,
    'name',       s.name,
    'type',       s.type,
    'lat',        trim_scale(round(ST_Y(s.geom::geometry)::numeric, 6)),
    'lng',        trim_scale(round(ST_X(s.geom::geometry)::numeric, 6)),
    'phone',      s.phone,
    'open_hours', s.open_hours,
    'is_partner', s.is_partner,
    'is_demo',    s.is_demo)
$$;

-- Buddy session as returned to the device (CONTRACT §8 Session object).
create or replace function app_private.session_json(s public.buddy_sessions)
returns jsonb
language sql
stable
set search_path = public, extensions, pg_temp
as $$
  select case when s.id is null then null else jsonb_build_object(
    'id',                   s.id,
    'traveler_name',        s.traveler_name,
    'recipient_name',       s.recipient_name,
    'recipient_email',      s.recipient_email,
    'recipient_phone',      s.recipient_phone,
    'interval_min',         s.interval_min,
    'grace_min',            s.grace_min,
    'route_id',             s.route_id,
    'travel_mode',          s.travel_mode,
    'share_public_medical', s.share_public_medical,
    'status',               s.status,
    'started_at',           s.started_at,
    'last_checkin_at',      s.last_checkin_at,
    'next_due_at',          s.next_due_at,
    'last_lat',             s.last_lat,
    'last_lng',             s.last_lng,
    'last_location_at',     s.last_location_at,
    'alerted_at',           s.alerted_at,
    'closed_at',            s.closed_at,
    'synced',               true) end
$$;

-- Most relevant session of a device: the newest open one, else the newest.
create or replace function app_private.device_session_json(p_device_id uuid)
returns jsonb
language sql
stable
set search_path = public, extensions, pg_temp
as $$
  select app_private.session_json(s)
  from public.buddy_sessions s
  where s.device_id = p_device_id
  order by (s.status <> 'closed') desc, s.started_at desc
  limit 1
$$;

-- =============================================================================
-- 4. Pack builder
-- =============================================================================

-- Builds the Pack JSON (CONTRACT §8) for one route × carrier.
--   * coordinates are [lat, lng]; every edge geometry is oriented from→to
--   * array order: nodes along the route line; edges, facilities, services by id
--   * segments: latest model_version of that route×carrier, ordered by edge, seq;
--     an edge without any segment gets one 'uncertain' segment (confidence 0)
--     so that segments always cover every edge fully
--   * facilities: verified only (+ is_stale / days_since_verified);
--     services: active only; both with coordinates
--   * size_bytes = octet_length of the final JSON text (fixed point, exact)
create or replace function app_private.build_pack(p_route_id text, p_carrier text,
                                                  p_version int, p_published_at timestamptz)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  r           public.routes%rowtype;
  v_corridor  geography;
  v_model     text;
  v_accuracy  numeric;
  v_holdout   int;
  v_acc_model text;
  v_nodes     jsonb;
  v_edges     jsonb;
  v_segments  jsonb;
  v_fac       jsonb;
  v_svc       jsonb;
  v_pack      jsonb;
  v_size      int;
  v_len       int;
begin
  select * into r from public.routes where id = p_route_id;
  if not found then
    raise exception 'route_not_found' using errcode = 'P0002', detail = coalesce(p_route_id, 'null');
  end if;
  if not exists (select 1 from public.carriers c where c.id = p_carrier) then
    raise exception 'carrier_not_found' using errcode = 'P0002', detail = coalesce(p_carrier, 'null');
  end if;

  v_corridor := app_private.route_corridor(p_route_id);

  select a.accuracy, a.holdout_n, a.model_version
    into v_accuracy, v_holdout, v_acc_model
  from public.route_accuracy a
  where a.route_id = p_route_id and a.carrier = p_carrier;

  select s.model_version into v_model
  from public.signal_segments s
  where s.route_id = p_route_id and s.carrier = p_carrier
  order by s.created_at desc, s.id desc
  limit 1;

  -- nodes, in travel order along the route line (then id): pickers and
  -- itineraries read naturally without re-sorting on the device
  select coalesce(jsonb_agg(jsonb_build_object(
           'id',      n.id,
           'name',    n.name,
           'name_en', n.name_en,
           'kind',    n.kind,
           'lat',     trim_scale(round(ST_Y(n.geom::geometry)::numeric, 6)),
           'lng',     trim_scale(round(ST_X(n.geom::geometry)::numeric, 6)))
           order by case when r.geom is not null then ST_LineLocatePoint(r.geom::geometry, n.geom::geometry) end,
                    n.id), '[]'::jsonb)
    into v_nodes
  from public.route_nodes n
  where n.route_id = p_route_id;

  -- edges (geometry oriented from → to)
  select coalesce(jsonb_agg(jsonb_build_object(
           'id',           e.id,
           'from',         e.from_node,
           'to',           e.to_node,
           'length_km',    trim_scale(round(e.length_km::numeric, 3)),
           'is_connector', e.is_connector,
           'geometry',     app_private.line_latlng(
                             case when ST_Distance(ST_StartPoint(e.geom::geometry)::geography, fn.geom)
                                     > ST_Distance(ST_EndPoint(e.geom::geometry)::geography, fn.geom)
                                  then ST_Reverse(e.geom::geometry)
                                  else e.geom::geometry end)) order by e.id), '[]'::jsonb)
    into v_edges
  from public.route_edges e
  join public.route_nodes fn on fn.id = e.from_node
  where e.route_id = p_route_id;

  -- segments, grouped per edge
  with segs as (
    select s.edge_id, s.seq, s.from_km, s.to_km, s.level, s.confidence
    from public.signal_segments s
    join public.route_edges e on e.id = s.edge_id and e.route_id = p_route_id
    where s.route_id = p_route_id
      and s.carrier = p_carrier
      and s.model_version is not distinct from v_model
    union all
    select e.id, 0, 0::numeric, e.length_km, 'uncertain', 0::numeric
    from public.route_edges e
    where e.route_id = p_route_id
      and not exists (select 1 from public.signal_segments s
                       where s.edge_id = e.id and s.carrier = p_carrier
                         and s.model_version is not distinct from v_model)
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'edge_id',    g.edge_id,
           'seq',        g.seq,
           'from_km',    trim_scale(round(g.from_km::numeric, 3)),
           'to_km',      trim_scale(round(g.to_km::numeric, 3)),
           'level',      g.level,
           'confidence', trim_scale(round(g.confidence::numeric, 3))) order by g.edge_id, g.seq, g.from_km), '[]'::jsonb)
    into v_segments
  from segs g;

  -- verified facilities of the route (or untagged within the corridor)
  select coalesce(jsonb_agg(app_private.facility_pack_json(f) order by f.id), '[]'::jsonb)
    into v_fac
  from public.facilities f
  where f.status = 'verified'
    and f.geom is not null
    and app_private.in_route(f.route_id, f.geom, p_route_id, v_corridor);

  -- active services
  select coalesce(jsonb_agg(app_private.service_pack_json(s) order by s.id), '[]'::jsonb)
    into v_svc
  from public.services s
  where s.status = 'active'
    and s.geom is not null
    and app_private.in_route(s.route_id, s.geom, p_route_id, v_corridor);

  v_pack := jsonb_build_object(
    'schema', 1,
    'route', jsonb_build_object(
      'id',             r.id,
      'name',           r.name,
      'name_en',        r.name_en,
      'region',         r.region,
      'travel_mode',    r.travel_mode,
      'length_km',      app_private.route_length_km(r.id),
      'color',          r.color,
      'bbox',           app_private.route_bbox(r.id),
      'description_vi', r.description_vi,
      'description_en', r.description_en),
    'carrier',       p_carrier,
    'version',       coalesce(p_version, 0),
    'published_at',  p_published_at,
    'model_version', coalesce(v_model, v_acc_model),
    'accuracy',      v_accuracy,
    'holdout_n',     coalesce(v_holdout, 0),
    'nodes',         v_nodes,
    'edges',         v_edges,
    'segments',      v_segments,
    'facilities',    v_fac,
    'services',      v_svc);

  -- size_bytes must describe the final text, which includes size_bytes itself.
  v_size := octet_length(v_pack::text);
  for i in 1 .. 5 loop
    v_len := octet_length((v_pack || jsonb_build_object('size_bytes', v_size))::text);
    exit when v_len = v_size;
    v_size := v_len;
  end loop;
  return v_pack || jsonb_build_object('size_bytes', v_size);
end $$;

-- =============================================================================
-- 5. Public read RPCs
-- =============================================================================

-- Live build (not stored). version = current published version (0 if none).
create or replace function public.build_data_pack(p_route_id text, p_carrier text)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_version int;
begin
  select coalesce(max(p.version), 0) into v_version
  from public.data_packs p
  where p.route_id = p_route_id and p.carrier = p_carrier and p.is_current;
  return app_private.build_pack(p_route_id, p_carrier, v_version, now());
end $$;
comment on function public.build_data_pack(text, text) is
  'Live Pack JSON (CONTRACT §8) built from the current tables; not stored.';

-- Current published pack; falls back to a live build when nothing is published
-- (or when a published row has no stored payload, e.g. imported metadata).
create or replace function public.get_data_pack(p_route_id text, p_carrier text)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_payload jsonb;
  v_version int;
  v_published timestamptz;
begin
  select p.payload, p.version, p.published_at
    into v_payload, v_version, v_published
  from public.data_packs p
  where p.route_id = p_route_id and p.carrier = p_carrier and p.is_current
  order by p.version desc
  limit 1;
  if v_payload is not null then
    return v_payload;
  end if;
  return app_private.build_pack(p_route_id, p_carrier, coalesce(v_version, 0), coalesce(v_published, now()));
end $$;
comment on function public.get_data_pack(text, text) is
  'Current published Pack JSON for a route × carrier (live build if none is published).';

-- Route catalogue with per-carrier accuracy and current pack metadata.
create or replace function public.list_routes()
returns jsonb
language sql
stable
security definer
set search_path = public, extensions, pg_temp
as $$
  select coalesce(jsonb_agg(q.item order by q.sort, q.id), '[]'::jsonb)
  from (
    select r.sort, r.id,
      jsonb_build_object(
        'id',             r.id,
        'name',           r.name,
        'name_en',        r.name_en,
        'region',         r.region,
        'travel_mode',    r.travel_mode,
        'length_km',      app_private.route_length_km(r.id),
        'color',          r.color,
        'bbox',           app_private.route_bbox(r.id),
        'description_vi', r.description_vi,
        'description_en', r.description_en,
        'verified_facilities', (
          select count(*)::int from public.facilities f
          where f.status = 'verified'
            and app_private.in_route(f.route_id, f.geom, r.id, cor.g)),
        'accuracy', (
          select coalesce(jsonb_object_agg(c.id, a.accuracy order by c.sort), '{}'::jsonb)
          from public.carriers c
          left join public.route_accuracy a on a.route_id = r.id and a.carrier = c.id),
        'packs', (
          select coalesce(jsonb_object_agg(c.id, (
                   select jsonb_build_object('version', p.version,
                                             'published_at', p.published_at,
                                             'size_bytes', p.size_bytes)
                   from public.data_packs p
                   where p.route_id = r.id and p.carrier = c.id and p.is_current
                   order by p.version desc limit 1) order by c.sort), '{}'::jsonb)
          from public.carriers c)
      ) as item
    from public.routes r
    cross join lateral (select app_private.route_corridor(r.id) as g) cor
    where r.is_active
  ) q
$$;

-- Nearest verified facilities to a point (server-side twin of the offline
-- client search). Ordered purely by distance, then trauma capability —
-- never by partnership (PDF C.2).
create or replace function public.nearest_facilities(p_lat double precision, p_lng double precision,
                                                     p_limit int default 5, p_types text[] default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_pt    geography;
  v_limit int := greatest(1, least(coalesce(p_limit, 5), 50));
  v_out   jsonb;
begin
  if p_lat is null or p_lng is null or p_lat not between -90 and 90 or p_lng not between -180 and 180 then
    raise exception 'invalid_coordinates' using errcode = '22023';
  end if;
  v_pt := app_private.pt(p_lat, p_lng);

  select coalesce(jsonb_agg(z.item order by z.dist, z.trauma desc), '[]'::jsonb) into v_out
  from (
    select app_private.facility_pack_json(c.fac)
             || jsonb_build_object('route_id', c.route_id,
                                   'distance_km', trim_scale(round((ST_Distance(c.geom, v_pt) / 1000.0)::numeric, 3))) as item,
           ST_Distance(c.geom, v_pt) as dist,
           coalesce(c.trauma_capable, false) as trauma
    from (
      -- KNN pre-selection via the GiST index, then exact spheroid distance
      select f as fac, f.geom, f.route_id, f.trauma_capable
      from public.facilities f
      where f.status = 'verified'
        and f.geom is not null
        and (p_types is null or cardinality(p_types) = 0 or f.type = any (p_types))
      order by f.geom <-> v_pt
      limit greatest(v_limit * 4, 40)
    ) c
    order by dist, trauma desc
    limit v_limit
  ) z;
  return v_out;
end $$;

-- Medical content release shown in the app: latest approved, else latest.
create or replace function public.get_content_release()
returns jsonb
language sql
stable
security definer
set search_path = public, extensions, pg_temp
as $$
  select to_jsonb(x)
  from (
    select c.id, c.version, c.kind, c.status, c.notes, c.reviewer_round1,
           c.approver, c.approved_at, c.created_at
    from public.content_releases c
    order by (c.status = 'approved') desc, c.approved_at desc nulls last, c.created_at desc, c.id desc
    limit 1
  ) x
$$;

-- =============================================================================
-- 6. Devices & sync
-- =============================================================================

-- Anonymous device registration. Returns the secret ONCE; only its sha256 is
-- stored. The device keeps {device_id, secret} in its encrypted store.
create or replace function public.register_device(p_carrier text default null, p_app_version text default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_secret  text := encode(gen_random_bytes(32), 'hex');
  v_id      uuid;
  v_carrier text := case when exists (select 1 from public.carriers c where c.id = p_carrier) then p_carrier end;
begin
  insert into public.devices (secret_hash, carrier, app_version, last_seen_at)
  values (encode(digest(v_secret, 'sha256'), 'hex'), v_carrier, app_private.clean_text(p_app_version, 40), now())
  returning id into v_id;
  return jsonb_build_object('device_id', v_id, 'secret', v_secret);
end $$;

-- Verifies a device credential (raises 'unauthorized_device', SQLSTATE 28000;
-- same code as the local mock backend, so the client re-registers).
create or replace function app_private.verify_device(p_device_id uuid, p_secret text)
returns public.devices
language plpgsql
stable
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  d public.devices%rowtype;
begin
  select * into d from public.devices where id = p_device_id;
  if not found or d.secret_hash is null or p_secret is null
     or d.secret_hash <> encode(digest(p_secret, 'sha256'), 'hex') then
    raise exception 'unauthorized_device'
      using errcode = '28000', hint = 'Unknown device or wrong secret: call register_device again.';
  end if;
  return d;
end $$;

-- Only the consented PUBLIC medical layer may reach the server (PDF 6.5).
create or replace function app_private.sanitize_public_medical(p jsonb)
returns jsonb
language sql
immutable
set search_path = public, extensions, pg_temp
as $$
  select case when p is null or jsonb_typeof(p) <> 'object' then null else
    nullif(jsonb_strip_nulls(jsonb_build_object(
      'blood_type',  app_private.clean_text(p ->> 'blood_type', 12),
      'allergies',   app_private.clean_text(p ->> 'allergies', 300),
      'conditions',  app_private.clean_text(p ->> 'conditions', 300),
      'medications', app_private.clean_text(p ->> 'medications', 300),
      'notes',       app_private.clean_text(p ->> 'notes', 300))), '{}'::jsonb) end
$$;

-- Inserts one buddy event (idempotent on event id) and returns its id.
create or replace function app_private.insert_event(p_session public.buddy_sessions, p_kind text,
                                                    p_event_id uuid, p_lat double precision,
                                                    p_lng double precision, p_accuracy numeric,
                                                    p_client_ts timestamptz, p_queued boolean,
                                                    p_note text, p_meta jsonb)
returns uuid
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_id uuid := coalesce(p_event_id, gen_random_uuid());
begin
  insert into public.checkin_events (id, session_id, device_id, kind, lat, lng, accuracy_m,
                                     client_ts, received_at, queued, note, meta)
  values (v_id, p_session.id, p_session.device_id, p_kind,
          case when p_lat between -90 and 90 and p_lng between -180 and 180 then p_lat end,
          case when p_lat between -90 and 90 and p_lng between -180 and 180 then p_lng end,
          p_accuracy, coalesce(p_client_ts, now()), now(), coalesce(p_queued, false),
          app_private.clean_text(p_note, 500), p_meta)
  on conflict (id) do nothing;
  return v_id;
end $$;

-- Resolves the target session of an op: explicit id (must belong to the
-- device), else the device's newest open session.
create or replace function app_private.op_session(p_device public.devices, p_session_id uuid)
returns public.buddy_sessions
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  s public.buddy_sessions%rowtype;
begin
  if p_session_id is not null then
    select * into s from public.buddy_sessions where id = p_session_id for update;
    if not found then
      raise exception 'session_not_found' using errcode = 'P0002', detail = p_session_id::text;
    end if;
    if s.device_id is distinct from p_device.id then
      raise exception 'session_forbidden' using errcode = '42501', detail = 'session belongs to another device';
    end if;
    return s;
  end if;
  select * into s from public.buddy_sessions
  where device_id = p_device.id and status <> 'closed'
  order by started_at desc limit 1
  for update;
  if not found then
    raise exception 'no_active_session' using errcode = 'P0002';
  end if;
  return s;
end $$;

-- ---- op: buddy.start ---------------------------------------------------------
create or replace function app_private.op_buddy_start(p_device public.devices, p_data jsonb, p_op_id uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v        jsonb := case when jsonb_typeof(p_data -> 'session') = 'object' then p_data -> 'session' else p_data end;
  v_id     uuid := coalesce(app_private.try_uuid(v ->> 'id'), app_private.try_uuid(v ->> 'session_id'),
                            app_private.try_uuid(p_data ->> 'session_id'), gen_random_uuid());
  v_email  text := lower(app_private.clean_text(coalesce(v -> 'recipient' ->> 'email', v ->> 'recipient_email'), 254));
  v_start  timestamptz := least(coalesce(app_private.try_ts(v ->> 'started_at'),
                                         app_private.try_ts(p_data ->> 'client_ts'), now()), now());
  v_int    int := greatest(1, least(coalesce(app_private.try_num(v ->> 'interval_min'), 60)::int, 10080));
  v_grace  int := greatest(0, least(coalesce(app_private.try_num(v ->> 'grace_min'), 15)::int, 1440));
  v_share  boolean := coalesce(app_private.try_bool(v ->> 'share_public_medical'), false);
  v_lat    double precision := coalesce(app_private.try_num(v ->> 'lat'), app_private.try_num(v ->> 'last_lat'));
  v_lng    double precision := coalesce(app_private.try_num(v ->> 'lng'), app_private.try_num(v ->> 'last_lng'));
  v_warn   jsonb := '[]'::jsonb;
  v_prev   public.buddy_sessions%rowtype;
  s        public.buddy_sessions%rowtype;
  v_old    public.buddy_sessions%rowtype;
begin
  if not (v_lat between -90 and 90 and v_lng between -180 and 180) then
    v_lat := null; v_lng := null;
  end if;
  if v_email is not null and not app_private.valid_email(v_email) then
    v_warn := v_warn || '"invalid_recipient_email"'::jsonb;
    v_email := null;
  end if;
  if v_email is null then
    v_warn := v_warn || '"no_recipient_email"'::jsonb;
  end if;

  select * into v_prev from public.buddy_sessions where id = v_id for update;
  if found and v_prev.device_id is distinct from p_device.id then
    raise exception 'session_conflict' using errcode = '42501', detail = 'session id belongs to another device';
  end if;

  -- one open session per device: close older open sessions
  for v_old in
    select * from public.buddy_sessions
    where device_id = p_device.id and status <> 'closed' and id <> v_id
    for update
  loop
    update public.buddy_sessions set status = 'closed', closed_at = now() where id = v_old.id;
    perform app_private.insert_event(v_old, 'stop', null, null, null, null, now(), false,
                                     null, jsonb_build_object('reason', 'superseded', 'by', v_id));
  end loop;

  insert into public.buddy_sessions as b (
    id, device_id, traveler_name, recipient_name, recipient_email, recipient_phone,
    interval_min, grace_min, route_id, travel_mode, share_public_medical, public_medical,
    status, started_at, last_checkin_at, next_due_at, last_lat, last_lng, last_location_at)
  values (
    v_id, p_device.id,
    app_private.clean_text(v ->> 'traveler_name', 80),
    app_private.clean_text(coalesce(v -> 'recipient' ->> 'name', v ->> 'recipient_name'), 80),
    v_email,
    app_private.clean_text(coalesce(v -> 'recipient' ->> 'phone', v ->> 'recipient_phone'), 32),
    v_int, v_grace,
    app_private.clean_text(v ->> 'route_id', 64),
    app_private.clean_text(v ->> 'travel_mode', 20),
    v_share,
    case when v_share then app_private.sanitize_public_medical(v -> 'public_medical') end,
    'active', v_start, v_start, v_start + make_interval(mins => v_int),
    v_lat, v_lng, case when v_lat is not null then v_start end)
  on conflict (id) do update set          -- re-sent start of the same device: refresh settings
    traveler_name        = excluded.traveler_name,
    recipient_name       = excluded.recipient_name,
    recipient_email      = excluded.recipient_email,
    recipient_phone      = excluded.recipient_phone,
    interval_min         = excluded.interval_min,
    grace_min            = excluded.grace_min,
    route_id             = excluded.route_id,
    travel_mode          = excluded.travel_mode,
    share_public_medical = excluded.share_public_medical,
    public_medical       = excluded.public_medical
  returning * into s;

  if v_prev.id is null then
    perform app_private.insert_event(
      s, 'start',
      coalesce(app_private.try_uuid(p_data ->> 'event_id'), app_private.try_uuid(p_data -> 'event' ->> 'id')),
      v_lat, v_lng, app_private.try_num(v ->> 'accuracy_m')::numeric, v_start,
      coalesce(app_private.try_bool(v ->> 'queued'), false) or now() - v_start > interval '2 minutes', null,
      jsonb_build_object('interval_min', v_int, 'grace_min', v_grace));
  end if;
  return jsonb_build_object('session_id', s.id, 'status', s.status, 'next_due_at', s.next_due_at,
                            'received_at', now(), 'warnings', v_warn);
end $$;

-- ---- op: buddy.checkin (checkin | location | pre_deadzone | sos | overdue) ----
create or replace function app_private.op_buddy_checkin(p_device public.devices, p_data jsonb, p_op_id uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v        jsonb := case when jsonb_typeof(p_data -> 'event') = 'object' then p_data -> 'event' else p_data end;
  v_kind   text := coalesce(nullif(v ->> 'kind', ''), 'checkin');
  v_ts     timestamptz := least(coalesce(app_private.try_ts(v ->> 'client_ts'), now()), now());
  v_lat    double precision := app_private.try_num(v ->> 'lat');
  v_lng    double precision := app_private.try_num(v ->> 'lng');
  v_queued boolean := coalesce(app_private.try_bool(v ->> 'queued'), now() - v_ts > interval '2 minutes');
  v_meta   jsonb := case when jsonb_typeof(v -> 'meta') = 'object' then v -> 'meta' end;
  s        public.buddy_sessions%rowtype;
  v_prev   text;
  v_last   timestamptz;
  v_event  uuid;
  v_notify boolean := false;   -- send the "all clear" (alerted → active)
  v_escalate boolean := false; -- send the alert now (active → overdue)
begin
  if v_kind not in ('checkin', 'location', 'pre_deadzone', 'sos', 'overdue') then
    raise exception 'invalid_kind' using errcode = '22023', detail = v_kind;
  end if;
  if not (v_lat between -90 and 90 and v_lng between -180 and 180) then
    v_lat := null; v_lng := null;
  end if;
  if v_meta is not null and octet_length(v_meta::text) > 4000 then
    v_meta := jsonb_build_object('truncated', true);
  end if;

  s := app_private.op_session(p_device, coalesce(app_private.try_uuid(v ->> 'session_id'),
                                                 app_private.try_uuid(p_data ->> 'session_id')));
  v_prev := s.status;

  v_event := app_private.insert_event(
    s, v_kind,
    coalesce(app_private.try_uuid(v ->> 'event_id'), app_private.try_uuid(v ->> 'id')),
    v_lat, v_lng, app_private.try_num(v ->> 'accuracy_m')::numeric, v_ts, v_queued,
    v ->> 'note', v_meta);

  if s.status = 'closed' then
    -- late event for a closed session: keep it in the log, change nothing
    return jsonb_build_object('event_id', v_event, 'received_at', now(), 'status', s.status,
                              'ignored', 'session_closed');
  end if;

  -- newest known location
  if v_lat is not null and (s.last_location_at is null or v_ts >= s.last_location_at) then
    s.last_lat := v_lat; s.last_lng := v_lng; s.last_location_at := v_ts;
  end if;

  if v_kind = 'checkin' then
    v_last := greatest(coalesce(s.last_checkin_at, v_ts), v_ts);
    s.last_checkin_at := v_last;
    s.next_due_at := v_last + make_interval(mins => s.interval_min);
    if s.status in ('overdue', 'alerted') then
      v_notify := (s.status = 'alerted');
      s.status := 'active';
      s.alerted_at := null;
      perform app_private.insert_event(s, 'resolved', null, v_lat, v_lng, null, now(), false, null,
                                       jsonb_build_object('reason', 'checkin', 'previous_status', v_prev));
    end if;
  elsif v_kind in ('sos', 'overdue') and s.status = 'active' then
    -- SOS pressed, or overdue detected on the device while offline: escalate
    -- like a missed check-in so the recipient is e-mailed (alert_payload
    -- words it as SOS when an 'sos' event exists since the last check-in).
    -- Same rule as the local mock backend (backend-local.js opBuddyCheckin).
    s.status := 'overdue';
    s.alerted_at := null;
    v_escalate := true;
  end if;

  update public.buddy_sessions set
    status           = s.status,
    last_checkin_at  = s.last_checkin_at,
    next_due_at      = s.next_due_at,
    last_lat         = s.last_lat,
    last_lng         = s.last_lng,
    last_location_at = s.last_location_at,
    alerted_at       = s.alerted_at
  where id = s.id;

  if v_notify then
    perform app_private.notify_deadman(jsonb_build_object('session_id', s.id, 'type', 'resolved'));
  elsif v_escalate and s.recipient_email is not null then
    -- do not wait for the next cron tick (pg_net sends after this transaction commits)
    perform app_private.notify_deadman(jsonb_build_object('source', v_kind, 'type', 'overdue'));
  end if;
  return jsonb_build_object('event_id', v_event, 'received_at', now(), 'status', s.status,
                            'next_due_at', s.next_due_at);
end $$;

-- ---- op: buddy.stop ------------------------------------------------------------
create or replace function app_private.op_buddy_stop(p_device public.devices, p_data jsonb, p_op_id uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_ts   timestamptz := least(coalesce(app_private.try_ts(p_data ->> 'client_ts'), now()), now());
  v_lat  double precision := app_private.try_num(p_data ->> 'lat');
  v_lng  double precision := app_private.try_num(p_data ->> 'lng');
  s      public.buddy_sessions%rowtype;
begin
  s := app_private.op_session(p_device, coalesce(app_private.try_uuid(p_data ->> 'session_id'),
                                                 app_private.try_uuid(p_data ->> 'id')));
  if s.status = 'closed' then
    return jsonb_build_object('session_id', s.id, 'status', s.status, 'received_at', now(), 'ignored', 'already_closed');
  end if;
  if s.status in ('overdue', 'alerted') then
    perform app_private.insert_event(s, 'resolved', null, v_lat, v_lng, null, v_ts, false, null,
                                     jsonb_build_object('by', 'stop', 'previous_status', s.status));
  end if;
  perform app_private.insert_event(s, 'stop', app_private.try_uuid(p_data ->> 'event_id'), v_lat, v_lng,
                                   app_private.try_num(p_data ->> 'accuracy_m')::numeric, v_ts,
                                   now() - v_ts > interval '2 minutes', p_data ->> 'note', null);
  update public.buddy_sessions
     set status = 'closed', closed_at = v_ts
   where id = s.id;
  if s.status = 'alerted' then
    perform app_private.notify_deadman(jsonb_build_object('session_id', s.id, 'type', 'resolved'));
  end if;
  return jsonb_build_object('session_id', s.id, 'status', 'closed', 'received_at', now());
end $$;

-- ---- op: buddy.resolve ("Tôi an toàn": re-arms the timer, leaves overdue/alerted) ----
create or replace function app_private.op_buddy_resolve(p_device public.devices, p_data jsonb, p_op_id uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_ts  timestamptz := least(coalesce(app_private.try_ts(p_data ->> 'client_ts'), now()), now());
  v_lat double precision := app_private.try_num(p_data ->> 'lat');
  v_lng double precision := app_private.try_num(p_data ->> 'lng');
  s     public.buddy_sessions%rowtype;
  v_was text;
begin
  s := app_private.op_session(p_device, coalesce(app_private.try_uuid(p_data ->> 'session_id'),
                                                 app_private.try_uuid(p_data ->> 'id')));
  v_was := s.status;
  if s.status = 'closed' then
    return jsonb_build_object('session_id', s.id, 'status', s.status, 'received_at', now(), 'ignored', 'session_closed');
  end if;
  if not (v_lat between -90 and 90 and v_lng between -180 and 180) then
    v_lat := null; v_lng := null;
  end if;
  perform app_private.insert_event(s, 'resolved', app_private.try_uuid(p_data ->> 'event_id'), v_lat, v_lng,
                                   null, v_ts, now() - v_ts > interval '2 minutes', p_data ->> 'note',
                                   jsonb_build_object('by', 'traveler', 'previous_status', v_was));
  update public.buddy_sessions set
    status           = 'active',
    alerted_at       = null,
    last_checkin_at  = greatest(coalesce(last_checkin_at, v_ts), v_ts),
    next_due_at      = greatest(coalesce(last_checkin_at, v_ts), v_ts) + make_interval(mins => interval_min),
    last_lat         = case when v_lat is not null and (last_location_at is null or v_ts >= last_location_at) then v_lat else last_lat end,
    last_lng         = case when v_lat is not null and (last_location_at is null or v_ts >= last_location_at) then v_lng else last_lng end,
    last_location_at = case when v_lat is not null and (last_location_at is null or v_ts >= last_location_at) then v_ts else last_location_at end
  where id = s.id
  returning * into s;
  if v_was = 'alerted' then
    perform app_private.notify_deadman(jsonb_build_object('session_id', s.id, 'type', 'resolved'));
  end if;
  return jsonb_build_object('session_id', s.id, 'status', s.status, 'received_at', now(), 'next_due_at', s.next_due_at);
end $$;

-- ---- op: report.submit (community facility report) -------------------------------
create or replace function app_private.op_report_submit(p_device public.devices, p_data jsonb, p_op_id uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_id   text := coalesce(app_private.clean_text(p_data ->> 'id', 64), p_op_id::text);
  v_kind text := coalesce(nullif(p_data ->> 'kind', ''), 'new');
  v_lat  double precision := app_private.try_num(p_data ->> 'lat');
  v_lng  double precision := app_private.try_num(p_data ->> 'lng');
begin
  if v_kind not in ('new', 'correction', 'closed', 'signal_report') then
    raise exception 'invalid_kind' using errcode = '22023', detail = v_kind;
  end if;
  if octet_length(p_data::text) > 8000 then
    raise exception 'payload_too_large' using errcode = '22023';
  end if;
  if not (v_lat between -90 and 90 and v_lng between -180 and 180) then
    v_lat := null; v_lng := null;
  end if;
  -- the device sends {id, kind, facility_id, payload:{name,type,note,route_id}, lat, lng};
  -- a flat report {kind, name, type, note, …} is accepted too
  insert into public.facility_submissions (id, device_id, facility_id, kind, payload, lat, lng, status)
  values (v_id, p_device.id, app_private.clean_text(p_data ->> 'facility_id', 64), v_kind,
          case when jsonb_typeof(p_data -> 'payload') = 'object' then p_data -> 'payload'
               else p_data - array['id', 'kind', 'facility_id', 'lat', 'lng'] end,
          v_lat, v_lng, 'pending')
  on conflict (id) do nothing;
  return jsonb_build_object('submission_id', v_id, 'received_at', now());
end $$;

-- ---- op: signal.log (opt-in anonymous community signal samples) --------------------
create or replace function app_private.op_signal_log(p_device public.devices, p_data jsonb, p_op_id uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_arr      jsonb := case when jsonb_typeof(p_data) = 'array' then p_data else p_data -> 'samples' end;
  x          jsonb;
  v_lat      double precision;
  v_lng      double precision;
  v_pt       geography;
  v_carrier  text;
  v_route    text;
  v_edge     text;
  v_rsrp     int;
  v_tech     text;
  v_level    text;
  v_ok       int := 0;
  v_skip     int := 0;
begin
  if v_arr is null or jsonb_typeof(v_arr) <> 'array' then
    raise exception 'invalid_samples' using errcode = '22023';
  end if;
  if jsonb_array_length(v_arr) > 1000 then
    raise exception 'too_many_samples' using errcode = '22023';
  end if;
  for x in select value from jsonb_array_elements(v_arr) loop
    v_lat := app_private.try_num(x ->> 'lat');
    v_lng := app_private.try_num(x ->> 'lng');
    v_carrier := coalesce(nullif(x ->> 'carrier', ''), p_device.carrier);
    v_rsrp := app_private.try_num(coalesce(x ->> 'rsrp_dbm', x ->> 'rsrp'))::int;
    v_tech := case when x ->> 'tech' in ('5G', '4G', '3G', '2G', 'none') then x ->> 'tech' end;
    v_level := case when x ->> 'level' in ('likely', 'uncertain', 'lost') then x ->> 'level' end;
    if v_rsrp is not null and v_rsrp not between -160 and -20 then
      v_rsrp := null;
    end if;
    if not (v_lat between -90 and 90 and v_lng between -180 and 180)
       or not exists (select 1 from public.carriers c where c.id = v_carrier)
       or (v_level is null and v_rsrp is null and v_tech is null) then
      v_skip := v_skip + 1;
      continue;
    end if;
    v_pt := app_private.pt(v_lat, v_lng);
    v_route := case when exists (select 1 from public.routes r where r.id = x ->> 'route_id') then x ->> 'route_id' end;
    v_edge := case when exists (select 1 from public.route_edges e where e.id = x ->> 'edge_id') then x ->> 'edge_id' end;
    if v_edge is null then
      select e.id, coalesce(v_route, e.route_id) into v_edge, v_route
      from public.route_edges e
      where ST_DWithin(e.geom, v_pt, 5000) and (v_route is null or e.route_id = v_route)
      order by e.geom <-> v_pt
      limit 1;
      if v_edge is not null and not exists (select 1 from public.route_edges e
                                              where e.id = v_edge and ST_DWithin(e.geom, v_pt, 1000)) then
        v_edge := null;   -- close to the route but not to a specific edge
      end if;
    end if;
    if v_route is null then
      v_skip := v_skip + 1;
      continue;
    end if;
    insert into public.signal_samples (route_id, edge_id, carrier, tech, rsrp_dbm, level, geom,
                                       measured_at, source, status, device_model, is_holdout)
    values (v_route, v_edge, v_carrier, v_tech, v_rsrp, v_level, v_pt,
            least(coalesce(app_private.try_ts(coalesce(x ->> 'measured_at', x ->> 'ts')), now()), now()),
            'community', 'pending', app_private.clean_text(x ->> 'device_model', 60), false);
    v_ok := v_ok + 1;
  end loop;
  return jsonb_build_object('inserted', v_ok, 'skipped', v_skip);
end $$;

-- ---- dispatcher -------------------------------------------------------------------
create or replace function app_private.apply_device_op(p_device public.devices, p_op text, p_data jsonb, p_op_id uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
begin
  if p_data is null or jsonb_typeof(p_data) not in ('object', 'array') then
    p_data := '{}'::jsonb;
  end if;
  case p_op
    when 'device.register' then
      update public.devices set
        carrier     = coalesce((select c.id from public.carriers c where c.id = p_data ->> 'carrier'), carrier),
        app_version = coalesce(app_private.clean_text(p_data ->> 'app_version', 40), app_version)
      where id = p_device.id;
      return jsonb_build_object('device_id', p_device.id);
    when 'buddy.start'   then return app_private.op_buddy_start(p_device, p_data, p_op_id);
    when 'buddy.checkin' then return app_private.op_buddy_checkin(p_device, p_data, p_op_id);
    when 'buddy.stop'    then return app_private.op_buddy_stop(p_device, p_data, p_op_id);
    when 'buddy.resolve' then return app_private.op_buddy_resolve(p_device, p_data, p_op_id);
    when 'report.submit' then return app_private.op_report_submit(p_device, p_data, p_op_id);
    when 'signal.log'    then return app_private.op_signal_log(p_device, p_data, p_op_id);
    else
      raise exception 'unknown_op' using errcode = '22023', detail = coalesce(p_op, 'null');
  end case;
end $$;

-- Batch sync of the device outbox. Each op runs in its own sub-transaction;
-- an op id that was already processed returns 'duplicate' with the stored
-- result (idempotency via device_ops). Failed ops are NOT recorded, so the
-- device may retry them; results carry retryable=false for bad input.
create or replace function public.sync_device_ops(p_device_id uuid, p_secret text, p_ops jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  d        public.devices%rowtype;
  v_ops    jsonb := coalesce(p_ops, '[]'::jsonb);
  v_op     jsonb;
  v_id     uuid;
  v_kind   text;
  v_data   jsonb;
  v_prev   jsonb;
  v_res    jsonb := '[]'::jsonb;
  v_msg    text;
  v_state  text;
begin
  d := app_private.verify_device(p_device_id, p_secret);
  if jsonb_typeof(v_ops) <> 'array' then
    raise exception 'invalid_ops' using errcode = '22023';
  end if;
  if jsonb_array_length(v_ops) > 200 then
    raise exception 'too_many_ops' using errcode = '22023', hint = 'Send at most 200 ops per call.';
  end if;
  update public.devices set last_seen_at = now() where id = d.id;

  for v_op in select e.value from jsonb_array_elements(v_ops) with ordinality as e(value, n) order by e.n loop
    v_id := app_private.try_uuid(v_op ->> 'id');
    v_kind := v_op ->> 'op';
    if v_id is null then
      v_res := v_res || jsonb_build_array(jsonb_build_object(
        'id', v_op -> 'id', 'status', 'error', 'error', 'invalid_op_id', 'retryable', false));
      continue;
    end if;
    begin
      insert into public.device_ops (id, device_id, op) values (v_id, d.id, coalesce(v_kind, '?'))
      on conflict (id) do nothing;
      if not found then
        select o.result into v_prev from public.device_ops o where o.id = v_id;
        v_res := v_res || jsonb_build_array(jsonb_build_object(
          'id', v_id, 'status', 'duplicate', 'data', v_prev -> 'data'));
        continue;
      end if;
      v_data := app_private.apply_device_op(d, v_kind, v_op -> 'data', v_id);
      update public.device_ops set result = jsonb_build_object('status', 'ok', 'data', v_data) where id = v_id;
      v_res := v_res || jsonb_build_array(jsonb_build_object('id', v_id, 'status', 'ok', 'data', v_data));
    exception when others then
      get stacked diagnostics v_msg = message_text, v_state = returned_sqlstate;
      v_res := v_res || jsonb_build_array(jsonb_build_object(
        'id', v_id, 'status', 'error', 'error', v_msg, 'code', v_state,
        'retryable', not (v_state like '22%' or v_state like '23%' or v_state in ('P0002', '28000', '42501'))));
    end;
  end loop;

  return jsonb_build_object(
    'results',     v_res,
    'server_time', now(),
    'session',     app_private.device_session_json(d.id));
end $$;

-- =============================================================================
-- 7. Privileges
-- =============================================================================
do $$
declare
  f text;
  public_rpcs text[] := array[
    'public.list_routes()',
    'public.get_data_pack(text, text)',
    'public.build_data_pack(text, text)',
    'public.nearest_facilities(double precision, double precision, int, text[])',
    'public.get_content_release()',
    'public.register_device(text, text)',
    'public.sync_device_ops(uuid, text, jsonb)'];
  has_roles boolean := exists (select 1 from pg_roles where rolname = 'anon');
begin
  foreach f in array public_rpcs loop
    execute format('revoke all on function %s from public', f);
    if has_roles then
      execute format('grant execute on function %s to anon, authenticated, service_role', f);
    end if;
  end loop;
end $$;

-- >>> 20260927000600_rpc_admin.sql
-- =============================================================================
-- NomadCare v2 — 0600 admin RPC (authenticated only, every call checks is_admin())
-- Owner: P1 database. Contract names (CONTRACT §9):
--   admin_kpis() · admin_publish_pack(route, carrier, notes)
--   admin_review_submission(id, status, note) · admin_review_samples(ids, status)
--   admin_resolve_session(id, note) · admin_approve_content(id, approver)
-- Extra helpers for the dashboard (lat/lng in, completeness check with the
-- list of missing fields): admin_upsert_facility(row) · admin_upsert_service(row)
-- SQL-editor helpers (no JWT needed): app_private.publish_pack(...),
-- app_private.publish_all_packs(notes).
-- =============================================================================
set search_path = public, extensions;

-- Trusted callers: the service_role key (Edge Functions, scripts) and direct
-- database sessions (SQL Editor, psql, pg_cron), i.e. anything that does not
-- come through the Data API as anon/authenticated. Both the JWT role claim and
-- the SET ROLE done by PostgREST (GUC "role", unchanged inside SECURITY
-- DEFINER) are checked, so a missing claim can never escalate a user role.
create or replace function app_private.is_trusted_caller()
returns boolean
language sql
stable
security definer
set search_path = public, extensions, pg_temp
as $$
  select case
    when coalesce(auth.role(), '') in ('anon', 'authenticated')
      or coalesce(current_setting('role', true), 'none') in ('anon', 'authenticated') then false
    when coalesce(auth.role(), '') = 'service_role'
      or coalesce(current_setting('role', true), 'none') = 'service_role' then true
    else session_user <> 'authenticator'
  end
$$;

-- Raises 42501 'forbidden' unless the caller is an admin (or trusted, see above).
create or replace function app_private.require_admin()
returns void
language plpgsql
stable
security definer
set search_path = public, extensions, pg_temp
as $$
begin
  if public.is_admin() or app_private.is_trusted_caller() then
    return;
  end if;
  raise exception 'forbidden' using errcode = '42501', hint = 'Admin account required (table admin_users).';
end $$;

-- ------------------------------------------------------------ KPIs ----
create or replace function public.admin_kpis()
returns jsonb
language plpgsql
stable
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v jsonb;
begin
  perform app_private.require_admin();
  select jsonb_build_object(
    'generated_at', now(),
    'facilities', (
      select jsonb_build_object(
        'verified', count(*) filter (where f.status = 'verified'),
        'pending',  count(*) filter (where f.status = 'pending'),
        'rejected', count(*) filter (where f.status = 'rejected'),
        'stale',    count(*) filter (where f.status = 'verified' and f.verified_at < app_private.today_vn() - 90),
        'target',   216)                        -- PDF 8.1: 216 verified points (72 per route)
      from public.facilities f),
    'submissions_pending', (select count(*) from public.facility_submissions s where s.status = 'pending'),
    'buddy', (
      select jsonb_build_object(
        'active',    count(*) filter (where b.status = 'active'),
        'overdue',   count(*) filter (where b.status = 'overdue'),
        'alerted',   count(*) filter (where b.status = 'alerted'),
        'closed_24h', count(*) filter (where b.status = 'closed' and b.closed_at > now() - interval '24 hours'))
      from public.buddy_sessions b),
    'samples', jsonb_build_object(
      'total',   (select count(*) from public.signal_samples),
      'pending', (select count(*) from public.signal_samples x where x.status = 'pending'),
      'by_carrier', (
        select coalesce(jsonb_object_agg(c.id, (select count(*) from public.signal_samples x where x.carrier = c.id)
                                         order by c.sort), '{}'::jsonb)
        from public.carriers c)),
    'devices', (select count(*) from public.devices),
    'routes', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'id',       r.id,
          'name',     r.name,
          'verified', (select count(*) from public.facilities f where f.route_id = r.id and f.status = 'verified'),
          'pending',  (select count(*) from public.facilities f where f.route_id = r.id and f.status = 'pending'),
          'stale',    (select count(*) from public.facilities f where f.route_id = r.id and f.status = 'verified'
                                                                    and f.verified_at < app_private.today_vn() - 90),
          'accuracy', (select coalesce(jsonb_object_agg(c.id, a.accuracy order by c.sort), '{}'::jsonb)
                         from public.carriers c
                         left join public.route_accuracy a on a.route_id = r.id and a.carrier = c.id),
          'samples',  (select count(*) from public.signal_samples x where x.route_id = r.id))
        order by r.sort, r.id), '[]'::jsonb)
      from public.routes r),
    'packs', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'route_id', p.route_id, 'carrier', p.carrier, 'version', p.version,
          'published_at', p.published_at, 'size_bytes', p.size_bytes)
        order by p.route_id, p.carrier), '[]'::jsonb)
      from public.data_packs p where p.is_current)
  ) into v;
  return v;
end $$;

-- ------------------------------------------------------ pack publishing ----
-- Snapshot the live pack as version = max + 1 and make it the current one.
create or replace function app_private.publish_pack(p_route_id text, p_carrier text,
                                                    p_notes text default null, p_actor uuid default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_version int;
  v_now     timestamptz := now();
  v_payload jsonb;
  v_size    int;
  v_sum     text;
begin
  -- serialise concurrent publishes of the same route × carrier
  perform pg_advisory_xact_lock(hashtext('nomadcare.pack:' || coalesce(p_route_id, '') || ':' || coalesce(p_carrier, '')));
  select coalesce(max(p.version), 0) + 1 into v_version
  from public.data_packs p where p.route_id = p_route_id and p.carrier = p_carrier;

  v_payload := app_private.build_pack(p_route_id, p_carrier, v_version, v_now);   -- raises if unknown
  v_size := (v_payload ->> 'size_bytes')::int;
  v_sum := encode(digest(v_payload::text, 'sha256'), 'hex');

  update public.data_packs set is_current = false
   where route_id = p_route_id and carrier = p_carrier and is_current;
  insert into public.data_packs (route_id, carrier, version, published_at, published_by, notes,
                                 size_bytes, checksum, payload, is_current)
  values (p_route_id, p_carrier, v_version, v_now, p_actor, app_private.clean_text(p_notes, 500),
          v_size, v_sum, v_payload, true);

  return jsonb_build_object('route_id', p_route_id, 'carrier', p_carrier, 'version', v_version,
                            'size_bytes', v_size, 'checksum', v_sum, 'published_at', v_now);
end $$;

-- Publishes every active route × carrier (SQL editor / seed helper).
create or replace function app_private.publish_all_packs(p_notes text default 'Initial publish')
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_out jsonb := '[]'::jsonb;
  r record;
begin
  for r in
    select ro.id as route_id, c.id as carrier
    from public.routes ro cross join public.carriers c
    where ro.is_active
    order by ro.sort, ro.id, c.sort
  loop
    v_out := v_out || jsonb_build_array(app_private.publish_pack(r.route_id, r.carrier, p_notes, null));
  end loop;
  return v_out;
end $$;

create or replace function public.admin_publish_pack(p_route_id text, p_carrier text, p_notes text default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
begin
  perform app_private.require_admin();
  return app_private.publish_pack(p_route_id, p_carrier, p_notes, auth.uid());
end $$;

-- ------------------------------------------------ community submissions ----
-- approved 'new'        → creates a PENDING facility prefilled from the payload
-- approved 'closed'     → target facility back to 'pending' (unpublished until re-verified)
-- approved 'correction' → note appended to the facility (admin edits the fields)
create or replace function public.admin_review_submission(p_id text, p_status text, p_note text default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  s        public.facility_submissions%rowtype;
  p        jsonb;
  v_fac    text;
  v_lat    double precision;
  v_lng    double precision;
  v_route  text;
  v_type   text;
  v_note   text := app_private.clean_text(p_note, 500);
begin
  perform app_private.require_admin();
  if p_status not in ('approved', 'rejected', 'pending') then
    raise exception 'invalid_status' using errcode = '22023', detail = coalesce(p_status, 'null');
  end if;
  select * into s from public.facility_submissions where id = p_id for update;
  if not found then
    raise exception 'submission_not_found' using errcode = 'P0002', detail = coalesce(p_id, 'null');
  end if;
  p := coalesce(s.payload, '{}'::jsonb);
  v_fac := s.facility_id;

  if p_status = 'approved' and s.status <> 'approved' then
    if s.kind = 'new' then
      v_lat := coalesce(s.lat, app_private.try_num(p ->> 'lat'));
      v_lng := coalesce(s.lng, app_private.try_num(p ->> 'lng'));
      v_type := case when p ->> 'type' in ('tram_y_te', 'phong_kham', 'benh_vien', 'nha_thuoc') then p ->> 'type' end;
      v_route := case when exists (select 1 from public.routes r where r.id = p ->> 'route_id') then p ->> 'route_id' end;
      if v_route is null and v_lat is not null then
        select e.route_id into v_route
        from public.route_edges e
        where ST_DWithin(e.geom, app_private.pt(v_lat, v_lng), 20000)
        order by e.geom <-> app_private.pt(v_lat, v_lng)
        limit 1;
      end if;
      insert into public.facilities (route_id, name, type, address, geom, phone, open_hours,
                                     status, source, notes)
      values (v_route,
              coalesce(app_private.clean_text(p ->> 'name', 160), 'Điểm y tế cộng đồng đề xuất'),
              v_type,
              app_private.clean_text(p ->> 'address', 300),
              app_private.pt(v_lat, v_lng),
              app_private.clean_text(p ->> 'phone', 32),
              app_private.clean_text(p ->> 'open_hours', 120),
              'pending', 'community',
              concat_ws(E'\n', 'Từ đóng góp cộng đồng #' || s.id, app_private.clean_text(p ->> 'note', 500), v_note))
      returning id into v_fac;
    elsif s.kind = 'closed' and v_fac is not null then
      update public.facilities
         set status = case when status = 'verified' then 'pending' else status end,
             notes  = concat_ws(E'\n', notes, 'Báo đóng cửa (#' || s.id || ')' || coalesce(': ' || v_note, ''))
       where id = v_fac;
    elsif s.kind = 'correction' and v_fac is not null then
      update public.facilities
         set notes = concat_ws(E'\n', notes, 'Đề xuất sửa (#' || s.id || '): '
                                             || coalesce(app_private.clean_text(p ->> 'note', 500), p::text))
       where id = v_fac;
    end if;
  end if;

  update public.facility_submissions set
    status      = p_status,
    review_note = v_note,
    reviewed_by = auth.uid(),
    reviewed_at = now(),
    facility_id = v_fac
  where id = s.id
  returning * into s;

  return jsonb_build_object('id', s.id, 'kind', s.kind, 'status', s.status,
                            'facility_id', s.facility_id, 'reviewed_at', s.reviewed_at);
end $$;

create or replace function public.admin_review_samples(p_ids bigint[], p_status text)
returns int
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_n int;
begin
  perform app_private.require_admin();
  if p_status not in ('approved', 'pending', 'rejected') then
    raise exception 'invalid_status' using errcode = '22023', detail = coalesce(p_status, 'null');
  end if;
  update public.signal_samples set status = p_status where id = any (coalesce(p_ids, '{}'));
  get diagnostics v_n = row_count;
  return v_n;
end $$;

-- ------------------------------------------------------- buddy sessions ----
-- Admin closes an incident (traveller confirmed safe). Sends the "all clear"
-- email when the recipient had been alerted.
create or replace function public.admin_resolve_session(p_id uuid, p_note text default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  s     public.buddy_sessions%rowtype;
  v_was text;
begin
  perform app_private.require_admin();
  select * into s from public.buddy_sessions where id = p_id for update;
  if not found then
    raise exception 'session_not_found' using errcode = 'P0002', detail = coalesce(p_id::text, 'null');
  end if;
  v_was := s.status;
  if v_was <> 'closed' then
    perform app_private.insert_event(s, 'resolved', null, null, null, null, now(), false, p_note,
                                     jsonb_build_object('by', 'admin', 'admin', auth.uid(), 'previous_status', v_was));
    update public.buddy_sessions set status = 'closed', closed_at = now()
     where id = s.id
     returning * into s;
    if v_was = 'alerted' then
      perform app_private.notify_deadman(jsonb_build_object('session_id', s.id, 'type', 'resolved'));
    end if;
  end if;
  return app_private.session_json(s) || jsonb_build_object('previous_status', v_was);
end $$;

-- ---------------------------------------------------- content releases ----
-- Round-2 sign-off by the medical advisor (PDF 8.1).
create or replace function public.admin_approve_content(p_id bigint, p_approver text)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  c public.content_releases%rowtype;
  v_approver text := app_private.clean_text(p_approver, 120);
begin
  perform app_private.require_admin();
  if v_approver is null then
    raise exception 'approver_required' using errcode = '22023',
      hint = 'Round-2 approval must name the medical advisor.';
  end if;
  update public.content_releases
     set status = 'approved', approver = v_approver, approved_at = now()
   where id = p_id
   returning * into c;
  if not found then
    raise exception 'content_release_not_found' using errcode = 'P0002', detail = coalesce(p_id::text, 'null');
  end if;
  return to_jsonb(c);
end $$;

-- ------------------------------------------ facility / service upserts ----
-- Required fields of a verified facility (mirrors facilities_verified_complete).
create or replace function app_private.facility_missing_fields(f public.facilities)
returns text[]
language sql
immutable
set search_path = public, extensions, pg_temp
as $$
  select array_remove(array[
    case when nullif(btrim(f.name), '') is null        then 'name' end,
    case when nullif(btrim(f.address), '') is null     then 'address' end,
    case when f.geom is null                           then 'lat_lng' end,
    case when f.type is null                           then 'type' end,
    case when nullif(btrim(f.open_hours), '') is null  then 'open_hours' end,
    case when f.night_shift is null                    then 'night_shift' end,
    case when f.trauma_capable is null                 then 'trauma_capable' end,
    case when nullif(btrim(f.phone), '') is null       then 'phone' end,
    case when nullif(btrim(f.verified_by), '') is null then 'verified_by' end,
    case when f.verified_at is null                    then 'verified_at' end], null)
$$;

-- Insert or partially update a facility from JSON {id?, lat, lng, …}. Only the
-- keys present in p_row are changed. Errors (same codes as the local backend):
--   'incomplete' (23514, DETAIL = JSON array of missing fields) when a
--   'verified' row lacks a required field; 'invalid_type' / 'invalid_status' /
--   'invalid_coordinates' (22023); 'facility_not_found' (P0002) when an unknown
--   id comes without a name (e.g. a status change of a deleted facility).
create or replace function public.admin_upsert_facility(p_row jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  f        public.facilities%rowtype;
  v_exists boolean := false;
  v_miss   text[];
  v_lat    double precision;
  v_lng    double precision;
begin
  perform app_private.require_admin();
  if p_row is null or jsonb_typeof(p_row) <> 'object' then
    raise exception 'invalid_row' using errcode = '22023';
  end if;
  if p_row ? 'id' and nullif(p_row ->> 'id', '') is not null then
    select * into f from public.facilities where id = p_row ->> 'id' for update;
    v_exists := found;
    f.id := p_row ->> 'id';
  else
    f.id := gen_random_uuid()::text;
  end if;
  if not v_exists then
    f.status := 'pending'; f.source := 'team'; f.is_demo := true;
  end if;

  if p_row ? 'route_id'       then f.route_id := nullif(p_row ->> 'route_id', ''); end if;
  if p_row ? 'name'           then f.name := app_private.clean_text(p_row ->> 'name', 160); end if;
  if p_row ? 'type'           then f.type := nullif(p_row ->> 'type', ''); end if;
  if p_row ? 'address'        then f.address := app_private.clean_text(p_row ->> 'address', 300); end if;
  if p_row ? 'phone'          then f.phone := app_private.clean_text(p_row ->> 'phone', 32); end if;
  if p_row ? 'open_hours'     then f.open_hours := app_private.clean_text(p_row ->> 'open_hours', 120); end if;
  if p_row ? 'night_shift'    then f.night_shift := app_private.try_bool(p_row ->> 'night_shift'); end if;
  if p_row ? 'trauma_capable' then f.trauma_capable := app_private.try_bool(p_row ->> 'trauma_capable'); end if;
  if p_row ? 'verified_by'    then f.verified_by := app_private.clean_text(p_row ->> 'verified_by', 120); end if;
  if p_row ? 'verified_at'    then f.verified_at := app_private.try_ts(p_row ->> 'verified_at')::date; end if;
  if p_row ? 'status'         then f.status := coalesce(nullif(p_row ->> 'status', ''), f.status); end if;
  if p_row ? 'source'         then f.source := coalesce(nullif(p_row ->> 'source', ''), f.source); end if;
  if p_row ? 'notes'          then f.notes := app_private.clean_text(p_row ->> 'notes', 2000); end if;
  if p_row ? 'is_demo'        then f.is_demo := coalesce(app_private.try_bool(p_row ->> 'is_demo'), f.is_demo); end if;
  if p_row ? 'lat' or p_row ? 'lng' then
    v_lat := app_private.try_num(p_row ->> 'lat');
    v_lng := app_private.try_num(p_row ->> 'lng');
    if v_lat is null or v_lng is null then
      f.geom := null;
    elsif v_lat between -90 and 90 and v_lng between -180 and 180 then
      f.geom := app_private.pt(v_lat, v_lng);
    else
      raise exception 'invalid_coordinates' using errcode = '22023';
    end if;
  end if;

  if not v_exists and p_row ? 'id' and not (p_row ? 'name') then
    raise exception 'facility_not_found' using errcode = 'P0002', detail = p_row ->> 'id';
  end if;
  if f.type is not null and f.type not in ('tram_y_te', 'phong_kham', 'benh_vien', 'nha_thuoc') then
    raise exception 'invalid_type' using errcode = '22023', detail = f.type;
  end if;
  if f.status is null or f.status not in ('verified', 'pending', 'rejected') then
    raise exception 'invalid_status' using errcode = '22023', detail = coalesce(f.status, 'null');
  end if;

  if f.status = 'verified' then
    v_miss := app_private.facility_missing_fields(f);
    if cardinality(v_miss) > 0 then
      raise exception 'incomplete' using errcode = '23514',
        detail = to_jsonb(v_miss)::text,
        hint = 'A verified facility needs every field (PDF 8.1); keep it pending until complete.';
    end if;
  end if;

  if v_exists then
    update public.facilities set
      route_id = f.route_id, name = f.name, type = f.type, address = f.address, geom = f.geom,
      phone = f.phone, open_hours = f.open_hours, night_shift = f.night_shift,
      trauma_capable = f.trauma_capable, verified_by = f.verified_by, verified_at = f.verified_at,
      status = f.status, source = f.source, notes = f.notes, is_demo = f.is_demo
    where id = f.id;
  else
    insert into public.facilities (id, route_id, name, type, address, geom, phone, open_hours, night_shift,
                                   trauma_capable, verified_by, verified_at, status, source, notes, is_demo)
    values (f.id, f.route_id, f.name, f.type, f.address, f.geom, f.phone, f.open_hours, f.night_shift,
            f.trauma_capable, f.verified_by, f.verified_at, f.status, f.source, f.notes, f.is_demo);
  end if;
  return (select to_jsonb(v) from public.v_facilities v where v.id = f.id);
end $$;

-- Insert or partially update a service (lodging/repair/fuel/rental) from JSON
-- {id?, lat, lng, …}. Errors: 'incomplete' (23514, DETAIL '["name"]'),
-- 'invalid_type' / 'invalid_status' / 'invalid_coordinates' (22023).
create or replace function public.admin_upsert_service(p_row jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  s        public.services%rowtype;
  v_exists boolean := false;
  v_lat    double precision;
  v_lng    double precision;
begin
  perform app_private.require_admin();
  if p_row is null or jsonb_typeof(p_row) <> 'object' then
    raise exception 'invalid_row' using errcode = '22023';
  end if;
  if nullif(p_row ->> 'id', '') is not null then
    select * into s from public.services where id = p_row ->> 'id' for update;
    v_exists := found;
    s.id := p_row ->> 'id';
  else
    s.id := gen_random_uuid()::text;
  end if;
  if not v_exists then
    s.status := 'active'; s.is_partner := false; s.commission_rate := 0; s.is_demo := true;
  end if;
  if p_row ? 'route_id'        then s.route_id := nullif(p_row ->> 'route_id', ''); end if;
  if p_row ? 'name'            then s.name := app_private.clean_text(p_row ->> 'name', 160); end if;
  if p_row ? 'type'            then s.type := nullif(p_row ->> 'type', ''); end if;
  if p_row ? 'phone'           then s.phone := app_private.clean_text(p_row ->> 'phone', 32); end if;
  if p_row ? 'open_hours'      then s.open_hours := app_private.clean_text(p_row ->> 'open_hours', 120); end if;
  if p_row ? 'is_partner'      then s.is_partner := coalesce(app_private.try_bool(p_row ->> 'is_partner'), false); end if;
  if p_row ? 'commission_rate' then s.commission_rate := coalesce(app_private.try_num(p_row ->> 'commission_rate'), 0); end if;
  if p_row ? 'status'          then s.status := coalesce(nullif(p_row ->> 'status', ''), s.status); end if;
  if p_row ? 'notes'           then s.notes := app_private.clean_text(p_row ->> 'notes', 2000); end if;
  if p_row ? 'is_demo'         then s.is_demo := coalesce(app_private.try_bool(p_row ->> 'is_demo'), s.is_demo); end if;
  if p_row ? 'lat' or p_row ? 'lng' then
    v_lat := app_private.try_num(p_row ->> 'lat');
    v_lng := app_private.try_num(p_row ->> 'lng');
    if v_lat is null or v_lng is null then
      s.geom := null;
    elsif v_lat between -90 and 90 and v_lng between -180 and 180 then
      s.geom := app_private.pt(v_lat, v_lng);
    else
      raise exception 'invalid_coordinates' using errcode = '22023';
    end if;
  end if;

  if s.name is null then
    raise exception 'incomplete' using errcode = '23514', detail = '["name"]', hint = 'Service name is required.';
  end if;
  if s.type is null or s.type not in ('lodging', 'repair', 'fuel', 'rental') then
    raise exception 'invalid_type' using errcode = '22023', detail = coalesce(s.type, 'null');
  end if;
  if s.status is null or s.status not in ('active', 'inactive') then
    raise exception 'invalid_status' using errcode = '22023', detail = coalesce(s.status, 'null');
  end if;

  if v_exists then
    update public.services set
      route_id = s.route_id, name = s.name, type = s.type, geom = s.geom, phone = s.phone,
      open_hours = s.open_hours, is_partner = s.is_partner, commission_rate = s.commission_rate,
      status = s.status, notes = s.notes, is_demo = s.is_demo
    where id = s.id;
  else
    insert into public.services (id, route_id, name, type, geom, phone, open_hours, is_partner,
                                 commission_rate, status, notes, is_demo)
    values (s.id, s.route_id, s.name, s.type, s.geom, s.phone, s.open_hours, s.is_partner,
            s.commission_rate, s.status, s.notes, s.is_demo);
  end if;
  return (select to_jsonb(v) from public.v_services v where v.id = s.id);
end $$;

-- ------------------------------------------------------------ privileges ----
do $$
declare
  f text;
  admin_rpcs text[] := array[
    'public.admin_kpis()',
    'public.admin_publish_pack(text, text, text)',
    'public.admin_review_submission(text, text, text)',
    'public.admin_review_samples(bigint[], text)',
    'public.admin_resolve_session(uuid, text)',
    'public.admin_approve_content(bigint, text)',
    'public.admin_upsert_facility(jsonb)',
    'public.admin_upsert_service(jsonb)'];
  has_roles boolean := exists (select 1 from pg_roles where rolname = 'anon');
begin
  foreach f in array admin_rpcs loop
    execute format('revoke all on function %s from public', f);
    if has_roles then
      execute format('revoke all on function %s from anon', f);
      execute format('grant execute on function %s to authenticated, service_role', f);
    end if;
  end loop;
end $$;

-- >>> 20260927000700_audit.sql
-- =============================================================================
-- NomadCare v2 — 0700 audit trail
-- Owner: P1 database. Row triggers write public.audit_log for:
--   facilities, services, facility_submissions, data_packs, content_releases
--   (insert / update / delete) and buddy_sessions (status changes only, no PII).
-- action: 'insert' | 'update' | 'status' (status column changed) | 'delete' | 'publish' (data_packs)
-- details: {row} on insert/delete, {changed:{col:{from,to}}} on update.
-- Large / noisy columns are left out (geom → lat/lng, payload, timestamps).
-- Bulk loads can switch auditing off for the current transaction/session:
--   set nc.audit = 'off';      -- e.g. at the top of seed.sql
-- An optional label for scripted changes:  set nc.actor = 'seed';
-- =============================================================================
set search_path = public, extensions;

-- Who is acting: admin display name / email, else the API role.
create or replace function app_private.actor_label(p_actor uuid)
returns text
language sql
stable
security definer
set search_path = public, extensions, pg_temp
as $$
  select coalesce(
    (select coalesce(a.display_name, u.email)
       from public.admin_users a left join auth.users u on u.id = a.user_id
      where a.user_id = p_actor),
    nullif(current_setting('nc.actor', true), ''),
    case auth.role()
      when 'anon'          then 'device'
      when 'service_role'  then 'service_role'
      when 'authenticated' then coalesce(auth.jwt() ->> 'email', 'user')
      else 'system'
    end)
$$;

-- JSON of a row without noisy columns; geography points become lat/lng.
create or replace function app_private.audit_clean(p_row jsonb, p_geom geography default null)
returns jsonb
language sql
stable
set search_path = public, extensions, pg_temp
as $$
  select (p_row - array['geom', 'payload', 'created_at', 'updated_at', 'secret_hash'])
         || case when p_geom is null then '{}'::jsonb
                 else jsonb_build_object('lat', trim_scale(round(ST_Y(p_geom::geometry)::numeric, 6)),
                                         'lng', trim_scale(round(ST_X(p_geom::geometry)::numeric, 6))) end
$$;

create or replace function app_private.audit_row()
returns trigger
language plpgsql
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_actor   uuid := auth.uid();
  v_old     jsonb;
  v_new     jsonb;
  v_changed jsonb := '{}'::jsonb;
  v_action  text := lower(tg_op);
  v_details jsonb;
  v_id      text;
  k         text;
begin
  if coalesce(current_setting('nc.audit', true), 'on') = 'off' then
    return null;
  end if;

  if tg_op in ('UPDATE', 'DELETE') then
    v_old := to_jsonb(old);
    v_old := app_private.audit_clean(v_old, case when v_old ? 'geom' then (v_old ->> 'geom')::geography end);
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    v_new := to_jsonb(new);
    v_new := app_private.audit_clean(v_new, case when v_new ? 'geom' then (v_new ->> 'geom')::geography end);
  end if;
  v_id := coalesce(v_new ->> 'id', v_old ->> 'id');

  if tg_table_name = 'buddy_sessions' then
    -- status transitions only; never copy personal data into the audit trail
    if tg_op <> 'UPDATE' or (v_old ->> 'status') is not distinct from (v_new ->> 'status') then
      return null;
    end if;
    v_action := 'status';
    v_details := jsonb_build_object('from', v_old ->> 'status', 'to', v_new ->> 'status');
  elsif tg_op = 'UPDATE' then
    for k in select jsonb_object_keys(v_new) loop
      if (v_new -> k) is distinct from (v_old -> k) then
        v_changed := v_changed || jsonb_build_object(k, jsonb_build_object('from', v_old -> k, 'to', v_new -> k));
      end if;
    end loop;
    if v_changed = '{}'::jsonb then
      return null;                                  -- nothing meaningful changed
    end if;
    if tg_table_name = 'data_packs' and v_changed - 'is_current' = '{}'::jsonb then
      return null;                                  -- the is_current flip of a publish
    end if;
    if v_changed ? 'status' then
      v_action := 'status';
    end if;
    v_details := jsonb_build_object('changed', v_changed);
  elsif tg_op = 'INSERT' then
    if tg_table_name = 'data_packs' then
      v_action := 'publish';
    end if;
    v_details := jsonb_build_object('row', v_new);
  else
    v_details := jsonb_build_object('row', v_old);
  end if;

  insert into public.audit_log (actor, actor_label, action, entity, entity_id, details)
  values (v_actor, app_private.actor_label(v_actor), v_action, tg_table_name, v_id, v_details);
  return null;
end $$;

do $$
declare
  t text;
begin
  foreach t in array array['facilities', 'services', 'facility_submissions', 'data_packs', 'content_releases'] loop
    execute format('drop trigger if exists %I on public.%I', t || '_audit', t);
    execute format('create trigger %I after insert or update or delete on public.%I
                    for each row execute function app_private.audit_row()', t || '_audit', t);
  end loop;
end $$;

drop trigger if exists buddy_sessions_audit on public.buddy_sessions;
create trigger buddy_sessions_audit after update of status on public.buddy_sessions
  for each row when (old.status is distinct from new.status)
  execute function app_private.audit_row();

-- >>> 20260927000800_cron.sql
-- =============================================================================
-- NomadCare v2 — 0800 dead-man switch: overdue detection, alert dispatch, cron
-- Owner: P1 database.
--   nc_mark_overdue()    active & now() > next_due_at + grace → 'overdue' + event
--   nc_dispatch_alerts() POST {functions_url}/deadman-alert (pg_net) when alerts are due
--   nc_deadman_tick()    both of the above (scheduled every minute via pg_cron)
--   nc_cleanup()         purge old idempotency records (daily)
--   nc_alert_claim() / nc_alert_result()  service_role API used by the Edge Function
-- Configuration (SQL Editor, once):
--   insert into app_private.settings(key, value) values
--     ('functions_url', 'https://<project-ref>.supabase.co/functions/v1'),
--     ('cron_secret',   '<same value as the CRON_SECRET function secret>')
--   on conflict (key) do update set value = excluded.value;
-- If pg_net / pg_cron are missing, everything here still installs; dispatch and
-- scheduling are skipped with a NOTICE (alerts can be sent from the dashboard).
-- =============================================================================
set search_path = public, extensions;

-- ---------------------------------------------------------- helpers ----
create or replace function app_private.setting(p_key text)
returns text
language sql
stable
security definer
set search_path = public, extensions, pg_temp
as $$
  select nullif(btrim(s.value), '') from app_private.settings s where s.key = p_key
$$;

create or replace function app_private.has_pg_net()
returns boolean
language sql
stable
set search_path = public, extensions, pg_temp
as $$
  select exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                  where n.nspname = 'net' and p.proname = 'http_post')
$$;

-- Fire-and-forget POST to the deadman-alert Edge Function. Returns the pg_net
-- request id, or null when not configured / unavailable. Never raises, so a
-- notification problem can never break a device sync or an admin action.
create or replace function app_private.notify_deadman(p_body jsonb)
returns bigint
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_url     text := app_private.setting('functions_url');
  v_secret  text := app_private.setting('cron_secret');
  v_anon    text := app_private.setting('anon_key');
  v_headers jsonb;
  v_req     bigint;
begin
  if v_url is null or not app_private.has_pg_net() then
    return null;
  end if;
  v_headers := jsonb_build_object('Content-Type', 'application/json',
                                  'x-nc-cron-secret', coalesce(v_secret, ''));
  if v_anon is not null then
    -- only needed when the function was deployed WITH JWT verification
    v_headers := v_headers || jsonb_build_object('Authorization', 'Bearer ' || v_anon, 'apikey', v_anon);
  end if;
  execute 'select net.http_post(url := $1, body := $2, headers := $3, timeout_milliseconds := $4)'
     into v_req
    using rtrim(v_url, '/') || '/deadman-alert', coalesce(p_body, '{}'::jsonb), v_headers, 15000;
  return v_req;
exception when others then
  raise warning 'notify_deadman failed: %', sqlerrm;
  return null;
end $$;

-- Retry policy after failed sends: wait 2, 4, 8, 16, 32 min; stop after 6
-- failures within an hour (an admin can still trigger manually).
create or replace function app_private.alert_backoff_ok(p_session_id uuid)
returns boolean
language sql
stable
set search_path = public, extensions, pg_temp
as $$
  select case
           when x.n = 0 then true
           when x.n >= 6 then false
           else x.last_at < now() - make_interval(mins => power(2, x.n)::int)
         end
  from (
    select count(*)::int as n, max(e.received_at) as last_at
    from public.checkin_events e
    where e.session_id = p_session_id
      and e.kind = 'alert_failed'
      and coalesce(e.meta ->> 'type', 'overdue') <> 'resolved'
      and e.received_at > now() - interval '1 hour'
  ) x
$$;

-- A session needs an alert email now (cron path). alerted_at doubles as a
-- claim marker while sending; a claim older than 10 min is considered stuck.
create or replace function app_private.alert_due(s public.buddy_sessions)
returns boolean
language sql
stable
set search_path = public, extensions, pg_temp
as $$
  select s.status = 'overdue'
     and s.recipient_email is not null
     and (s.alerted_at is null or s.alerted_at < now() - interval '10 minutes')
     and app_private.alert_backoff_ok(s.id)
$$;

-- Email payload for one session (only consented medical data). reason = 'sos'
-- when the traveller pressed SOS since the last check-in (wording of the e-mail).
create or replace function app_private.alert_payload(s public.buddy_sessions, p_type text, p_claim_at timestamptz)
returns jsonb
language sql
stable
security definer
set search_path = public, extensions, pg_temp
as $$
  select jsonb_build_object(
    'id',                   s.id,
    'type',                 p_type,
    'reason', case
                when p_type = 'resolved' then 'resolved'
                when exists (select 1 from public.checkin_events e
                              where e.session_id = s.id and e.kind = 'sos'
                                and coalesce(e.client_ts, e.received_at) >= coalesce(s.last_checkin_at, s.started_at))
                  then 'sos'
                when s.status = 'active' then 'manual'
                else 'overdue'
              end,
    'traveler_name',        s.traveler_name,
    'recipient_name',       s.recipient_name,
    'recipient_email',      s.recipient_email,
    'recipient_phone',      s.recipient_phone,
    'route_id',             s.route_id,
    'route_name',           r.name,
    'route_name_en',        r.name_en,
    'travel_mode',          s.travel_mode,
    'interval_min',         s.interval_min,
    'grace_min',            s.grace_min,
    'status',               s.status,
    'started_at',           s.started_at,
    'last_checkin_at',      s.last_checkin_at,
    'next_due_at',          s.next_due_at,
    'last_lat',             s.last_lat,
    'last_lng',             s.last_lng,
    'last_location_at',     s.last_location_at,
    'overdue_by_min', case when s.next_due_at is not null and now() > s.next_due_at
                           then floor(extract(epoch from now() - s.next_due_at) / 60)::int else 0 end,
    'share_public_medical', s.share_public_medical,
    'public_medical',       case when s.share_public_medical then s.public_medical end,
    'resolved_note', (select e.note from public.checkin_events e
                       where e.session_id = s.id and e.kind = 'resolved'
                       order by e.received_at desc limit 1),
    'claim_at',             p_claim_at,
    'server_time',          now())
  from (select 1) one
  left join public.routes r on r.id = s.route_id
$$;

-- ----------------------------------------------------- overdue detection ----
create or replace function public.nc_mark_overdue()
returns int
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_n int;
begin
  if not (app_private.is_trusted_caller() or public.is_admin()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  with due as (
    select s.id
    from public.buddy_sessions s
    where s.status = 'active'
      and s.next_due_at < now()                                   -- index-friendly prefilter
      and now() > s.next_due_at + make_interval(mins => s.grace_min)
    for update skip locked
  ), upd as (
    update public.buddy_sessions s
       set status = 'overdue', alerted_at = null
      from due
     where s.id = due.id
    returning s.id, s.device_id, s.last_lat, s.last_lng, s.next_due_at, s.grace_min
  ), ev as (
    insert into public.checkin_events (session_id, device_id, kind, lat, lng, client_ts, received_at, queued, meta)
    select u.id, u.device_id, 'overdue', u.last_lat, u.last_lng, now(), now(), false,
           jsonb_build_object('source', 'server', 'next_due_at', u.next_due_at, 'grace_min', u.grace_min)
    from upd u
    returning 1
  )
  select count(*)::int into v_n from ev;
  return v_n;
end $$;

-- ------------------------------------------------------- alert dispatch ----
-- Returns the number of sessions due for an alert when the Edge Function was
-- invoked (0 when nothing is due or dispatch is not configured).
create or replace function public.nc_dispatch_alerts()
returns int
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_n   int;
  v_req bigint;
begin
  if not (app_private.is_trusted_caller() or public.is_admin()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  select count(*)::int into v_n from public.buddy_sessions s where app_private.alert_due(s);
  if v_n = 0 then
    return 0;
  end if;
  if app_private.setting('functions_url') is null then
    raise notice 'nc_dispatch_alerts: % alert(s) due but app_private.settings.functions_url is not set', v_n;
    return 0;
  end if;
  if not app_private.has_pg_net() then
    raise notice 'nc_dispatch_alerts: % alert(s) due but pg_net is not installed', v_n;
    return 0;
  end if;
  v_req := app_private.notify_deadman(jsonb_build_object('source', 'cron', 'type', 'overdue'));
  return case when v_req is null then 0 else v_n end;
end $$;

create or replace function public.nc_deadman_tick()
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_marked int;
  v_sent   int;
begin
  v_marked := public.nc_mark_overdue();
  v_sent := public.nc_dispatch_alerts();
  return jsonb_build_object('marked_overdue', v_marked, 'dispatched', v_sent, 'at', now());
end $$;

create or replace function public.nc_cleanup()
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_ops int;
begin
  if not (app_private.is_trusted_caller() or public.is_admin()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  delete from public.device_ops where received_at < now() - interval '30 days';
  get diagnostics v_ops = row_count;
  return jsonb_build_object('device_ops_deleted', v_ops, 'at', now());
end $$;

-- --------------------------------------- Edge Function API (service_role) ----
-- Claims sessions to alert and returns their email payloads.
--   type 'overdue' (default): cron → every due session (alert_due), up to p_limit;
--       p_session_id + p_force (admin trigger) → that session if not closed
--   type 'resolved': the "all clear" for p_session_id, only when an alert was
--       sent and no all-clear has been sent since (p_force skips that check)
create or replace function public.nc_alert_claim(p_session_id uuid default null, p_type text default 'overdue',
                                                 p_force boolean default false, p_limit int default 25)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  s        public.buddy_sessions%rowtype;
  v_out    jsonb := '[]'::jsonb;
  v_now    timestamptz := now();
  v_alert  timestamptz;
  v_clear  timestamptz;
begin
  if not app_private.is_trusted_caller() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if p_type not in ('overdue', 'resolved') then
    raise exception 'invalid_type' using errcode = '22023', detail = coalesce(p_type, 'null');
  end if;

  if p_type = 'resolved' then
    select * into s from public.buddy_sessions where id = p_session_id;
    if not found or s.recipient_email is null or s.status not in ('active', 'closed') then
      return v_out;
    end if;
    select max(e.received_at) filter (where coalesce(e.meta ->> 'type', 'overdue') <> 'resolved'),
           max(e.received_at) filter (where e.meta ->> 'type' = 'resolved')
      into v_alert, v_clear
    from public.checkin_events e
    where e.session_id = s.id and e.kind = 'alert_sent';
    if p_force or (v_alert is not null and (v_clear is null or v_clear < v_alert)) then
      v_out := jsonb_build_array(app_private.alert_payload(s, 'resolved', v_now));
    end if;
    return v_out;
  end if;

  if p_session_id is not null and p_force then
    select * into s from public.buddy_sessions where id = p_session_id for update;
    if not found or s.status = 'closed' or s.recipient_email is null then
      return v_out;
    end if;
    if s.status in ('overdue', 'active') then
      update public.buddy_sessions set alerted_at = v_now where id = s.id returning * into s;
    end if;
    return jsonb_build_array(app_private.alert_payload(s, 'overdue', v_now));
  end if;

  for s in
    select * from public.buddy_sessions b
    where app_private.alert_due(b) and (p_session_id is null or b.id = p_session_id)
    order by b.next_due_at nulls last
    limit greatest(1, least(coalesce(p_limit, 25), 100))
    for update skip locked
  loop
    update public.buddy_sessions set alerted_at = v_now where id = s.id returning * into s;
    v_out := v_out || jsonb_build_array(app_private.alert_payload(s, 'overdue', v_now));
  end loop;
  return v_out;
end $$;

-- Records the outcome of one email. On success an overdue session becomes
-- 'alerted'; on failure the claim is released so the cron retries (backoff).
create or replace function public.nc_alert_result(p_session_id uuid, p_ok boolean, p_type text default 'overdue',
                                                  p_provider text default 'resend', p_provider_id text default null,
                                                  p_error text default null, p_trigger text default 'cron')
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  s           public.buddy_sessions%rowtype;
  v_meta      jsonb;
  v_all_clear boolean := false;
begin
  if not app_private.is_trusted_caller() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  select * into s from public.buddy_sessions where id = p_session_id for update;
  if not found then
    raise exception 'session_not_found' using errcode = 'P0002';
  end if;
  v_meta := jsonb_strip_nulls(jsonb_build_object(
    'type', coalesce(p_type, 'overdue'), 'provider', p_provider, 'id', p_provider_id,
    'error', left(p_error, 500), 'trigger', p_trigger));

  if coalesce(p_type, 'overdue') = 'overdue' then
    if p_ok then
      if s.status = 'overdue' or (p_trigger = 'manual' and s.status in ('active', 'alerted')) then
        update public.buddy_sessions set status = 'alerted', alerted_at = now()
         where id = s.id returning * into s;
      elsif s.status = 'active' then
        -- the traveller checked in while the email was being sent → follow up with "all clear"
        update public.buddy_sessions set alerted_at = null where id = s.id returning * into s;
        v_all_clear := true;
      end if;
    elsif s.status in ('overdue', 'active') then
      update public.buddy_sessions set alerted_at = null where id = s.id returning * into s;
    end if;
  end if;

  perform app_private.insert_event(s, case when p_ok then 'alert_sent' else 'alert_failed' end,
                                   null, null, null, null, now(), false, null, v_meta);
  if v_all_clear then
    perform app_private.notify_deadman(jsonb_build_object('session_id', s.id, 'type', 'resolved'));
  end if;
  return jsonb_build_object('session_id', s.id, 'status', s.status, 'alerted_at', s.alerted_at);
end $$;

-- ------------------------------------------------------------ privileges ----
do $$
declare
  f text;
  has_roles boolean := exists (select 1 from pg_roles where rolname = 'anon');
begin
  foreach f in array array['public.nc_mark_overdue()', 'public.nc_dispatch_alerts()',
                           'public.nc_deadman_tick()', 'public.nc_cleanup()'] loop
    execute format('revoke all on function %s from public', f);
    if has_roles then
      execute format('revoke all on function %s from anon', f);
      execute format('grant execute on function %s to authenticated, service_role', f);  -- guarded inside
    end if;
  end loop;
  foreach f in array array['public.nc_alert_claim(uuid, text, boolean, int)',
                           'public.nc_alert_result(uuid, boolean, text, text, text, text, text)'] loop
    execute format('revoke all on function %s from public', f);
    if has_roles then
      execute format('revoke all on function %s from anon, authenticated', f);
      execute format('grant execute on function %s to service_role', f);
    end if;
  end loop;
end $$;

-- -------------------------------------------------------------- schedule ----
do $$
begin
  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                  where n.nspname = 'cron' and p.proname = 'schedule') then
    raise notice 'pg_cron not installed: jobs not scheduled. Run "select public.nc_deadman_tick();" manually, or enable pg_cron then create the cron jobs (supabase/README.md, Bước 5) or re-run the whole setup_all.sql — never 0800_cron.sql alone.';
    return;
  end if;
  begin
    perform cron.schedule('nomadcare-deadman', '* * * * *', 'select public.nc_deadman_tick()');
    perform cron.schedule('nomadcare-cleanup', '17 3 * * *', 'select public.nc_cleanup()');
  exception when others then
    raise notice 'pg_cron scheduling failed (%): schedule the jobs from Dashboard > Integrations > Cron', sqlerrm;
  end;
end $$;

-- >>> 20260927000900_realtime.sql
-- =============================================================================
-- NomadCare v2 — 0900 Supabase Realtime + final privilege sweep
-- Owner: P1 database.
-- Realtime (postgres_changes) for the admin dashboard: buddy_sessions,
-- checkin_events, facility_submissions, facilities, signal_samples.
-- Realtime applies RLS, so only admins receive the changes. Skipped with a
-- NOTICE when the publication "supabase_realtime" does not exist.
-- =============================================================================
set search_path = public, extensions;

do $$
declare
  t text;
begin
  if not exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    raise notice 'publication supabase_realtime not found: realtime not configured (dashboard falls back to polling)';
    return;
  end if;
  if (select puballtables from pg_publication where pubname = 'supabase_realtime') then
    return;                                        -- FOR ALL TABLES: already included
  end if;
  foreach t in array array['buddy_sessions', 'checkin_events', 'facility_submissions', 'facilities', 'signal_samples'] loop
    if not exists (select 1 from pg_publication_tables
                    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
end $$;

-- ------------------------------------------------ final privilege sweep ----
-- Functions are EXECUTE-able by PUBLIC by default in PostgreSQL. Nothing in
-- app_private is reachable through the Data API, but lock it down anyway and
-- re-grant only what RLS policies / invoker-rights triggers need.
revoke all on all functions in schema app_private from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on all functions in schema app_private from anon, authenticated';
    execute 'grant execute on all functions in schema app_private to service_role';
    -- used by RLS policies and by SECURITY INVOKER triggers fired by admin DML
    execute 'grant execute on function app_private.has_admin_role(text) to authenticated';
    execute 'grant execute on function app_private.level_from_rsrp(int, text) to authenticated';
    execute 'grant execute on function app_private.touch_updated_at() to authenticated';
    execute 'grant execute on function app_private.route_defaults() to authenticated';
    execute 'grant execute on function app_private.signal_sample_defaults() to authenticated';
    -- used by the security_invoker view v_facilities
    execute 'grant execute on function app_private.today_vn() to authenticated';
  end if;
end $$;

-- JIT off for every NomadCare function: these are small OLTP queries, and
-- right after a bulk load (no statistics yet) inflated estimates would make
-- PostgreSQL spend ~70 ms JIT-compiling a 1 ms query (measured on list_routes).
do $$
declare
  f regprocedure;
begin
  for f in
    select p.oid::regprocedure
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    join pg_language l on l.oid = p.prolang
    where n.nspname in ('public', 'app_private')
      and p.prokind = 'f'
      and l.lanname in ('sql', 'plpgsql')
      and p.proowner = (select oid from pg_roles where rolname = current_user)
      and not exists (select 1 from pg_depend d
                       where d.classid = 'pg_proc'::regclass and d.objid = p.oid and d.deptype = 'e')
  loop
    execute format('alter function %s set jit = off', f);
  end loop;
end $$;

-- >>> 20260928000100_hardening.sql
-- =============================================================================
-- NomadCare v2 — 20260928000100 hardening (wave 3): privacy, abuse limits, SOS,
-- admin data quality. Owner: backend. Idempotent; runs after 0100–0900 and
-- replaces some of their functions (old signatures are dropped first).
--   Buddy / devices
--   * buddy_sessions.alert_reason 'overdue' | 'sos' | null (null while active or
--     closed; kept while overdue/alerted). SOS on an alerted session re-arms the
--     alert so the recipient gets an SOS e-mail. v_buddy_sessions adds
--     alert_reason + sos_at.
--   * buddy.start requires a valid recipient e-mail ('recipient_email_required');
--     traveller / recipient names are cleaned (≤ 60 chars, no URLs, e-mails,
--     control characters); started_at is capped to the last 24 h.
--   * new device ops: buddy.update {session_id, share_public_medical,
--     public_medical} and device.erase (erases the device and everything it
--     owns; an unknown device + device.erase is a no-op success).
--   * rate limits (app_private.settings can override the defaults):
--       limit_buddy_start_device_24h  5   new sessions per device / 24 h
--       limit_alert_recipient_24h     3   alert e-mails per recipient / 24 h
--       limit_alert_global_1h        50   alert e-mails for all recipients / h
--       limit_register_ip_1h         30   register_device per client IP / h
--     Recipients on reserved domains (example.com, *.test, …) never receive a
--     real e-mail and are exempt. A session over the alert limit stays
--     'overdue' and gets one 'alert_failed' event {reason:'rate_limited'}.
--     Manual alerts sent by an admin are never limited.
--   * retention: public_medical is dropped as soon as a session closes;
--     nc_cleanup() deletes sessions closed > 30 days ago (and open sessions idle
--     > 90 days) with their events, and clears registration IP hashes > 24 h.
--   * manual alerts are attributed to the admin (nc_alert_claim / nc_alert_result
--     take p_actor; audit_row reads nc.actor_id).
--   Admin
--   * admin_publish_pack(route, carrier, notes, force=false) returns the current
--     version with unchanged:true when the live build has the same content.
--   * admin_pack_changes(route?, carrier?) — per route × carrier: changed flag
--     + facilities/services added/removed(reason)/updated since the current pack.
--   * admin_review_submission: re-approving a reopened 'new' report reuses the
--     facility created the first time.
--   * admin_review_samples writes one audit row per call (changed rows only).
--   * admin_upsert_facility: 'invalid_date' for a verification date in the
--     future; 'invalid_coordinates' (detail outside_vietnam) for a verified
--     facility outside lat 8.1–23.5 / lng 102.1–109.6.
--   * realtime publication + data_packs (without payload where supported),
--     content_releases, services, audit_log.
-- =============================================================================
set search_path = public, extensions;

-- =============================================================================
-- 1. Schema
-- =============================================================================
alter table public.buddy_sessions add column if not exists alert_reason text;
do $$
begin
  if not exists (select 1 from pg_constraint
                 where conname = 'buddy_sessions_alert_reason_check'
                   and conrelid = 'public.buddy_sessions'::regclass) then
    alter table public.buddy_sessions add constraint buddy_sessions_alert_reason_check
      check (alert_reason is null or alert_reason in ('overdue', 'sos'));
  end if;
end $$;
comment on column public.buddy_sessions.alert_reason is
  'Why the session is overdue/alerted: overdue (missed check-in) | sos (SOS pressed). Null while active or closed.';

alter table public.devices add column if not exists reg_ip_hash text;
comment on column public.devices.reg_ip_hash is
  'sha256(ip_salt | client IP) of the registration request, only for the register_device rate limit; cleared after 24 h by nc_cleanup().';

create index if not exists buddy_sessions_device_created_idx on public.buddy_sessions (device_id, created_at desc);
create index if not exists buddy_sessions_recipient_idx      on public.buddy_sessions (lower(recipient_email))
  where recipient_email is not null;
create index if not exists buddy_sessions_closed_at_idx      on public.buddy_sessions (closed_at) where status = 'closed';
create index if not exists checkin_events_alert_idx          on public.checkin_events (received_at desc)
  where kind in ('alert_sent', 'alert_failed');
create index if not exists devices_reg_ip_idx                on public.devices (reg_ip_hash, created_at desc)
  where reg_ip_hash is not null;

-- per-project salt for the IP hashes (never exposed)
insert into app_private.settings (key, value)
values ('ip_salt', encode(gen_random_bytes(16), 'hex'))
on conflict (key) do nothing;

-- =============================================================================
-- 2. Small helpers
-- =============================================================================

-- Integer limit from app_private.settings (key) or the default.
create or replace function app_private.limit_value(p_key text, p_default int)
returns int
language sql
stable
security definer
set search_path = public, extensions, pg_temp
as $$
  select coalesce((select case when s.value ~ '^\s*\d+\s*$' then btrim(s.value)::int end
                   from app_private.settings s where s.key = p_key), p_default)
$$;

-- RFC 2606 / 6761 reserved domains (demo seed): never e-mailed for real (same
-- rule as the Edge Function), so they are exempt from the abuse limits.
create or replace function app_private.is_reserved_email(p text)
returns boolean
language sql
immutable
set search_path = public, extensions, pg_temp
as $$
  select p is not null
     and lower(btrim(p)) ~ '@([^@]*\.)?(example\.(com|net|org)|example|test|invalid|localhost)$'
$$;

-- Display name for e-mails / dashboards: control characters, URLs, "http",
-- "www.", e-mail addresses and bare domains (common TLDs) are removed, spaces
-- collapsed, max p_max characters; empty → null. Mirrors cleanName() in
-- assets/js/services/backend-local.js.
create or replace function app_private.clean_name(p text, p_max int default 60)
returns text
language sql
immutable
set search_path = public, extensions, pg_temp
as $$
  select nullif(btrim(left(btrim(
    regexp_replace(
      regexp_replace(
        regexp_replace(
          regexp_replace(
            regexp_replace(coalesce(p, ''), '[[:cntrl:]]+', ' ', 'g'),
            '[^[:space:]]*(https?|://|www\.)[^[:space:]]*', ' ', 'gi'),
          '[^[:space:]@]+@[^[:space:]@]+', ' ', 'g'),
        '[^[:space:]]+\.(com|net|org|info|biz|io|co|me|app|dev|xyz|top|site|online|link|click|shop|store|live|'
          || 'vn|ru|cn|uk|de|fr|us|tk|ml|ga|cf|gq|ly|to|gl|gg|cc|tv|ws|pw|su|in|eu|asia|ai|sh|page|lol|icu|'
          || 'cyou|buzz|rest|work|support|help|email|bank|finance|money|pro|cloud|tech|space|website|fun|'
          || 'club|vip|win|bid|loan|zip|mov)\M[^[:space:]]*', ' ', 'gi'),
      '[[:space:]]+', ' ', 'g')), greatest(coalesce(p_max, 60), 1))), '')
$$;

-- Client IP of the current PostgREST request (Cloudflare / proxy headers), or
-- null outside the Data API (SQL editor, tests, cron).
create or replace function app_private.client_ip()
returns text
language plpgsql
stable
set search_path = public, extensions, pg_temp
as $$
declare
  h jsonb;
begin
  begin
    h := nullif(current_setting('request.headers', true), '')::jsonb;
  exception when others then
    return null;
  end;
  if h is null or jsonb_typeof(h) <> 'object' then
    return null;
  end if;
  return left(coalesce(nullif(btrim(h ->> 'cf-connecting-ip'), ''),
                       nullif(btrim(h ->> 'x-real-ip'), ''),
                       nullif(btrim(split_part(coalesce(h ->> 'x-forwarded-for', ''), ',', 1)), '')), 64);
end $$;

-- Acting admin for trusted callers (the Edge Function uses the service key):
-- audit_row() and actor_label() pick it up for the rest of the transaction.
create or replace function app_private.set_actor(p_actor uuid)
returns text
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_label text;
begin
  if p_actor is null then
    return null;
  end if;
  select coalesce(a.display_name, u.email, 'admin') into v_label
  from public.admin_users a left join auth.users u on u.id = a.user_id
  where a.user_id = p_actor;
  if not found then
    return null;                      -- not an admin: keep the default attribution
  end if;
  perform set_config('nc.actor_id', p_actor::text, true);
  perform set_config('nc.actor', v_label, true);
  return v_label;
end $$;

-- =============================================================================
-- 3. Audit: trusted callers may act for an admin (nc.actor_id)
-- =============================================================================
create or replace function app_private.audit_row()
returns trigger
language plpgsql
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_actor   uuid := coalesce(auth.uid(), app_private.try_uuid(current_setting('nc.actor_id', true)));
  v_old     jsonb;
  v_new     jsonb;
  v_changed jsonb := '{}'::jsonb;
  v_action  text := lower(tg_op);
  v_details jsonb;
  v_id      text;
  k         text;
begin
  if coalesce(current_setting('nc.audit', true), 'on') = 'off' then
    return null;
  end if;

  if tg_op in ('UPDATE', 'DELETE') then
    v_old := to_jsonb(old);
    v_old := app_private.audit_clean(v_old, case when v_old ? 'geom' then (v_old ->> 'geom')::geography end);
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    v_new := to_jsonb(new);
    v_new := app_private.audit_clean(v_new, case when v_new ? 'geom' then (v_new ->> 'geom')::geography end);
  end if;
  v_id := coalesce(v_new ->> 'id', v_old ->> 'id');

  if tg_table_name = 'buddy_sessions' then
    -- status transitions only; never copy personal data into the audit trail
    if tg_op <> 'UPDATE' or (v_old ->> 'status') is not distinct from (v_new ->> 'status') then
      return null;
    end if;
    v_action := 'status';
    v_details := jsonb_build_object('from', v_old ->> 'status', 'to', v_new ->> 'status');
  elsif tg_op = 'UPDATE' then
    for k in select jsonb_object_keys(v_new) loop
      if (v_new -> k) is distinct from (v_old -> k) then
        v_changed := v_changed || jsonb_build_object(k, jsonb_build_object('from', v_old -> k, 'to', v_new -> k));
      end if;
    end loop;
    if v_changed = '{}'::jsonb then
      return null;
    end if;
    if tg_table_name = 'data_packs' and v_changed - 'is_current' = '{}'::jsonb then
      return null;
    end if;
    if v_changed ? 'status' then
      v_action := 'status';
    end if;
    v_details := jsonb_build_object('changed', v_changed);
  elsif tg_op = 'INSERT' then
    if tg_table_name = 'data_packs' then
      v_action := 'publish';
    end if;
    v_details := jsonb_build_object('row', v_new);
  else
    v_details := jsonb_build_object('row', v_old);
  end if;

  insert into public.audit_log (actor, actor_label, action, entity, entity_id, details)
  values (v_actor, app_private.actor_label(v_actor), v_action, tg_table_name, v_id, v_details);
  return null;
end $$;

-- =============================================================================
-- 4. Buddy session invariants (one place for every write path)
-- =============================================================================
--   active / closed      → alert_reason null
--   overdue / alerted    → alert_reason defaults to 'overdue'
--   closed               → public_medical dropped (retention)
--   not shared           → public_medical null
create or replace function app_private.buddy_session_defaults()
returns trigger
language plpgsql
set search_path = public, extensions, pg_temp
as $$
begin
  if new.status in ('active', 'closed') then
    new.alert_reason := null;
  elsif new.alert_reason is null then
    new.alert_reason := 'overdue';
  end if;
  if new.status = 'closed' or not coalesce(new.share_public_medical, false) then
    new.public_medical := null;
  end if;
  return new;
end $$;

-- backfill before the trigger exists (explicit values, then the trigger keeps them)
update public.buddy_sessions s
   set alert_reason = case when exists (select 1 from public.checkin_events e
                                         where e.session_id = s.id and e.kind = 'sos'
                                           and coalesce(e.client_ts, e.received_at) >= coalesce(s.last_checkin_at, s.started_at))
                           then 'sos' else 'overdue' end
 where s.status in ('overdue', 'alerted') and s.alert_reason is null;
update public.buddy_sessions set public_medical = null
 where public_medical is not null and (status = 'closed' or not share_public_medical);

drop trigger if exists buddy_sessions_defaults on public.buddy_sessions;
create trigger buddy_sessions_defaults before insert or update on public.buddy_sessions
  for each row execute function app_private.buddy_session_defaults();

-- Session object for the device (+ alert_reason).
create or replace function app_private.session_json(s public.buddy_sessions)
returns jsonb
language sql
stable
set search_path = public, extensions, pg_temp
as $$
  select case when s.id is null then null else jsonb_build_object(
    'id',                   s.id,
    'traveler_name',        s.traveler_name,
    'recipient_name',       s.recipient_name,
    'recipient_email',      s.recipient_email,
    'recipient_phone',      s.recipient_phone,
    'interval_min',         s.interval_min,
    'grace_min',            s.grace_min,
    'route_id',             s.route_id,
    'travel_mode',          s.travel_mode,
    'share_public_medical', s.share_public_medical,
    'status',               s.status,
    'alert_reason',         s.alert_reason,
    'started_at',           s.started_at,
    'last_checkin_at',      s.last_checkin_at,
    'next_due_at',          s.next_due_at,
    'last_lat',             s.last_lat,
    'last_lng',             s.last_lng,
    'last_location_at',     s.last_location_at,
    'alerted_at',           s.alerted_at,
    'closed_at',            s.closed_at,
    'synced',               true) end
$$;

-- Dashboard view (+ alert_reason, sos_at = latest SOS since the last check-in).
create or replace view public.v_buddy_sessions
with (security_invoker = true) as
select
  s.id,
  s.device_id,
  s.traveler_name,
  s.recipient_name,
  s.recipient_email,
  s.recipient_phone,
  s.interval_min,
  s.grace_min,
  s.route_id,
  s.travel_mode,
  s.share_public_medical,
  s.public_medical,
  s.status,
  s.started_at,
  s.last_checkin_at,
  s.next_due_at,
  s.last_lat,
  s.last_lng,
  s.last_location_at,
  s.alerted_at,
  s.closed_at,
  s.created_at,
  s.updated_at,
  s.last_lat                                                  as lat,
  s.last_lng                                                  as lng,
  case
    when s.status <> 'closed' and s.next_due_at is not null and now() > s.next_due_at
      then floor(extract(epoch from (now() - s.next_due_at)) / 60)::int
    else 0
  end                                                         as overdue_by_min,
  (select count(*)::int from public.checkin_events e where e.session_id = s.id)
                                                              as event_count,
  (select e.kind from public.checkin_events e
    where e.session_id = s.id
    order by coalesce(e.client_ts, e.received_at) desc nulls last, e.received_at desc nulls last
    limit 1)                                                  as last_event_kind,
  s.alert_reason,
  (select max(coalesce(e.client_ts, e.received_at)) from public.checkin_events e
    where e.session_id = s.id and e.kind = 'sos'
      and coalesce(e.client_ts, e.received_at) >= coalesce(s.last_checkin_at, s.started_at))
                                                              as sos_at
from public.buddy_sessions s;

-- =============================================================================
-- 5. Alert quota (abuse limits) + backoff + due
-- =============================================================================

-- Why an alert e-mail to p_email must not go out now: 'recipient_24h' |
-- 'global_1h' | null. Counts sent overdue/SOS alerts plus claims in flight.
create or replace function app_private.alert_quota_block(p_email text)
returns text
language sql
stable
security definer
set search_path = public, extensions, pg_temp
as $$
  with a as (
    select b.recipient_email as email, e.received_at as at
    from public.checkin_events e
    join public.buddy_sessions b on b.id = e.session_id
    where e.kind = 'alert_sent'
      and coalesce(e.meta ->> 'type', 'overdue') = 'overdue'
      and coalesce(e.meta ->> 'provider', '') <> 'demo'
      and e.received_at > now() - interval '24 hours'
    union all
    select b.recipient_email, b.alerted_at             -- claimed, e-mail in flight
    from public.buddy_sessions b
    where b.status = 'overdue' and b.alerted_at > now() - interval '10 minutes'
  )
  select case
    when p_email is null or app_private.is_reserved_email(p_email) then null
    when (select count(*) from a where lower(a.email) = lower(p_email))
         >= app_private.limit_value('limit_alert_recipient_24h', 3) then 'recipient_24h'
    when (select count(*) from a where a.at > now() - interval '1 hour' and not app_private.is_reserved_email(a.email))
         >= app_private.limit_value('limit_alert_global_1h', 50) then 'global_1h'
  end
$$;

-- Retry policy after failed sends (rate-limit markers are not send failures).
create or replace function app_private.alert_backoff_ok(p_session_id uuid)
returns boolean
language sql
stable
set search_path = public, extensions, pg_temp
as $$
  select case
           when x.n = 0 then true
           when x.n >= 6 then false
           else x.last_at < now() - make_interval(mins => power(2, x.n)::int)
         end
  from (
    select count(*)::int as n, max(e.received_at) as last_at
    from public.checkin_events e
    where e.session_id = p_session_id
      and e.kind = 'alert_failed'
      and coalesce(e.meta ->> 'type', 'overdue') <> 'resolved'
      and coalesce(e.meta ->> 'reason', '') <> 'rate_limited'
      and e.received_at > now() - interval '1 hour'
  ) x
$$;

create or replace function app_private.alert_due(s public.buddy_sessions)
returns boolean
language sql
stable
set search_path = public, extensions, pg_temp
as $$
  select s.status = 'overdue'
     and s.recipient_email is not null
     and (s.alerted_at is null or s.alerted_at < now() - interval '10 minutes')
     and app_private.alert_backoff_ok(s.id)
     and app_private.alert_quota_block(s.recipient_email) is null
$$;

-- One 'alert_failed' {reason:'rate_limited'} per overdue episode for sessions
-- held back by the quota (visible in the dashboard timeline). Returns the count.
create or replace function app_private.flag_rate_limited(p_session_id uuid default null)
returns int
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  s       public.buddy_sessions%rowtype;
  v_block text;
  v_n     int := 0;
begin
  for s in
    select * from public.buddy_sessions b
    where b.status = 'overdue'
      and b.recipient_email is not null
      and (p_session_id is null or b.id = p_session_id)
      and (b.alerted_at is null or b.alerted_at < now() - interval '10 minutes')
      and not app_private.is_reserved_email(b.recipient_email)
      and not exists (select 1 from public.checkin_events e
                       where e.session_id = b.id and e.kind = 'alert_failed'
                         and e.meta ->> 'reason' = 'rate_limited'
                         and e.received_at >= coalesce(b.last_checkin_at, b.started_at))
  loop
    v_block := app_private.alert_quota_block(s.recipient_email);
    continue when v_block is null;
    perform app_private.insert_event(s, 'alert_failed', null, null, null, null, now(), false, null,
      jsonb_build_object('type', 'overdue', 'reason', 'rate_limited', 'limit', v_block,
                         'max', case v_block when 'recipient_24h' then app_private.limit_value('limit_alert_recipient_24h', 3)
                                             else app_private.limit_value('limit_alert_global_1h', 50) end,
                         'trigger', 'cron', 'provider', 'none'));
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;

-- An alert e-mail went out and no all-clear followed it yet.
create or replace function app_private.all_clear_pending(p_session_id uuid)
returns boolean
language sql
stable
set search_path = public, extensions, pg_temp
as $$
  select coalesce(max(e.received_at) filter (where coalesce(e.meta ->> 'type', 'overdue') <> 'resolved'), '-infinity')
       > coalesce(max(e.received_at) filter (where e.meta ->> 'type' = 'resolved'), '-infinity')
  from public.checkin_events e
  where e.session_id = p_session_id and e.kind = 'alert_sent'
$$;

-- E-mail payload (names cleaned again for legacy rows; SOS wording from
-- alert_reason, else from an SOS event since the last check-in).
create or replace function app_private.alert_payload(s public.buddy_sessions, p_type text, p_claim_at timestamptz)
returns jsonb
language sql
stable
security definer
set search_path = public, extensions, pg_temp
as $$
  select jsonb_build_object(
    'id',                   s.id,
    'type',                 p_type,
    'reason', case
                when p_type = 'resolved' then 'resolved'
                when s.alert_reason = 'sos' or x.sos_at is not null then 'sos'
                when s.status = 'active' then 'manual'
                else 'overdue'
              end,
    'alert_reason',         s.alert_reason,
    'sos_at',               x.sos_at,
    'traveler_name',        app_private.clean_name(s.traveler_name, 60),
    'recipient_name',       app_private.clean_name(s.recipient_name, 60),
    'recipient_email',      s.recipient_email,
    'recipient_phone',      s.recipient_phone,
    'route_id',             s.route_id,
    'route_name',           r.name,
    'route_name_en',        r.name_en,
    'travel_mode',          s.travel_mode,
    'interval_min',         s.interval_min,
    'grace_min',            s.grace_min,
    'status',               s.status,
    'started_at',           s.started_at,
    'last_checkin_at',      s.last_checkin_at,
    'next_due_at',          s.next_due_at,
    'last_lat',             s.last_lat,
    'last_lng',             s.last_lng,
    'last_location_at',     s.last_location_at,
    'overdue_by_min', case when s.next_due_at is not null and now() > s.next_due_at
                           then floor(extract(epoch from now() - s.next_due_at) / 60)::int else 0 end,
    'share_public_medical', s.share_public_medical,
    'public_medical',       case when s.share_public_medical then s.public_medical end,
    'resolved_note', app_private.clean_name((select e.note from public.checkin_events e
                                              where e.session_id = s.id and e.kind = 'resolved'
                                              order by e.received_at desc limit 1), 300),
    'claim_at',             p_claim_at,
    'server_time',          now())
  from (select (select max(coalesce(e.client_ts, e.received_at)) from public.checkin_events e
                 where e.session_id = s.id and e.kind = 'sos'
                   and coalesce(e.client_ts, e.received_at) >= coalesce(s.last_checkin_at, s.started_at)) as sos_at) x
  left join public.routes r on r.id = s.route_id
$$;

-- =============================================================================
-- 6. Devices: registration throttle
-- =============================================================================
create or replace function public.register_device(p_carrier text default null, p_app_version text default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_secret  text := encode(gen_random_bytes(32), 'hex');
  v_id      uuid;
  v_carrier text := case when exists (select 1 from public.carriers c where c.id = p_carrier) then p_carrier end;
  v_ip      text := app_private.client_ip();
  v_hash    text;
begin
  if v_ip is not null then
    v_hash := encode(digest(coalesce(app_private.setting('ip_salt'), '') || '|' || v_ip, 'sha256'), 'hex');
    if (select count(*) from public.devices d
         where d.reg_ip_hash = v_hash and d.created_at > now() - interval '1 hour')
       >= app_private.limit_value('limit_register_ip_1h', 30) then
      raise exception 'rate_limited' using errcode = '54000', detail = 'register_ip_1h',
        hint = 'Too many new devices from this network in the last hour; try again later.';
    end if;
  end if;
  insert into public.devices (secret_hash, carrier, app_version, last_seen_at, reg_ip_hash)
  values (encode(digest(v_secret, 'sha256'), 'hex'), v_carrier, app_private.clean_text(p_app_version, 40), now(), v_hash)
  returning id into v_id;
  return jsonb_build_object('device_id', v_id, 'secret', v_secret);
end $$;

-- =============================================================================
-- 7. Device ops
-- =============================================================================

-- ---- op: buddy.start (e-mail required, names cleaned, per-device limit) ----------
create or replace function app_private.op_buddy_start(p_device public.devices, p_data jsonb, p_op_id uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v        jsonb := case when jsonb_typeof(p_data -> 'session') = 'object' then p_data -> 'session' else p_data end;
  v_id     uuid := coalesce(app_private.try_uuid(v ->> 'id'), app_private.try_uuid(v ->> 'session_id'),
                            app_private.try_uuid(p_data ->> 'session_id'), gen_random_uuid());
  v_email  text := lower(app_private.clean_text(coalesce(v -> 'recipient' ->> 'email', v ->> 'recipient_email'), 254));
  v_raw    text := app_private.clean_text(v ->> 'traveler_name', 200);
  v_name   text := app_private.clean_name(v ->> 'traveler_name', 60);
  -- offline-first: a start queued on the phone keeps its time, but never more than 24 h back
  v_start  timestamptz := greatest(least(coalesce(app_private.try_ts(v ->> 'started_at'),
                                                  app_private.try_ts(p_data ->> 'client_ts'), now()), now()),
                                   now() - interval '24 hours');
  v_int    int := greatest(1, least(coalesce(app_private.try_num(v ->> 'interval_min'), 60)::int, 10080));
  v_grace  int := greatest(0, least(coalesce(app_private.try_num(v ->> 'grace_min'), 15)::int, 1440));
  v_share  boolean := coalesce(app_private.try_bool(v ->> 'share_public_medical'), false);
  v_lat    double precision := coalesce(app_private.try_num(v ->> 'lat'), app_private.try_num(v ->> 'last_lat'));
  v_lng    double precision := coalesce(app_private.try_num(v ->> 'lng'), app_private.try_num(v ->> 'last_lng'));
  v_warn   jsonb := '[]'::jsonb;
  v_recent int;
  v_prev   public.buddy_sessions%rowtype;
  s        public.buddy_sessions%rowtype;
  v_old    public.buddy_sessions%rowtype;
begin
  if not (v_lat between -90 and 90 and v_lng between -180 and 180) then
    v_lat := null; v_lng := null;
  end if;
  -- e-mail is the only automatic alert channel: a session without it would never alert anyone
  if v_email is null or not app_private.valid_email(v_email) then
    raise exception 'recipient_email_required' using errcode = '22023',
      detail = case when v_email is null then 'missing' else 'invalid' end,
      hint = 'buddy.start needs a valid recipient e-mail (the phone number is only for the SMS fallback on the device).';
  end if;
  if v_raw is distinct from v_name then
    v_warn := v_warn || '"traveler_name_sanitized"'::jsonb;
  end if;

  select * into v_prev from public.buddy_sessions where id = v_id for update;
  if found and v_prev.device_id is distinct from p_device.id then
    raise exception 'session_conflict' using errcode = '42501', detail = 'session id belongs to another device';
  end if;

  if v_prev.id is null and not app_private.is_reserved_email(v_email) then
    select count(*)::int into v_recent
    from public.buddy_sessions b
    where b.device_id = p_device.id
      and b.created_at > now() - interval '24 hours'
      and b.recipient_email is not null
      and not app_private.is_reserved_email(b.recipient_email);
    if v_recent >= app_private.limit_value('limit_buddy_start_device_24h', 5) then
      raise exception 'rate_limited' using errcode = '54000', detail = 'buddy_start_device_24h',
        hint = 'Too many Buddy sessions from this device in 24 h; the on-device alert still works.';
    end if;
  end if;

  -- one open session per device: close older open sessions (a late re-send of an
  -- already closed session must not close the session that replaced it)
  for v_old in
    select * from public.buddy_sessions
    where device_id = p_device.id and status <> 'closed' and id <> v_id
      and (v_prev.id is null or v_prev.status <> 'closed')
    for update
  loop
    update public.buddy_sessions set status = 'closed', closed_at = now() where id = v_old.id;
    perform app_private.insert_event(v_old, 'stop', null, null, null, null, now(), false,
                                     null, jsonb_build_object('reason', 'superseded', 'by', v_id));
  end loop;

  insert into public.buddy_sessions as b (
    id, device_id, traveler_name, recipient_name, recipient_email, recipient_phone,
    interval_min, grace_min, route_id, travel_mode, share_public_medical, public_medical,
    status, started_at, last_checkin_at, next_due_at, last_lat, last_lng, last_location_at)
  values (
    v_id, p_device.id,
    v_name,
    app_private.clean_name(coalesce(v -> 'recipient' ->> 'name', v ->> 'recipient_name'), 60),
    v_email,
    app_private.clean_text(coalesce(v -> 'recipient' ->> 'phone', v ->> 'recipient_phone'), 32),
    v_int, v_grace,
    app_private.clean_text(v ->> 'route_id', 64),
    app_private.clean_text(v ->> 'travel_mode', 20),
    v_share,
    case when v_share then app_private.sanitize_public_medical(v -> 'public_medical') end,
    'active', v_start, v_start, v_start + make_interval(mins => v_int),
    v_lat, v_lng, case when v_lat is not null then v_start end)
  on conflict (id) do update set          -- re-sent start of the same device: refresh settings
    traveler_name        = excluded.traveler_name,
    recipient_name       = excluded.recipient_name,
    recipient_email      = excluded.recipient_email,
    recipient_phone      = excluded.recipient_phone,
    interval_min         = excluded.interval_min,
    grace_min            = excluded.grace_min,
    route_id             = excluded.route_id,
    travel_mode          = excluded.travel_mode,
    share_public_medical = excluded.share_public_medical,
    public_medical       = excluded.public_medical
  returning * into s;

  if v_prev.id is null then
    perform app_private.insert_event(
      s, 'start',
      coalesce(app_private.try_uuid(p_data ->> 'event_id'), app_private.try_uuid(p_data -> 'event' ->> 'id')),
      v_lat, v_lng, app_private.try_num(v ->> 'accuracy_m')::numeric, v_start,
      coalesce(app_private.try_bool(v ->> 'queued'), false) or now() - v_start > interval '2 minutes', null,
      jsonb_build_object('interval_min', v_int, 'grace_min', v_grace));
  end if;
  return jsonb_build_object('session_id', s.id, 'status', s.status, 'next_due_at', s.next_due_at,
                            'received_at', now(), 'warnings', v_warn);
end $$;

-- ---- op: buddy.checkin (SOS sets alert_reason 'sos'; SOS after an overdue alert re-alerts) ----
create or replace function app_private.op_buddy_checkin(p_device public.devices, p_data jsonb, p_op_id uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v        jsonb := case when jsonb_typeof(p_data -> 'event') = 'object' then p_data -> 'event' else p_data end;
  v_kind   text := coalesce(nullif(v ->> 'kind', ''), 'checkin');
  v_ts     timestamptz := least(coalesce(app_private.try_ts(v ->> 'client_ts'), now()), now());
  v_lat    double precision := app_private.try_num(v ->> 'lat');
  v_lng    double precision := app_private.try_num(v ->> 'lng');
  v_queued boolean := coalesce(app_private.try_bool(v ->> 'queued'), now() - v_ts > interval '2 minutes');
  v_meta   jsonb := case when jsonb_typeof(v -> 'meta') = 'object' then v -> 'meta' end;
  s        public.buddy_sessions%rowtype;
  v_prev   text;
  v_last   timestamptz;
  v_event  uuid;
  v_notify boolean := false;   -- send the "all clear" (alerted → active)
  v_escalate boolean := false; -- send the alert now
begin
  if v_kind not in ('checkin', 'location', 'pre_deadzone', 'sos', 'overdue') then
    raise exception 'invalid_kind' using errcode = '22023', detail = v_kind;
  end if;
  if not (v_lat between -90 and 90 and v_lng between -180 and 180) then
    v_lat := null; v_lng := null;
  end if;
  if v_meta is not null and octet_length(v_meta::text) > 4000 then
    v_meta := jsonb_build_object('truncated', true);
  end if;

  s := app_private.op_session(p_device, coalesce(app_private.try_uuid(v ->> 'session_id'),
                                                 app_private.try_uuid(p_data ->> 'session_id')));
  v_prev := s.status;

  v_event := app_private.insert_event(
    s, v_kind,
    coalesce(app_private.try_uuid(v ->> 'event_id'), app_private.try_uuid(v ->> 'id')),
    v_lat, v_lng, app_private.try_num(v ->> 'accuracy_m')::numeric, v_ts, v_queued,
    v ->> 'note', v_meta);

  if s.status = 'closed' then
    return jsonb_build_object('event_id', v_event, 'received_at', now(), 'status', s.status,
                              'ignored', 'session_closed');
  end if;

  if v_lat is not null and (s.last_location_at is null or v_ts >= s.last_location_at) then
    s.last_lat := v_lat; s.last_lng := v_lng; s.last_location_at := v_ts;
  end if;

  if v_kind = 'checkin' then
    v_last := greatest(coalesce(s.last_checkin_at, v_ts), v_ts);
    s.last_checkin_at := v_last;
    s.next_due_at := v_last + make_interval(mins => s.interval_min);
    if s.status in ('overdue', 'alerted') then
      v_notify := (s.status = 'alerted');
      s.status := 'active';
      s.alerted_at := null;
      s.alert_reason := null;
      perform app_private.insert_event(s, 'resolved', null, v_lat, v_lng, null, now(), false, null,
                                       jsonb_build_object('reason', 'checkin', 'previous_status', v_prev));
    end if;
  elsif v_kind = 'sos' then
    -- SOS is an emergency: escalate an active session, and re-alert when the recipient was only
    -- told about a missed check-in (the next e-mail is worded as SOS). Same rule as backend-local.js.
    if s.status = 'active' or (s.status = 'alerted' and s.alert_reason is distinct from 'sos') then
      s.status := 'overdue';
      s.alerted_at := null;
      v_escalate := true;
    elsif s.status = 'overdue' and s.alert_reason is distinct from 'sos' then
      v_escalate := true;
    end if;
    if s.status in ('overdue', 'alerted') then
      s.alert_reason := 'sos';
    end if;
  elsif v_kind = 'overdue' and s.status = 'active' then
    -- overdue detected on the device while offline
    s.status := 'overdue';
    s.alerted_at := null;
    s.alert_reason := 'overdue';
    v_escalate := true;
  end if;

  update public.buddy_sessions set
    status           = s.status,
    alert_reason     = s.alert_reason,
    last_checkin_at  = s.last_checkin_at,
    next_due_at      = s.next_due_at,
    last_lat         = s.last_lat,
    last_lng         = s.last_lng,
    last_location_at = s.last_location_at,
    alerted_at       = s.alerted_at
  where id = s.id;

  if v_notify then
    perform app_private.notify_deadman(jsonb_build_object('session_id', s.id, 'type', 'resolved'));
  elsif v_escalate and s.recipient_email is not null then
    -- do not wait for the next cron tick (pg_net sends after this transaction commits)
    perform app_private.notify_deadman(jsonb_build_object('source', v_kind, 'type', 'overdue'));
  end if;
  return jsonb_build_object('event_id', v_event, 'received_at', now(), 'status', s.status,
                            'alert_reason', s.alert_reason, 'next_due_at', s.next_due_at);
end $$;

-- ---- op: buddy.update (consent withdrawn / given: medical layer of the open session) ----
create or replace function app_private.op_buddy_update(p_device public.devices, p_data jsonb, p_op_id uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  s       public.buddy_sessions%rowtype;
  v_share boolean;
begin
  s := app_private.op_session(p_device, coalesce(app_private.try_uuid(p_data ->> 'session_id'),
                                                 app_private.try_uuid(p_data ->> 'id')));
  if s.status = 'closed' then
    return jsonb_build_object('session_id', s.id, 'status', s.status, 'received_at', now(), 'ignored', 'session_closed');
  end if;
  v_share := coalesce(app_private.try_bool(p_data ->> 'share_public_medical'), s.share_public_medical);
  update public.buddy_sessions set
    share_public_medical = v_share,
    public_medical = case when not v_share then null
                          when p_data ? 'public_medical' then app_private.sanitize_public_medical(p_data -> 'public_medical')
                          else public_medical end
  where id = s.id
  returning * into s;
  return jsonb_build_object('session_id', s.id, 'status', s.status, 'share_public_medical', s.share_public_medical,
                            'has_public_medical', s.public_medical is not null, 'received_at', now());
end $$;

-- ---- op: device.erase (delete everything this device owns on the server) ----------
-- Open sessions are closed WITHOUT an alert and deleted with their events;
-- community reports stay but lose the device link; device_ops and the device
-- row go. If a recipient was alerted and never got the all-clear, it is sent
-- from an inline payload (the Edge Function cannot read the deleted row).
create or replace function app_private.op_device_erase(p_device public.devices, p_data jsonb, p_op_id uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  s          public.buddy_sessions%rowtype;
  v_sessions int := 0;
  v_events   int := 0;
  v_subs     int := 0;
  v_clear    int := 0;
  v_audit    text := current_setting('nc.audit', true);
begin
  for s in select * from public.buddy_sessions where device_id = p_device.id order by started_at for update loop
    if s.recipient_email is not null and app_private.all_clear_pending(s.id) then
      perform app_private.notify_deadman(jsonb_build_object(
        'type', 'resolved', 'session_id', s.id, 'source', 'erase',
        'inline', app_private.alert_payload(s, 'resolved', now())));
      v_clear := v_clear + 1;
    end if;
    if s.status <> 'closed' then
      update public.buddy_sessions set status = 'closed', closed_at = now() where id = s.id;
    end if;
  end loop;
  select count(*)::int into v_events
  from public.checkin_events e join public.buddy_sessions b on b.id = e.session_id
  where b.device_id = p_device.id;
  delete from public.buddy_sessions where device_id = p_device.id;          -- events cascade
  get diagnostics v_sessions = row_count;
  -- unlink community reports without copying the device id into the audit trail,
  -- and drop it from the snapshots the trail already holds
  perform set_config('nc.audit', 'off', true);
  update public.facility_submissions set device_id = null where device_id = p_device.id;
  get diagnostics v_subs = row_count;
  perform set_config('nc.audit', coalesce(nullif(v_audit, ''), 'on'), true);
  update public.audit_log set details = jsonb_set(details, '{row,device_id}', 'null'::jsonb)
   where entity = 'facility_submissions' and details -> 'row' ->> 'device_id' = p_device.id::text;
  delete from public.devices where id = p_device.id;                         -- device_ops cascade
  return jsonb_build_object('erased', true, 'sessions_deleted', v_sessions, 'events_deleted', v_events,
                            'submissions_unlinked', v_subs, 'all_clear_sent', v_clear, 'received_at', now());
end $$;

-- ---- dispatcher (+ buddy.update, device.erase) ---------------------------------------
create or replace function app_private.apply_device_op(p_device public.devices, p_op text, p_data jsonb, p_op_id uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
begin
  if p_data is null or jsonb_typeof(p_data) not in ('object', 'array') then
    p_data := '{}'::jsonb;
  end if;
  case p_op
    when 'device.register' then
      update public.devices set
        carrier     = coalesce((select c.id from public.carriers c where c.id = p_data ->> 'carrier'), carrier),
        app_version = coalesce(app_private.clean_text(p_data ->> 'app_version', 40), app_version)
      where id = p_device.id;
      return jsonb_build_object('device_id', p_device.id);
    when 'buddy.start'   then return app_private.op_buddy_start(p_device, p_data, p_op_id);
    when 'buddy.checkin' then return app_private.op_buddy_checkin(p_device, p_data, p_op_id);
    when 'buddy.stop'    then return app_private.op_buddy_stop(p_device, p_data, p_op_id);
    when 'buddy.resolve' then return app_private.op_buddy_resolve(p_device, p_data, p_op_id);
    when 'buddy.update'  then return app_private.op_buddy_update(p_device, p_data, p_op_id);
    when 'report.submit' then return app_private.op_report_submit(p_device, p_data, p_op_id);
    when 'signal.log'    then return app_private.op_signal_log(p_device, p_data, p_op_id);
    when 'device.erase'  then return app_private.op_device_erase(p_device, p_data, p_op_id);
    else
      raise exception 'unknown_op' using errcode = '22023', detail = coalesce(p_op, 'null');
  end case;
end $$;

-- Batch sync (as 0500) + device.erase: ops after an erase in the same batch get
-- 'device_erased'; a batch with device.erase for a device that no longer exists
-- (tombstone replay) succeeds without touching anything.
create or replace function public.sync_device_ops(p_device_id uuid, p_secret text, p_ops jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  d        public.devices%rowtype;
  v_ops    jsonb := coalesce(p_ops, '[]'::jsonb);
  v_op     jsonb;
  v_id     uuid;
  v_kind   text;
  v_data   jsonb;
  v_prev   jsonb;
  v_res    jsonb := '[]'::jsonb;
  v_msg    text;
  v_state  text;
  v_erased boolean := false;
  v_tomb   boolean := false;
begin
  -- nested tests: AND does not guarantee evaluation order (jsonb_array_length raises on a non-array)
  if jsonb_typeof(v_ops) = 'array' then
    if jsonb_array_length(v_ops) <= 200 then
      v_tomb := exists (select 1 from jsonb_array_elements(v_ops) o where o ->> 'op' = 'device.erase')
                and not exists (select 1 from public.devices x where x.id = p_device_id);
    end if;
  end if;
  if v_tomb then
    return jsonb_build_object(
      'results', coalesce((
        select jsonb_agg(case when o ->> 'op' = 'device.erase'
                              then jsonb_build_object('id', o -> 'id', 'status', 'ok',
                                                      'data', jsonb_build_object('erased', true, 'already_erased', true))
                              else jsonb_build_object('id', o -> 'id', 'status', 'error', 'error', 'device_erased',
                                                      'retryable', false) end order by n)
        from jsonb_array_elements(v_ops) with ordinality as x(o, n)), '[]'::jsonb),
      'server_time', now(),
      'session', null);
  end if;

  d := app_private.verify_device(p_device_id, p_secret);
  if jsonb_typeof(v_ops) <> 'array' then
    raise exception 'invalid_ops' using errcode = '22023';
  end if;
  if jsonb_array_length(v_ops) > 200 then
    raise exception 'too_many_ops' using errcode = '22023', hint = 'Send at most 200 ops per call.';
  end if;
  update public.devices set last_seen_at = now() where id = d.id;

  for v_op in select e.value from jsonb_array_elements(v_ops) with ordinality as e(value, n) order by e.n loop
    v_id := app_private.try_uuid(v_op ->> 'id');
    v_kind := v_op ->> 'op';
    if v_erased then
      v_res := v_res || jsonb_build_array(jsonb_build_object(
        'id', v_op -> 'id', 'status', 'error', 'error', 'device_erased', 'retryable', false));
      continue;
    end if;
    if v_id is null then
      v_res := v_res || jsonb_build_array(jsonb_build_object(
        'id', v_op -> 'id', 'status', 'error', 'error', 'invalid_op_id', 'retryable', false));
      continue;
    end if;
    begin
      insert into public.device_ops (id, device_id, op) values (v_id, d.id, coalesce(v_kind, '?'))
      on conflict (id) do nothing;
      if not found then
        select o.result into v_prev from public.device_ops o where o.id = v_id;
        v_res := v_res || jsonb_build_array(jsonb_build_object(
          'id', v_id, 'status', 'duplicate', 'data', v_prev -> 'data'));
        continue;
      end if;
      v_data := app_private.apply_device_op(d, v_kind, v_op -> 'data', v_id);
      if v_kind = 'device.erase' then
        v_erased := true;                 -- the device row and its device_ops are gone
      else
        update public.device_ops set result = jsonb_build_object('status', 'ok', 'data', v_data) where id = v_id;
      end if;
      v_res := v_res || jsonb_build_array(jsonb_build_object('id', v_id, 'status', 'ok', 'data', v_data));
    exception when others then
      get stacked diagnostics v_msg = message_text, v_state = returned_sqlstate;
      -- 54000 = rate_limited (buddy.start over the per-device limit): permanent for that op. A retried
      -- start would land once the 24 h window slides, backdated to its queue time, i.e. already overdue,
      -- possibly after the user stopped the session: a false alarm to the contact.
      v_res := v_res || jsonb_build_array(jsonb_build_object(
        'id', v_id, 'status', 'error', 'error', v_msg, 'code', v_state,
        'retryable', not (v_state like '22%' or v_state like '23%' or v_state in ('P0002', '28000', '42501', '54000'))));
    end;
  end loop;

  return jsonb_build_object(
    'results',     v_res,
    'server_time', now(),
    'session',     case when v_erased then null else app_private.device_session_json(d.id) end);
end $$;

-- =============================================================================
-- 8. Cron / Edge Function API
-- =============================================================================
create or replace function public.nc_dispatch_alerts()
returns int
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_n   int;
  v_req bigint;
begin
  if not (app_private.is_trusted_caller() or public.is_admin()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  perform app_private.flag_rate_limited();
  select count(*)::int into v_n from public.buddy_sessions s where app_private.alert_due(s);
  if v_n = 0 then
    return 0;
  end if;
  if app_private.setting('functions_url') is null then
    raise notice 'nc_dispatch_alerts: % alert(s) due but app_private.settings.functions_url is not set', v_n;
    return 0;
  end if;
  if not app_private.has_pg_net() then
    raise notice 'nc_dispatch_alerts: % alert(s) due but pg_net is not installed', v_n;
    return 0;
  end if;
  v_req := app_private.notify_deadman(jsonb_build_object('source', 'cron', 'type', 'overdue'));
  return case when v_req is null then 0 else v_n end;
end $$;

-- Daily retention job.
create or replace function public.nc_cleanup()
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_ops      int;
  v_sessions int;
  v_events   int;
  v_ips      int;
begin
  if not (app_private.is_trusted_caller() or public.is_admin()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  delete from public.device_ops where received_at < now() - interval '30 days';
  get diagnostics v_ops = row_count;
  -- closed > 30 days ago, or abandoned (no change for 90 days): session + events (cascade)
  with old as (
    select s.id from public.buddy_sessions s
    where (s.status = 'closed' and coalesce(s.closed_at, s.updated_at) < now() - interval '30 days')
       or (s.status <> 'closed' and s.updated_at < now() - interval '90 days')
  ), ev as (
    select count(*)::int as n from public.checkin_events e where e.session_id in (select id from old)
  ), del as (
    delete from public.buddy_sessions s using old where s.id = old.id returning 1
  )
  select (select count(*)::int from del), (select n from ev) into v_sessions, v_events;
  update public.devices set reg_ip_hash = null
   where reg_ip_hash is not null and created_at < now() - interval '24 hours';
  get diagnostics v_ips = row_count;
  return jsonb_build_object('device_ops_deleted', v_ops, 'sessions_deleted', v_sessions,
                            'events_deleted', v_events, 'ip_hashes_cleared', v_ips, 'at', now());
end $$;

-- Claims sessions to alert (see 0800) + p_actor (admin behind a manual trigger)
-- + abuse quota on the cron path (re-checked for every claim of the batch).
drop function if exists public.nc_alert_claim(uuid, text, boolean, int);
create or replace function public.nc_alert_claim(p_session_id uuid default null, p_type text default 'overdue',
                                                 p_force boolean default false, p_limit int default 25,
                                                 p_actor uuid default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  s        public.buddy_sessions%rowtype;
  v_out    jsonb := '[]'::jsonb;
  v_now    timestamptz := now();
  v_alert  timestamptz;
  v_clear  timestamptz;
begin
  if not app_private.is_trusted_caller() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if p_type not in ('overdue', 'resolved') then
    raise exception 'invalid_type' using errcode = '22023', detail = coalesce(p_type, 'null');
  end if;
  perform app_private.set_actor(p_actor);

  if p_type = 'resolved' then
    select * into s from public.buddy_sessions where id = p_session_id;
    if not found or s.recipient_email is null or s.status not in ('active', 'closed') then
      return v_out;
    end if;
    select max(e.received_at) filter (where coalesce(e.meta ->> 'type', 'overdue') <> 'resolved'),
           max(e.received_at) filter (where e.meta ->> 'type' = 'resolved')
      into v_alert, v_clear
    from public.checkin_events e
    where e.session_id = s.id and e.kind = 'alert_sent';
    if p_force or (v_alert is not null and (v_clear is null or v_clear < v_alert)) then
      v_out := jsonb_build_array(app_private.alert_payload(s, 'resolved', v_now));
    end if;
    return v_out;
  end if;

  if p_session_id is not null and p_force then
    -- manual trigger by an admin: never rate-limited
    select * into s from public.buddy_sessions where id = p_session_id for update;
    if not found or s.status = 'closed' or s.recipient_email is null then
      return v_out;
    end if;
    if s.status in ('overdue', 'active') then
      update public.buddy_sessions set alerted_at = v_now where id = s.id returning * into s;
    end if;
    return jsonb_build_array(app_private.alert_payload(s, 'overdue', v_now));
  end if;

  perform app_private.flag_rate_limited();
  for s in
    select * from public.buddy_sessions b
    where app_private.alert_due(b) and (p_session_id is null or b.id = p_session_id)
    order by b.next_due_at nulls last
    limit greatest(1, least(coalesce(p_limit, 25), 100))
    for update skip locked
  loop
    -- an earlier claim of this batch may have used the recipient's quota
    if app_private.alert_quota_block(s.recipient_email) is not null then
      perform app_private.flag_rate_limited(s.id);
      continue;
    end if;
    update public.buddy_sessions set alerted_at = v_now where id = s.id returning * into s;
    v_out := v_out || jsonb_build_array(app_private.alert_payload(s, 'overdue', v_now));
  end loop;
  return v_out;
end $$;

-- Records the outcome of one e-mail (see 0800) + p_actor, p_reason (reason the
-- e-mail was worded with). An overdue e-mail that crossed an SOS keeps the
-- session 'overdue' so the SOS e-mail follows on the next tick.
drop function if exists public.nc_alert_result(uuid, boolean, text, text, text, text, text);
create or replace function public.nc_alert_result(p_session_id uuid, p_ok boolean, p_type text default 'overdue',
                                                  p_provider text default 'resend', p_provider_id text default null,
                                                  p_error text default null, p_trigger text default 'cron',
                                                  p_actor uuid default null, p_reason text default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  s           public.buddy_sessions%rowtype;
  v_meta      jsonb;
  v_label     text;
  v_all_clear boolean := false;
begin
  if not app_private.is_trusted_caller() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  v_label := app_private.set_actor(p_actor);
  select * into s from public.buddy_sessions where id = p_session_id for update;
  if not found then
    raise exception 'session_not_found' using errcode = 'P0002';
  end if;
  v_meta := jsonb_strip_nulls(jsonb_build_object(
    'type', coalesce(p_type, 'overdue'), 'provider', p_provider, 'id', p_provider_id,
    'error', left(p_error, 500), 'trigger', p_trigger,
    'reason', case when p_ok then p_reason else 'send_failed' end,
    'alert_reason', case when not p_ok then p_reason end,
    'actor', v_label));

  if coalesce(p_type, 'overdue') = 'overdue' then
    if p_ok then
      if s.status = 'overdue' and s.alert_reason = 'sos' and p_reason is not null and p_reason <> 'sos' then
        -- the traveller pressed SOS while the missed-check-in e-mail was on its way
        update public.buddy_sessions set alerted_at = null where id = s.id returning * into s;
      elsif s.status = 'overdue' or (p_trigger = 'manual' and s.status in ('active', 'alerted')) then
        update public.buddy_sessions set status = 'alerted', alerted_at = now()
         where id = s.id returning * into s;
      elsif s.status = 'active' then
        -- the traveller checked in while the email was being sent → follow up with "all clear"
        update public.buddy_sessions set alerted_at = null where id = s.id returning * into s;
        v_all_clear := true;
      end if;
    elsif s.status in ('overdue', 'active') then
      update public.buddy_sessions set alerted_at = null where id = s.id returning * into s;
    end if;
  end if;

  perform app_private.insert_event(s, case when p_ok then 'alert_sent' else 'alert_failed' end,
                                   null, null, null, null, now(), false, null, v_meta);
  if v_all_clear then
    perform app_private.notify_deadman(jsonb_build_object('session_id', s.id, 'type', 'resolved'));
  end if;
  return jsonb_build_object('session_id', s.id, 'status', s.status, 'alerted_at', s.alerted_at,
                            'alert_reason', s.alert_reason);
end $$;

-- =============================================================================
-- 9. Pack publishing: content comparison, no-op publish, change report
-- =============================================================================

-- Pack content without the fields that change on every build or every day
-- (version, published_at, size_bytes, facility freshness).
create or replace function app_private.pack_content(p jsonb)
returns jsonb
language sql
immutable
set search_path = public, extensions, pg_temp
as $$
  select case when p is null or jsonb_typeof(p) <> 'object' then null else
    (p - array['version', 'published_at', 'size_bytes', 'source', 'facilities'])
    || jsonb_build_object('facilities', coalesce((
         select jsonb_agg(f - array['is_stale', 'days_since_verified'] order by f ->> 'id')
         from jsonb_array_elements(case when jsonb_typeof(p -> 'facilities') = 'array'
                                        then p -> 'facilities' else '[]'::jsonb end) f), '[]'::jsonb))
  end
$$;

create or replace function app_private.pack_content_hash(p jsonb)
returns text
language sql
immutable
set search_path = public, extensions, pg_temp
as $$
  select case when p is null then null else encode(digest(app_private.pack_content(p)::text, 'sha256'), 'hex') end
$$;

-- {added:[{id,name,type}], removed:[{id,name,type,reason}], updated:[{id,name,type,fields}]}
-- between two pack item arrays; removed.reason = deleted | pending | rejected |
-- inactive | moved (still listed but no longer in this route's corridor).
create or replace function app_private.pack_item_diff(p_pub jsonb, p_live jsonb, p_facility boolean)
returns jsonb
language sql
stable
security definer
set search_path = public, extensions, pg_temp
as $$
  with pub as (
    select x ->> 'id' as id, x - array['is_stale', 'days_since_verified'] as j
    from jsonb_array_elements(case when jsonb_typeof(p_pub) = 'array' then p_pub else '[]'::jsonb end) x
  ), live as (
    select x ->> 'id' as id, x - array['is_stale', 'days_since_verified'] as j
    from jsonb_array_elements(case when jsonb_typeof(p_live) = 'array' then p_live else '[]'::jsonb end) x
  )
  select jsonb_build_object(
    'added', coalesce((
      select jsonb_agg(jsonb_build_object('id', l.id, 'name', l.j ->> 'name', 'type', l.j ->> 'type')
                       order by l.j ->> 'name', l.id)
      from live l where not exists (select 1 from pub p where p.id = l.id)), '[]'::jsonb),
    'removed', coalesce((
      select jsonb_agg(jsonb_build_object('id', p.id, 'name', p.j ->> 'name', 'type', p.j ->> 'type',
               'reason', case
                 when p_facility then (select case when f.id is null then 'deleted'
                                                   when f.status <> 'verified' then f.status else 'moved' end
                                       from (select 1) one left join public.facilities f on f.id = p.id)
                 else (select case when sv.id is null then 'deleted'
                                   when sv.status <> 'active' then sv.status else 'moved' end
                       from (select 1) one left join public.services sv on sv.id = p.id)
               end) order by p.j ->> 'name', p.id)
      from pub p where not exists (select 1 from live l where l.id = p.id)), '[]'::jsonb),
    'updated', coalesce((
      select jsonb_agg(jsonb_build_object('id', l.id, 'name', l.j ->> 'name', 'type', l.j ->> 'type',
               'fields', (select coalesce(jsonb_agg(k order by k), '[]'::jsonb)
                          from jsonb_object_keys(l.j || p.j) k
                          where (l.j -> k) is distinct from (p.j -> k)))
             order by l.j ->> 'name', l.id)
      from live l join pub p on p.id = l.id
      where l.j is distinct from p.j), '[]'::jsonb))
$$;

-- Snapshot the live pack as version = max + 1 — unless its content equals the
-- current pack (then the current one is returned with unchanged = true).
drop function if exists app_private.publish_pack(text, text, text, uuid);
create or replace function app_private.publish_pack(p_route_id text, p_carrier text, p_notes text default null,
                                                    p_actor uuid default null, p_force boolean default false)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_version int;
  v_now     timestamptz := now();
  v_payload jsonb;
  v_size    int;
  v_sum     text;
  c         public.data_packs%rowtype;
begin
  perform pg_advisory_xact_lock(hashtext('nomadcare.pack:' || coalesce(p_route_id, '') || ':' || coalesce(p_carrier, '')));
  select coalesce(max(p.version), 0) + 1 into v_version
  from public.data_packs p where p.route_id = p_route_id and p.carrier = p_carrier;

  v_payload := app_private.build_pack(p_route_id, p_carrier, v_version, v_now);   -- raises if unknown

  select * into c from public.data_packs p
  where p.route_id = p_route_id and p.carrier = p_carrier and p.is_current
  order by p.version desc limit 1;
  if not coalesce(p_force, false) and c.id is not null and c.payload is not null
     and app_private.pack_content_hash(c.payload) = app_private.pack_content_hash(v_payload) then
    return jsonb_build_object('route_id', p_route_id, 'carrier', p_carrier, 'version', c.version,
                              'size_bytes', c.size_bytes, 'checksum', c.checksum, 'published_at', c.published_at,
                              'unchanged', true);
  end if;

  v_size := (v_payload ->> 'size_bytes')::int;
  v_sum := encode(digest(v_payload::text, 'sha256'), 'hex');
  update public.data_packs set is_current = false
   where route_id = p_route_id and carrier = p_carrier and is_current;
  insert into public.data_packs (route_id, carrier, version, published_at, published_by, notes,
                                 size_bytes, checksum, payload, is_current)
  values (p_route_id, p_carrier, v_version, v_now, p_actor, app_private.clean_text(p_notes, 500),
          v_size, v_sum, v_payload, true);

  return jsonb_build_object('route_id', p_route_id, 'carrier', p_carrier, 'version', v_version,
                            'size_bytes', v_size, 'checksum', v_sum, 'published_at', v_now, 'unchanged', false);
end $$;

drop function if exists public.admin_publish_pack(text, text, text);
create or replace function public.admin_publish_pack(p_route_id text, p_carrier text, p_notes text default null,
                                                     p_force boolean default false)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
begin
  perform app_private.require_admin();
  return app_private.publish_pack(p_route_id, p_carrier, p_notes, auth.uid(), p_force);
end $$;

-- Unpublished changes per route × carrier (closures and deletions included):
-- [{route_id, carrier, version, published_at, published, changed, count,
--   facilities:{added,removed,updated}, services:{…}, other:[section…],
--   live_checksum, published_checksum}]
create or replace function public.admin_pack_changes(p_route_id text default null, p_carrier text default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  r       record;
  c       public.data_packs%rowtype;
  v_live  jsonb;
  v_pub   jsonb;
  v_fac   jsonb;
  v_svc   jsonb;
  v_other jsonb;
  v_out   jsonb := '[]'::jsonb;
begin
  perform app_private.require_admin();
  for r in
    select ro.id as route_id, ca.id as carrier
    from public.routes ro cross join public.carriers ca
    where ro.is_active and (p_route_id is null or ro.id = p_route_id) and (p_carrier is null or ca.id = p_carrier)
    order by ro.sort, ro.id, ca.sort, ca.id
  loop
    select * into c from public.data_packs p
    where p.route_id = r.route_id and p.carrier = r.carrier and p.is_current
    order by p.version desc limit 1;
    v_pub := c.payload;
    v_live := app_private.build_pack(r.route_id, r.carrier, coalesce(c.version, 0), coalesce(c.published_at, now()));
    v_fac := app_private.pack_item_diff(v_pub -> 'facilities', v_live -> 'facilities', true);
    v_svc := app_private.pack_item_diff(v_pub -> 'services', v_live -> 'services', false);
    select coalesce(jsonb_agg(k order by k), '[]'::jsonb) into v_other
    from unnest(array['schema', 'route', 'nodes', 'edges', 'segments', 'model_version', 'accuracy', 'holdout_n']) k
    where v_pub is not null and (v_pub -> k) is distinct from (v_live -> k);
    v_out := v_out || jsonb_build_array(jsonb_build_object(
      'route_id',     r.route_id,
      'carrier',      r.carrier,
      'version',      coalesce(c.version, 0),
      'published_at', c.published_at,
      'published',    v_pub is not null,
      'changed',      v_pub is null or app_private.pack_content_hash(v_pub) is distinct from app_private.pack_content_hash(v_live),
      'count',        jsonb_array_length(v_fac -> 'added') + jsonb_array_length(v_fac -> 'removed')
                      + jsonb_array_length(v_fac -> 'updated') + jsonb_array_length(v_svc -> 'added')
                      + jsonb_array_length(v_svc -> 'removed') + jsonb_array_length(v_svc -> 'updated')
                      + jsonb_array_length(v_other),
      'facilities',   v_fac,
      'services',     v_svc,
      'other',        v_other,
      'live_checksum',      app_private.pack_content_hash(v_live),
      'published_checksum', app_private.pack_content_hash(v_pub)));
  end loop;
  return v_out;
end $$;

-- =============================================================================
-- 10. Admin RPCs: submissions, samples, facilities
-- =============================================================================
create or replace function public.admin_review_submission(p_id text, p_status text, p_note text default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  s        public.facility_submissions%rowtype;
  p        jsonb;
  v_fac    text;
  v_lat    double precision;
  v_lng    double precision;
  v_route  text;
  v_type   text;
  v_note   text := app_private.clean_text(p_note, 500);
begin
  perform app_private.require_admin();
  if p_status not in ('approved', 'rejected', 'pending') then
    raise exception 'invalid_status' using errcode = '22023', detail = coalesce(p_status, 'null');
  end if;
  select * into s from public.facility_submissions where id = p_id for update;
  if not found then
    raise exception 'submission_not_found' using errcode = 'P0002', detail = coalesce(p_id, 'null');
  end if;
  p := coalesce(s.payload, '{}'::jsonb);
  v_fac := s.facility_id;

  if p_status = 'approved' and s.status <> 'approved' then
    if s.kind = 'new' then
      if v_fac is not null and exists (select 1 from public.facilities x where x.id = v_fac) then
        null;   -- re-approval of a reopened report: keep the facility created the first time
      else
        v_lat := coalesce(s.lat, app_private.try_num(p ->> 'lat'));
        v_lng := coalesce(s.lng, app_private.try_num(p ->> 'lng'));
        v_type := case when p ->> 'type' in ('tram_y_te', 'phong_kham', 'benh_vien', 'nha_thuoc') then p ->> 'type' end;
        v_route := case when exists (select 1 from public.routes r where r.id = p ->> 'route_id') then p ->> 'route_id' end;
        if v_route is null and v_lat is not null then
          select e.route_id into v_route
          from public.route_edges e
          where ST_DWithin(e.geom, app_private.pt(v_lat, v_lng), 20000)
          order by e.geom <-> app_private.pt(v_lat, v_lng)
          limit 1;
        end if;
        insert into public.facilities (id, route_id, name, type, address, geom, phone, open_hours,
                                       status, source, notes)
        values (coalesce(v_fac, gen_random_uuid()::text), v_route,
                coalesce(app_private.clean_text(p ->> 'name', 160), 'Điểm y tế cộng đồng đề xuất'),
                v_type,
                app_private.clean_text(p ->> 'address', 300),
                app_private.pt(v_lat, v_lng),
                app_private.clean_text(p ->> 'phone', 32),
                app_private.clean_text(p ->> 'open_hours', 120),
                'pending', 'community',
                concat_ws(E'\n', 'Từ đóng góp cộng đồng #' || s.id, app_private.clean_text(p ->> 'note', 500), v_note))
        returning id into v_fac;
      end if;
    elsif s.kind = 'closed' and v_fac is not null then
      update public.facilities
         set status = case when status = 'verified' then 'pending' else status end,
             notes  = case when position('(#' || s.id || ')' in coalesce(notes, '')) > 0 then notes
                           else concat_ws(E'\n', notes, 'Báo đóng cửa (#' || s.id || ')' || coalesce(': ' || v_note, '')) end
       where id = v_fac;
    elsif s.kind = 'correction' and v_fac is not null then
      update public.facilities
         set notes = case when position('(#' || s.id || ')' in coalesce(notes, '')) > 0 then notes
                          else concat_ws(E'\n', notes, 'Đề xuất sửa (#' || s.id || '): '
                                         || coalesce(app_private.clean_text(p ->> 'note', 500), p::text)) end
       where id = v_fac;
    end if;
  end if;

  update public.facility_submissions set
    status      = p_status,
    review_note = v_note,
    reviewed_by = auth.uid(),
    reviewed_at = now(),
    facility_id = v_fac
  where id = s.id
  returning * into s;

  return jsonb_build_object('id', s.id, 'kind', s.kind, 'status', s.status,
                            'facility_id', s.facility_id, 'reviewed_at', s.reviewed_at);
end $$;

-- Only rows whose status changes are counted; one aggregated audit row per call.
create or replace function public.admin_review_samples(p_ids bigint[], p_status text)
returns int
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_n     int;
  v_ids   bigint[];
  v_actor uuid;
begin
  perform app_private.require_admin();
  if p_status not in ('approved', 'pending', 'rejected') then
    raise exception 'invalid_status' using errcode = '22023', detail = coalesce(p_status, 'null');
  end if;
  with u as (
    update public.signal_samples set status = p_status
     where id = any (coalesce(p_ids, '{}')) and status is distinct from p_status
    returning id
  )
  select count(*)::int, array_agg(id order by id) into v_n, v_ids from u;
  if v_n > 0 and coalesce(current_setting('nc.audit', true), 'on') <> 'off' then
    v_actor := coalesce(auth.uid(), app_private.try_uuid(current_setting('nc.actor_id', true)));
    insert into public.audit_log (actor, actor_label, action, entity, entity_id, details)
    values (v_actor, app_private.actor_label(v_actor), 'status', 'signal_samples', 'batch',
            jsonb_build_object('count', v_n, 'status', p_status, 'ids', to_jsonb(v_ids[1:50]),
                               'truncated', v_n > 50));
  end if;
  return v_n;
end $$;

-- As 0600 + 'invalid_date' (verification date in the future) and a Vietnam
-- bounding box for verified facilities ('invalid_coordinates', detail outside_vietnam).
create or replace function public.admin_upsert_facility(p_row jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  f        public.facilities%rowtype;
  v_exists boolean := false;
  v_miss   text[];
  v_lat    double precision;
  v_lng    double precision;
begin
  perform app_private.require_admin();
  if p_row is null or jsonb_typeof(p_row) <> 'object' then
    raise exception 'invalid_row' using errcode = '22023';
  end if;
  if p_row ? 'id' and nullif(p_row ->> 'id', '') is not null then
    select * into f from public.facilities where id = p_row ->> 'id' for update;
    v_exists := found;
    f.id := p_row ->> 'id';
  else
    f.id := gen_random_uuid()::text;
  end if;
  if not v_exists then
    f.status := 'pending'; f.source := 'team'; f.is_demo := true;
  end if;

  if p_row ? 'route_id'       then f.route_id := nullif(p_row ->> 'route_id', ''); end if;
  if p_row ? 'name'           then f.name := app_private.clean_text(p_row ->> 'name', 160); end if;
  if p_row ? 'type'           then f.type := nullif(p_row ->> 'type', ''); end if;
  if p_row ? 'address'        then f.address := app_private.clean_text(p_row ->> 'address', 300); end if;
  if p_row ? 'phone'          then f.phone := app_private.clean_text(p_row ->> 'phone', 32); end if;
  if p_row ? 'open_hours'     then f.open_hours := app_private.clean_text(p_row ->> 'open_hours', 120); end if;
  if p_row ? 'night_shift'    then f.night_shift := app_private.try_bool(p_row ->> 'night_shift'); end if;
  if p_row ? 'trauma_capable' then f.trauma_capable := app_private.try_bool(p_row ->> 'trauma_capable'); end if;
  if p_row ? 'verified_by'    then f.verified_by := app_private.clean_text(p_row ->> 'verified_by', 120); end if;
  if p_row ? 'verified_at'    then f.verified_at := app_private.try_ts(p_row ->> 'verified_at')::date; end if;
  if p_row ? 'status'         then f.status := coalesce(nullif(p_row ->> 'status', ''), f.status); end if;
  if p_row ? 'source'         then f.source := coalesce(nullif(p_row ->> 'source', ''), f.source); end if;
  if p_row ? 'notes'          then f.notes := app_private.clean_text(p_row ->> 'notes', 2000); end if;
  if p_row ? 'is_demo'        then f.is_demo := coalesce(app_private.try_bool(p_row ->> 'is_demo'), f.is_demo); end if;
  if p_row ? 'lat' or p_row ? 'lng' then
    v_lat := app_private.try_num(p_row ->> 'lat');
    v_lng := app_private.try_num(p_row ->> 'lng');
    if v_lat is null or v_lng is null then
      f.geom := null;
    elsif v_lat between -90 and 90 and v_lng between -180 and 180 then
      f.geom := app_private.pt(v_lat, v_lng);
    else
      raise exception 'invalid_coordinates' using errcode = '22023';
    end if;
  end if;

  if not v_exists and p_row ? 'id' and not (p_row ? 'name') then
    raise exception 'facility_not_found' using errcode = 'P0002', detail = p_row ->> 'id';
  end if;
  if f.type is not null and f.type not in ('tram_y_te', 'phong_kham', 'benh_vien', 'nha_thuoc') then
    raise exception 'invalid_type' using errcode = '22023', detail = f.type;
  end if;
  if f.status is null or f.status not in ('verified', 'pending', 'rejected') then
    raise exception 'invalid_status' using errcode = '22023', detail = coalesce(f.status, 'null');
  end if;
  -- a typo like 2062 would otherwise keep a facility "fresh" for decades (one day of
  -- tolerance for admins in time zones ahead of Vietnam)
  if f.verified_at is not null and (f.verified_at > app_private.today_vn() + 1 or f.verified_at < date '2000-01-01') then
    raise exception 'invalid_date' using errcode = '22023', detail = f.verified_at::text,
      hint = 'The verification date cannot be in the future.';
  end if;
  if f.status = 'verified' and f.geom is not null
     and not (ST_Y(f.geom::geometry) between 8.1 and 23.5 and ST_X(f.geom::geometry) between 102.1 and 109.6) then
    raise exception 'invalid_coordinates' using errcode = '22023', detail = 'outside_vietnam',
      hint = 'A verified facility must be inside Vietnam (lat 8.1–23.5, lng 102.1–109.6).';
  end if;

  if f.status = 'verified' then
    v_miss := app_private.facility_missing_fields(f);
    if cardinality(v_miss) > 0 then
      raise exception 'incomplete' using errcode = '23514',
        detail = to_jsonb(v_miss)::text,
        hint = 'A verified facility needs every field (PDF 8.1); keep it pending until complete.';
    end if;
  end if;

  if v_exists then
    update public.facilities set
      route_id = f.route_id, name = f.name, type = f.type, address = f.address, geom = f.geom,
      phone = f.phone, open_hours = f.open_hours, night_shift = f.night_shift,
      trauma_capable = f.trauma_capable, verified_by = f.verified_by, verified_at = f.verified_at,
      status = f.status, source = f.source, notes = f.notes, is_demo = f.is_demo
    where id = f.id;
  else
    insert into public.facilities (id, route_id, name, type, address, geom, phone, open_hours, night_shift,
                                   trauma_capable, verified_by, verified_at, status, source, notes, is_demo)
    values (f.id, f.route_id, f.name, f.type, f.address, f.geom, f.phone, f.open_hours, f.night_shift,
            f.trauma_capable, f.verified_by, f.verified_at, f.status, f.source, f.notes, f.is_demo);
  end if;
  return (select to_jsonb(v) from public.v_facilities v where v.id = f.id);
end $$;

-- =============================================================================
-- 11. Realtime: packs, content releases, services, audit log
-- =============================================================================
do $$
declare
  t text;
begin
  if not exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    raise notice 'publication supabase_realtime not found: realtime not configured (dashboard falls back to polling)';
    return;
  end if;
  if (select puballtables from pg_publication where pubname = 'supabase_realtime') then
    return;
  end if;
  foreach t in array array['data_packs', 'content_releases', 'services', 'audit_log'] loop
    if exists (select 1 from pg_publication_tables
                where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
      continue;
    end if;
    if t = 'data_packs' and current_setting('server_version_num')::int >= 150000 then
      -- the pack payload (tens of kB) is not needed live: the dashboard re-reads the list
      begin
        execute 'alter publication supabase_realtime add table public.data_packs (id, route_id, carrier, version, '
             || 'published_at, published_by, notes, size_bytes, checksum, is_current)';
        continue;
      exception when others then
        raise notice 'publication column list not supported (%): publishing data_packs with all columns', sqlerrm;
      end;
    end if;
    execute format('alter publication supabase_realtime add table public.%I', t);
  end loop;
end $$;

-- =============================================================================
-- 12. Privileges (re-run of the 0900 sweep for the functions defined here)
-- =============================================================================
do $$
declare
  f text;
  has_roles boolean := exists (select 1 from pg_roles where rolname = 'anon');
begin
  foreach f in array array['public.register_device(text, text)', 'public.sync_device_ops(uuid, text, jsonb)'] loop
    execute format('revoke all on function %s from public', f);
    if has_roles then
      execute format('grant execute on function %s to anon, authenticated, service_role', f);
    end if;
  end loop;
  foreach f in array array['public.admin_publish_pack(text, text, text, boolean)',
                           'public.admin_pack_changes(text, text)',
                           'public.admin_review_submission(text, text, text)',
                           'public.admin_review_samples(bigint[], text)',
                           'public.admin_upsert_facility(jsonb)',
                           'public.nc_dispatch_alerts()', 'public.nc_cleanup()'] loop
    execute format('revoke all on function %s from public', f);
    if has_roles then
      execute format('revoke all on function %s from anon', f);
      execute format('grant execute on function %s to authenticated, service_role', f);
    end if;
  end loop;
  foreach f in array array['public.nc_alert_claim(uuid, text, boolean, int, uuid)',
                           'public.nc_alert_result(uuid, boolean, text, text, text, text, text, uuid, text)'] loop
    execute format('revoke all on function %s from public', f);
    if has_roles then
      execute format('revoke all on function %s from anon, authenticated', f);
      execute format('grant execute on function %s to service_role', f);
    end if;
  end loop;
end $$;

revoke all on all functions in schema app_private from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on all functions in schema app_private from anon, authenticated';
    execute 'grant execute on all functions in schema app_private to service_role';
    execute 'grant execute on function app_private.has_admin_role(text) to authenticated';
    execute 'grant execute on function app_private.level_from_rsrp(int, text) to authenticated';
    execute 'grant execute on function app_private.touch_updated_at() to authenticated';
    execute 'grant execute on function app_private.route_defaults() to authenticated';
    execute 'grant execute on function app_private.signal_sample_defaults() to authenticated';
    execute 'grant execute on function app_private.buddy_session_defaults() to authenticated';
    execute 'grant execute on function app_private.today_vn() to authenticated';
  end if;
end $$;

do $$
declare
  f regprocedure;
begin
  for f in
    select p.oid::regprocedure
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    join pg_language l on l.oid = p.prolang
    where n.nspname in ('public', 'app_private')
      and p.prokind = 'f'
      and l.lanname in ('sql', 'plpgsql')
      and p.proowner = (select oid from pg_roles where rolname = current_user)
      and not exists (select 1 from pg_depend d
                       where d.classid = 'pg_proc'::regclass and d.objid = p.oid and d.deptype = 'e')
  loop
    execute format('alter function %s set jit = off', f);
  end loop;
end $$;

comment on function public.admin_pack_changes(text, text) is
  'Unpublished changes of every route × carrier pack (facilities/services added, removed with reason, updated).';
comment on function public.admin_publish_pack(text, text, text, boolean) is
  'Publishes a new pack version; returns the current one with unchanged = true when nothing changed (p_force to override).';

-- >>> 20260929000100_quota_ledger.sql
-- =============================================================================
-- NomadCare v2 — 20260929000100 alert quota ledger + route region_en (wave 3d).
-- Owner: backend. Idempotent; runs after 20260928000100_hardening.sql and
-- replaces some of its functions (same signatures, grants are kept).
--   Alert quota ledger (anti e-mail relay)
--   * app_private.alert_ledger: one row per alert / all-clear e-mail, keyed by a
--     salted sha256 of the normalised recipient address (lower case, "+tag"
--     dropped; Gmail dots dropped, googlemail.com = gmail.com). No plaintext
--     address, no foreign key to sessions or devices: device.erase and the
--     session retention do not touch it; nc_cleanup() prunes rows > 48 h.
--   * alert_quota_block() counts that ledger instead of the sessions' events:
--     overdue / SOS / manual alerts AND all-clear e-mails, claimed (in flight)
--     or sent, per recipient (limit_alert_recipient_24h, default 3) and for all
--     recipients (limit_alert_global_1h, default 50). Failed sends and demo
--     recipients (example.com, *.test, …) do not count. All-clear e-mails are
--     counted but never held back: at most one follows each alert that went out.
--   * nc_alert_claim() writes a 'claimed' row for every alert it hands out
--     (claims are serialised with an advisory lock, so a cron tick and an SOS
--     cannot both pass the same quota); nc_alert_result() marks it sent /
--     failed / demo, or records a send / all-clear that had no claim row;
--     op_device_erase() records the inline all-clear it queues and unlinks the
--     erased sessions from their open claims (the claims keep counting).
--   Routes
--   * routes.region_en (English region label) in list_routes() and in the pack
--     route object (app_private.build_pack). Packs published before this
--     migration lack it until they are published again; clients fall back to
--     region.
-- =============================================================================
set search_path = public, extensions;

-- =============================================================================
-- 1. Schema
-- =============================================================================
create table if not exists app_private.alert_ledger (
  id             bigint generated always as identity primary key,
  recipient_hash text        not null,          -- app_private.recipient_hash(e-mail)
  kind           text        not null check (kind in ('alert', 'all_clear')),
  reason         text,                          -- overdue | sos | manual | resolved
  source         text,                          -- cron | manual | erase | …
  status         text        not null default 'sent'
                 check (status in ('claimed', 'sent', 'failed', 'demo')),
  session_ref    uuid,                          -- open claim only (no FK); cleared by the result or device.erase
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
comment on table app_private.alert_ledger is
  'Every alert / all-clear e-mail (claimed, sent, failed, demo) by salted sha256 of the normalised recipient; '
  'no plaintext address, no FK. Basis of the abuse quotas; survives device.erase; pruned after 48 h by nc_cleanup().';
create index if not exists alert_ledger_recipient_idx on app_private.alert_ledger (recipient_hash, created_at desc);
create index if not exists alert_ledger_created_idx   on app_private.alert_ledger (created_at desc);
create index if not exists alert_ledger_claim_idx     on app_private.alert_ledger (session_ref) where session_ref is not null;

alter table app_private.alert_ledger enable row level security;
revoke all on app_private.alert_ledger from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on app_private.alert_ledger from anon, authenticated';
    execute 'grant select on app_private.alert_ledger to service_role';
  end if;
end $$;

-- per-project salt for the recipient hashes (never exposed)
insert into app_private.settings (key, value)
values ('ledger_salt', encode(gen_random_bytes(16), 'hex'))
on conflict (key) do nothing;

alter table public.routes add column if not exists region_en text;
comment on column public.routes.region_en is 'English label of the region (null: clients show region).';
-- the three demo routes (supabase/seed.sql sets the same values; real edits are kept)
update public.routes r set region_en = v.region_en
from (values ('khanh-le',          'Lâm Đồng – Khánh Hòa'),
             ('ta-nang-phan-dung', 'Lâm Đồng'),
             ('ha-giang-loop',     'Tuyên Quang (former Hà Giang province)')) as v(id, region_en)
where r.id = v.id and r.region_en is null;

-- =============================================================================
-- 2. Ledger helpers + quota
-- =============================================================================

-- Canonical recipient for counting: trimmed, lower case, "+tag" dropped from the
-- local part; Gmail ignores dots and googlemail.com is gmail.com. Null for
-- null / blank. Mirrors normalizeEmail() in assets/js/services/backend-local.js.
create or replace function app_private.normalize_email(p text)
returns text
language sql
immutable
set search_path = public, extensions, pg_temp
as $$
  select case
    when x.v is null then null
    when position('@' in x.v) = 0 then x.v
    else (select case when y.dom in ('gmail.com', 'googlemail.com')
                      then replace(y.loc, '.', '') || '@gmail.com'
                      else y.loc || '@' || y.dom end
          from (select coalesce(nullif(split_part(regexp_replace(x.v, '@[^@]*$', ''), '+', 1), ''),
                                regexp_replace(x.v, '@[^@]*$', '')) as loc,
                       rtrim(substring(x.v from '@([^@]*)$'), '.') as dom) y)
  end
  from (select nullif(lower(btrim(p)), '') as v) x
$$;

-- sha256(ledger_salt | normalised address) as hex; null for null / blank.
create or replace function app_private.recipient_hash(p_email text)
returns text
language sql
stable
security definer
set search_path = public, extensions, pg_temp
as $$
  select case when n.e is not null
              then encode(digest(coalesce(app_private.setting('ledger_salt'), '') || '|' || n.e, 'sha256'), 'hex') end
  from (select app_private.normalize_email(p_email) as e) n
$$;

-- Records one e-mail in the ledger (demo recipients are never e-mailed for
-- real and are not recorded). Returns the ledger id or null.
create or replace function app_private.ledger_add(p_email text, p_kind text, p_reason text, p_source text,
                                                  p_status text default 'sent', p_session uuid default null)
returns bigint
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_id bigint;
begin
  if p_email is null or btrim(p_email) = '' or app_private.is_reserved_email(p_email) then
    return null;
  end if;
  insert into app_private.alert_ledger (recipient_hash, kind, reason, source, status, session_ref)
  values (app_private.recipient_hash(p_email), p_kind, p_reason, p_source, coalesce(p_status, 'sent'),
          case when coalesce(p_status, 'sent') = 'claimed' then p_session end)
  returning id into v_id;
  return v_id;
end $$;

-- Why an alert e-mail to p_email must not go out now: 'recipient_24h' |
-- 'global_1h' | null. Counts the ledger (alerts and all-clears, claimed or
-- sent), which device.erase cannot delete.
create or replace function app_private.alert_quota_block(p_email text)
returns text
language sql
stable
security definer
set search_path = public, extensions, pg_temp
as $$
  select case
    when p_email is null or app_private.is_reserved_email(p_email) then null
    when (select count(*) from app_private.alert_ledger l
           where l.recipient_hash = app_private.recipient_hash(p_email)
             and l.status in ('claimed', 'sent')
             and l.created_at > now() - interval '24 hours')
         >= app_private.limit_value('limit_alert_recipient_24h', 3) then 'recipient_24h'
    when (select count(*) from app_private.alert_ledger l
           where l.status in ('claimed', 'sent')
             and l.created_at > now() - interval '1 hour')
         >= app_private.limit_value('limit_alert_global_1h', 50) then 'global_1h'
  end
$$;

-- One-time backfill: e-mails of the last 48 h recorded before the ledger existed.
do $$
begin
  if not exists (select 1 from app_private.settings where key = 'alert_ledger_backfilled') then
    insert into app_private.alert_ledger (recipient_hash, kind, reason, source, status, created_at, updated_at)
    select app_private.recipient_hash(b.recipient_email),
           case when e.meta ->> 'type' = 'resolved' then 'all_clear' else 'alert' end,
           case when e.meta ->> 'type' = 'resolved' then 'resolved' else coalesce(e.meta ->> 'reason', 'overdue') end,
           coalesce(e.meta ->> 'trigger', 'cron'), 'sent', e.received_at, e.received_at
    from public.checkin_events e
    join public.buddy_sessions b on b.id = e.session_id
    where e.kind = 'alert_sent'
      and coalesce(e.meta ->> 'provider', '') <> 'demo'
      and e.received_at > now() - interval '48 hours'
      and b.recipient_email is not null
      and not app_private.is_reserved_email(b.recipient_email);
    insert into app_private.settings (key, value) values ('alert_ledger_backfilled', now()::text)
    on conflict (key) do nothing;
  end if;
end $$;

-- =============================================================================
-- 3. device.erase: inline all-clear recorded, open claims unlinked
-- =============================================================================
-- As 20260928000100 + the ledger. Open sessions are closed WITHOUT an alert and
-- deleted with their events; community reports stay but lose the device link;
-- device_ops and the device row go. If a recipient was alerted and never got
-- the all-clear, it is sent from an inline payload (the Edge Function cannot
-- read the deleted row) and counted in the ledger.
create or replace function app_private.op_device_erase(p_device public.devices, p_data jsonb, p_op_id uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  s          public.buddy_sessions%rowtype;
  v_sessions int := 0;
  v_events   int := 0;
  v_subs     int := 0;
  v_clear    int := 0;
  v_req      bigint;
  v_audit    text := current_setting('nc.audit', true);
begin
  for s in select * from public.buddy_sessions where device_id = p_device.id order by started_at for update loop
    if s.recipient_email is not null and app_private.all_clear_pending(s.id) then
      v_req := app_private.notify_deadman(jsonb_build_object(
        'type', 'resolved', 'session_id', s.id, 'source', 'erase',
        'inline', app_private.alert_payload(s, 'resolved', now())));
      if v_req is not null then
        perform app_private.ledger_add(s.recipient_email, 'all_clear', 'resolved', 'erase', 'sent', null);
      end if;
      v_clear := v_clear + 1;
    end if;
    if s.status <> 'closed' then
      update public.buddy_sessions set status = 'closed', closed_at = now() where id = s.id;
    end if;
  end loop;
  -- claims in flight keep counting against the quota, without the session link
  update app_private.alert_ledger set session_ref = null, updated_at = now()
   where session_ref in (select b.id from public.buddy_sessions b where b.device_id = p_device.id);
  select count(*)::int into v_events
  from public.checkin_events e join public.buddy_sessions b on b.id = e.session_id
  where b.device_id = p_device.id;
  delete from public.buddy_sessions where device_id = p_device.id;          -- events cascade
  get diagnostics v_sessions = row_count;
  -- unlink community reports without copying the device id into the audit trail,
  -- and drop it from the snapshots the trail already holds
  perform set_config('nc.audit', 'off', true);
  update public.facility_submissions set device_id = null where device_id = p_device.id;
  get diagnostics v_subs = row_count;
  perform set_config('nc.audit', coalesce(nullif(v_audit, ''), 'on'), true);
  update public.audit_log set details = jsonb_set(details, '{row,device_id}', 'null'::jsonb)
   where entity = 'facility_submissions' and details -> 'row' ->> 'device_id' = p_device.id::text;
  delete from public.devices where id = p_device.id;                         -- device_ops cascade
  return jsonb_build_object('erased', true, 'sessions_deleted', v_sessions, 'events_deleted', v_events,
                            'submissions_unlinked', v_subs, 'all_clear_sent', v_clear, 'received_at', now());
end $$;

-- =============================================================================
-- 4. Cron / Edge Function API: ledger writes, retention
-- =============================================================================

-- Daily retention job (as 20260928000100 + ledger rows older than 48 h).
create or replace function public.nc_cleanup()
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_ops      int;
  v_sessions int;
  v_events   int;
  v_ips      int;
  v_ledger   int;
begin
  if not (app_private.is_trusted_caller() or public.is_admin()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  delete from public.device_ops where received_at < now() - interval '30 days';
  get diagnostics v_ops = row_count;
  -- closed > 30 days ago, or abandoned (no change for 90 days): session + events (cascade)
  with old as (
    select s.id from public.buddy_sessions s
    where (s.status = 'closed' and coalesce(s.closed_at, s.updated_at) < now() - interval '30 days')
       or (s.status <> 'closed' and s.updated_at < now() - interval '90 days')
  ), ev as (
    select count(*)::int as n from public.checkin_events e where e.session_id in (select id from old)
  ), del as (
    delete from public.buddy_sessions s using old where s.id = old.id returning 1
  )
  select (select count(*)::int from del), (select n from ev) into v_sessions, v_events;
  update public.devices set reg_ip_hash = null
   where reg_ip_hash is not null and created_at < now() - interval '24 hours';
  get diagnostics v_ips = row_count;
  delete from app_private.alert_ledger where created_at < now() - interval '48 hours';
  get diagnostics v_ledger = row_count;
  return jsonb_build_object('device_ops_deleted', v_ops, 'sessions_deleted', v_sessions,
                            'events_deleted', v_events, 'ip_hashes_cleared', v_ips,
                            'ledger_deleted', v_ledger, 'at', now());
end $$;

-- Claims sessions to alert (as 20260928000100) + a ledger row per claimed
-- alert. The cron path is serialised (advisory lock) so that parallel callers
-- (cron tick, SOS, device-detected overdue) see each other's claims.
create or replace function public.nc_alert_claim(p_session_id uuid default null, p_type text default 'overdue',
                                                 p_force boolean default false, p_limit int default 25,
                                                 p_actor uuid default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  s        public.buddy_sessions%rowtype;
  v_out    jsonb := '[]'::jsonb;
  v_now    timestamptz := now();
  v_alert  timestamptz;
  v_clear  timestamptz;
  v_item   jsonb;
begin
  if not app_private.is_trusted_caller() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if p_type not in ('overdue', 'resolved') then
    raise exception 'invalid_type' using errcode = '22023', detail = coalesce(p_type, 'null');
  end if;
  perform app_private.set_actor(p_actor);

  if p_type = 'resolved' then
    -- recorded in the ledger by nc_alert_result once it went out
    select * into s from public.buddy_sessions where id = p_session_id;
    if not found or s.recipient_email is null or s.status not in ('active', 'closed') then
      return v_out;
    end if;
    select max(e.received_at) filter (where coalesce(e.meta ->> 'type', 'overdue') <> 'resolved'),
           max(e.received_at) filter (where e.meta ->> 'type' = 'resolved')
      into v_alert, v_clear
    from public.checkin_events e
    where e.session_id = s.id and e.kind = 'alert_sent';
    if p_force or (v_alert is not null and (v_clear is null or v_clear < v_alert)) then
      v_out := jsonb_build_array(app_private.alert_payload(s, 'resolved', v_now));
    end if;
    return v_out;
  end if;

  if p_session_id is not null and p_force then
    -- manual trigger by an admin: never rate-limited, but counted
    select * into s from public.buddy_sessions where id = p_session_id for update;
    if not found or s.status = 'closed' or s.recipient_email is null then
      return v_out;
    end if;
    if s.status in ('overdue', 'active') then
      update public.buddy_sessions set alerted_at = v_now where id = s.id returning * into s;
    end if;
    v_item := app_private.alert_payload(s, 'overdue', v_now);
    perform app_private.ledger_add(s.recipient_email, 'alert', v_item ->> 'reason', 'manual', 'claimed', s.id);
    return jsonb_build_array(v_item);
  end if;

  perform pg_advisory_xact_lock(hashtext('nomadcare.nc_alert_claim'));
  perform app_private.flag_rate_limited();
  for s in
    select * from public.buddy_sessions b
    where app_private.alert_due(b) and (p_session_id is null or b.id = p_session_id)
    order by b.next_due_at nulls last
    limit greatest(1, least(coalesce(p_limit, 25), 100))
    for update skip locked
  loop
    -- an earlier claim of this batch may have used the recipient's quota
    if app_private.alert_quota_block(s.recipient_email) is not null then
      perform app_private.flag_rate_limited(s.id);
      continue;
    end if;
    update public.buddy_sessions set alerted_at = v_now where id = s.id returning * into s;
    v_item := app_private.alert_payload(s, 'overdue', v_now);
    perform app_private.ledger_add(s.recipient_email, 'alert', v_item ->> 'reason', 'cron', 'claimed', s.id);
    v_out := v_out || jsonb_build_array(v_item);
  end loop;
  return v_out;
end $$;

-- Records the outcome of one e-mail (as 20260928000100) + the ledger: the open
-- claim of this session becomes sent / failed / demo; a send without a claim
-- (all-clear, older Edge Function) is added as sent.
create or replace function public.nc_alert_result(p_session_id uuid, p_ok boolean, p_type text default 'overdue',
                                                  p_provider text default 'resend', p_provider_id text default null,
                                                  p_error text default null, p_trigger text default 'cron',
                                                  p_actor uuid default null, p_reason text default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  s           public.buddy_sessions%rowtype;
  v_meta      jsonb;
  v_label     text;
  v_all_clear boolean := false;
  v_kind      text := case when coalesce(p_type, 'overdue') = 'resolved' then 'all_clear' else 'alert' end;
  v_state     text := case when not coalesce(p_ok, false) then 'failed' when p_provider = 'demo' then 'demo' else 'sent' end;
begin
  if not app_private.is_trusted_caller() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  v_label := app_private.set_actor(p_actor);
  select * into s from public.buddy_sessions where id = p_session_id for update;
  if not found then
    raise exception 'session_not_found' using errcode = 'P0002';
  end if;
  v_meta := jsonb_strip_nulls(jsonb_build_object(
    'type', coalesce(p_type, 'overdue'), 'provider', p_provider, 'id', p_provider_id,
    'error', left(p_error, 500), 'trigger', p_trigger,
    'reason', case when p_ok then p_reason else 'send_failed' end,
    'alert_reason', case when not p_ok then p_reason end,
    'actor', v_label));

  update app_private.alert_ledger l set status = v_state, session_ref = null, updated_at = now()
   where l.id = (select x.id from app_private.alert_ledger x
                  where x.session_ref = s.id and x.kind = v_kind and x.status = 'claimed'
                  order by x.created_at desc, x.id desc limit 1);
  if not found and v_state = 'sent' then
    perform app_private.ledger_add(s.recipient_email, v_kind,
                                   case when v_kind = 'all_clear' then 'resolved' else coalesce(p_reason, 'overdue') end,
                                   coalesce(p_trigger, 'cron'), 'sent', null);
  end if;

  if coalesce(p_type, 'overdue') = 'overdue' then
    if p_ok then
      if s.status = 'overdue' and s.alert_reason = 'sos' and p_reason is not null and p_reason <> 'sos' then
        -- the traveller pressed SOS while the missed-check-in e-mail was on its way
        update public.buddy_sessions set alerted_at = null where id = s.id returning * into s;
      elsif s.status = 'overdue' or (p_trigger = 'manual' and s.status in ('active', 'alerted')) then
        update public.buddy_sessions set status = 'alerted', alerted_at = now()
         where id = s.id returning * into s;
      elsif s.status = 'active' then
        -- the traveller checked in while the email was being sent → follow up with "all clear"
        update public.buddy_sessions set alerted_at = null where id = s.id returning * into s;
        v_all_clear := true;
      end if;
    elsif s.status in ('overdue', 'active') then
      update public.buddy_sessions set alerted_at = null where id = s.id returning * into s;
    end if;
  end if;

  perform app_private.insert_event(s, case when p_ok then 'alert_sent' else 'alert_failed' end,
                                   null, null, null, null, now(), false, null, v_meta);
  if v_all_clear then
    perform app_private.notify_deadman(jsonb_build_object('session_id', s.id, 'type', 'resolved'));
  end if;
  return jsonb_build_object('session_id', s.id, 'status', s.status, 'alerted_at', s.alerted_at,
                            'alert_reason', s.alert_reason);
end $$;

-- =============================================================================
-- 5. Routes: region_en in the pack and the route catalogue
-- =============================================================================

-- Pack JSON (CONTRACT §8) for one route × carrier; as 0500 + route.region_en.
create or replace function app_private.build_pack(p_route_id text, p_carrier text,
                                                  p_version int, p_published_at timestamptz)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  r           public.routes%rowtype;
  v_corridor  geography;
  v_model     text;
  v_accuracy  numeric;
  v_holdout   int;
  v_acc_model text;
  v_nodes     jsonb;
  v_edges     jsonb;
  v_segments  jsonb;
  v_fac       jsonb;
  v_svc       jsonb;
  v_pack      jsonb;
  v_size      int;
  v_len       int;
begin
  select * into r from public.routes where id = p_route_id;
  if not found then
    raise exception 'route_not_found' using errcode = 'P0002', detail = coalesce(p_route_id, 'null');
  end if;
  if not exists (select 1 from public.carriers c where c.id = p_carrier) then
    raise exception 'carrier_not_found' using errcode = 'P0002', detail = coalesce(p_carrier, 'null');
  end if;

  v_corridor := app_private.route_corridor(p_route_id);

  select a.accuracy, a.holdout_n, a.model_version
    into v_accuracy, v_holdout, v_acc_model
  from public.route_accuracy a
  where a.route_id = p_route_id and a.carrier = p_carrier;

  select s.model_version into v_model
  from public.signal_segments s
  where s.route_id = p_route_id and s.carrier = p_carrier
  order by s.created_at desc, s.id desc
  limit 1;

  -- nodes, in travel order along the route line (then id): pickers and
  -- itineraries read naturally without re-sorting on the device
  select coalesce(jsonb_agg(jsonb_build_object(
           'id',      n.id,
           'name',    n.name,
           'name_en', n.name_en,
           'kind',    n.kind,
           'lat',     trim_scale(round(ST_Y(n.geom::geometry)::numeric, 6)),
           'lng',     trim_scale(round(ST_X(n.geom::geometry)::numeric, 6)))
           order by case when r.geom is not null then ST_LineLocatePoint(r.geom::geometry, n.geom::geometry) end,
                    n.id), '[]'::jsonb)
    into v_nodes
  from public.route_nodes n
  where n.route_id = p_route_id;

  -- edges (geometry oriented from → to)
  select coalesce(jsonb_agg(jsonb_build_object(
           'id',           e.id,
           'from',         e.from_node,
           'to',           e.to_node,
           'length_km',    trim_scale(round(e.length_km::numeric, 3)),
           'is_connector', e.is_connector,
           'geometry',     app_private.line_latlng(
                             case when ST_Distance(ST_StartPoint(e.geom::geometry)::geography, fn.geom)
                                     > ST_Distance(ST_EndPoint(e.geom::geometry)::geography, fn.geom)
                                  then ST_Reverse(e.geom::geometry)
                                  else e.geom::geometry end)) order by e.id), '[]'::jsonb)
    into v_edges
  from public.route_edges e
  join public.route_nodes fn on fn.id = e.from_node
  where e.route_id = p_route_id;

  -- segments, grouped per edge
  with segs as (
    select s.edge_id, s.seq, s.from_km, s.to_km, s.level, s.confidence
    from public.signal_segments s
    join public.route_edges e on e.id = s.edge_id and e.route_id = p_route_id
    where s.route_id = p_route_id
      and s.carrier = p_carrier
      and s.model_version is not distinct from v_model
    union all
    select e.id, 0, 0::numeric, e.length_km, 'uncertain', 0::numeric
    from public.route_edges e
    where e.route_id = p_route_id
      and not exists (select 1 from public.signal_segments s
                       where s.edge_id = e.id and s.carrier = p_carrier
                         and s.model_version is not distinct from v_model)
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'edge_id',    g.edge_id,
           'seq',        g.seq,
           'from_km',    trim_scale(round(g.from_km::numeric, 3)),
           'to_km',      trim_scale(round(g.to_km::numeric, 3)),
           'level',      g.level,
           'confidence', trim_scale(round(g.confidence::numeric, 3))) order by g.edge_id, g.seq, g.from_km), '[]'::jsonb)
    into v_segments
  from segs g;

  -- verified facilities of the route (or untagged within the corridor)
  select coalesce(jsonb_agg(app_private.facility_pack_json(f) order by f.id), '[]'::jsonb)
    into v_fac
  from public.facilities f
  where f.status = 'verified'
    and f.geom is not null
    and app_private.in_route(f.route_id, f.geom, p_route_id, v_corridor);

  -- active services
  select coalesce(jsonb_agg(app_private.service_pack_json(s) order by s.id), '[]'::jsonb)
    into v_svc
  from public.services s
  where s.status = 'active'
    and s.geom is not null
    and app_private.in_route(s.route_id, s.geom, p_route_id, v_corridor);

  v_pack := jsonb_build_object(
    'schema', 1,
    'route', jsonb_build_object(
      'id',             r.id,
      'name',           r.name,
      'name_en',        r.name_en,
      'region',         r.region,
      'region_en',      r.region_en,
      'travel_mode',    r.travel_mode,
      'length_km',      app_private.route_length_km(r.id),
      'color',          r.color,
      'bbox',           app_private.route_bbox(r.id),
      'description_vi', r.description_vi,
      'description_en', r.description_en),
    'carrier',       p_carrier,
    'version',       coalesce(p_version, 0),
    'published_at',  p_published_at,
    'model_version', coalesce(v_model, v_acc_model),
    'accuracy',      v_accuracy,
    'holdout_n',     coalesce(v_holdout, 0),
    'nodes',         v_nodes,
    'edges',         v_edges,
    'segments',      v_segments,
    'facilities',    v_fac,
    'services',      v_svc);

  -- size_bytes must describe the final text, which includes size_bytes itself.
  v_size := octet_length(v_pack::text);
  for i in 1 .. 5 loop
    v_len := octet_length((v_pack || jsonb_build_object('size_bytes', v_size))::text);
    exit when v_len = v_size;
    v_size := v_len;
  end loop;
  return v_pack || jsonb_build_object('size_bytes', v_size);
end $$;

-- =============================================================================
-- 5. Public read RPCs
-- =============================================================================


-- Route catalogue (as 0500 + region_en).
create or replace function public.list_routes()
returns jsonb
language sql
stable
security definer
set search_path = public, extensions, pg_temp
as $$
  select coalesce(jsonb_agg(q.item order by q.sort, q.id), '[]'::jsonb)
  from (
    select r.sort, r.id,
      jsonb_build_object(
        'id',             r.id,
        'name',           r.name,
        'name_en',        r.name_en,
        'region',         r.region,
        'region_en',      r.region_en,
        'travel_mode',    r.travel_mode,
        'length_km',      app_private.route_length_km(r.id),
        'color',          r.color,
        'bbox',           app_private.route_bbox(r.id),
        'description_vi', r.description_vi,
        'description_en', r.description_en,
        'verified_facilities', (
          select count(*)::int from public.facilities f
          where f.status = 'verified'
            and app_private.in_route(f.route_id, f.geom, r.id, cor.g)),
        'accuracy', (
          select coalesce(jsonb_object_agg(c.id, a.accuracy order by c.sort), '{}'::jsonb)
          from public.carriers c
          left join public.route_accuracy a on a.route_id = r.id and a.carrier = c.id),
        'packs', (
          select coalesce(jsonb_object_agg(c.id, (
                   select jsonb_build_object('version', p.version,
                                             'published_at', p.published_at,
                                             'size_bytes', p.size_bytes)
                   from public.data_packs p
                   where p.route_id = r.id and p.carrier = c.id and p.is_current
                   order by p.version desc limit 1) order by c.sort), '{}'::jsonb)
          from public.carriers c)
      ) as item
    from public.routes r
    cross join lateral (select app_private.route_corridor(r.id) as g) cor
    where r.is_active
  ) q
$$;

